window.MEFOS_FIXED_BANK.push(...[{"id":"neuro20261004-1.5.1-1","number":"1","statement":"¿Cuál de los siguientes núcleos NO se localiza en la protuberancia (puente de Varolio)?:","options":["Núcleo ambiguo","Núcleo prepósito","Complejo olivar superior","Locus coeruleus"],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de Infiltración Bulbar vs. Pontina: A professora Aitana adora testar o aluno colocando o Núcleo Ambiguos em listas de estruturas pontinas. O núcleo ambiguo é uma coluna motora branquial localizada exclusivamente no bulbo raquídeo (origem motora dos nervos IX, X e XI). Em contrapartida, o locus coeruleus (noradrenérgico), o núcleo prepósito (integração do olhar) e o complexo olivar superior (audição) são estritamente pontinos.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada N-001 / G0017 del banco canónico | archivos: Todos os exames de Neuro EXTRACAO(1).pdf; Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte2.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #166) / ex. 2 (respuestas).pdf (Pregunta #13) / 09-23 Clase_ Neuroanatomía del Tronco Encefálico","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-2","number":"2","statement":"Señale cuál de los siguientes conjuntos de estructuras NO se encuentra en el bulbo raquídeo:","options":["Oliva inferior y núcleo grácil","Núcleos parabraquiales","Núcleo ambiguo y pirámides bulbares","Fibras arciformes internas"],"answer":1,"explanation":"No incluida en el material.","hack":"Hack do Intruso Pontino-Mesencefálico: Os núcleos parabraquiais (envolvidos no processamento gustativo, visceral e dor) situam-se na região dorsal da protuberância superior, abraçando o pedúnculo cerebeloso superior na transição com o mesencéfalo. NUNCA estão localizados no bulbo raquídeo.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada N-002 / G0018 del banco canónico | archivos: Todos os exames de Neuro EXTRACAO(1).pdf; Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte2.pdf | referencias indicadas: ex. 2021 (respuestas).pdf (Pregunta #14) / examenes neuro compl (1).pdf (Pregunta #13) / 09- 18 Clase_ Tronco del Encéfalo","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-3","number":"3","statement":"Con relación a la descripción anatómica y limites del tronco del encéfalo, es FALSO que:","options":["Las pirámides se localizan a ambos lados de la fisura media anterior bulbar, mientras que los tubérculos gráciles están a ambos lados del surco medio posterior.","La fosa romboidea forma el suelo del cuarto ventrículo en la parte posterior del tronco del encéfalo.","El surco basilar discurre longitudinalmente sobre la línea media anterior de la protuberancia.","Los colículos (tubérculos cuadrigéminos) se localizan ventrales al acueducto mesencefálico."],"answer":3,"explanation":"No incluida en el material.","hack":"Hack de Mentira Direcional (Tectum vs. Tegmentum): Os colículos superiores e inferiores constituem a lâmina cuadrigémina ou TECTUM (tecto), situado DORSAL / POSTERIOR ao acueduto cerebral de Silvio. A região ventral ao acueduto é o tegmento e a base (pedúnculos cerebrais).","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada N-003 / G0020 del banco canónico | archivos: Todos os exames de Neuro EXTRACAO(1).pdf; Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte2.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #164) / perguntas neuro julio exame.docx (Pregunta #18) / 09-24 Clase_ Estructuras del Mesencéfalo","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-4","number":"4","statement":"Indica la relación CORRECTA sobre la localización específica de los siguientes núcleos del tronco del encéfalo:","options":["Núcleo cuneiforme — Región medial en la parte anterior del bulbo raquídeo.","Núcleos interpedunculares — Región medial en la parte anterior (fosa interpeduncular) del mesencéfalo.","Área tegmental ventral — Alrededor del acueducto mesencefálico.","Núcleo vestibular lateral — Región anterior de la protuberancia."],"answer":1,"explanation":"No incluida en el material.","hack":"Hack de Microtopografia Mesencefálica: Núcleos interpedunculares: Fica na fossa interpeduncular (face ventral/anterior do mesencéfalo entre os pés dos pedúnculos cerebrais). Área em redor do acueduto: Chama-se Sustância Cinzenta Periacuedutal (PAG), e não Área Tegmental Ventral. Núcleo cuneiforme: Fica no bulbo posterior/dorsal.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada N-004 / G0024 del banco canónico | archivos: Todos os exames de Neuro EXTRACAO(1).pdf; Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte2.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #165) / perguntas neuro julio exame.docx (Pregunta #19) / 09-25 Clase_ Neuroanatomía del Mesencéfalo","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-5","number":"5","statement":"Señale la afirmación CORRECTA sobre la anatomía microscópica y macroscópica del suelo del cuarto ventrículo (fosa romboidea):","options":["Los núcleos de los nervios hipogloso (XII) y vago (X) provocan elevaciones superficiales visibles denominadas trígono del hipogloso y trígono del vago en la porción bulbar 7 8.","Los colículos inferiores forman la eminencia medial de la protuberancia 8.","Los tubérculos grácil y cuneiforme constituyen las paredes laterales del acueducto mesencefálico 8.","El colículo facial es producido por el núcleo del nervio oculomotor rodeado por el nervio troclear."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de las Huellas Ventriculares (Trígonos Bulbares): En la mitad inferior (porción bulbar) de la fosa romboidea, la presencia de los núcleos subyacentes proyecta relieves en forma de triángulo perfectamente identificables en la superficie: Trígono del hipogloso: Medial, sobre el núcleo del XII par 8. Trígono del vago: Intermedio/inferior, sobre el núcleo motor dorsal del X par 8. Área vestibular: Lateral, sobre los núcleos vestibulares 8. (Pregunta fija de examen para verificar si el alumno diferencia la porción bulbar de la pontina en el suelo ventricular) 7 8.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada N-005 / G0027 del banco canónico | archivos: Todos os exames de Neuro EXTRACAO(1).pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #201) / perguntas neuro julio exame.docx (Pregunta #53) / Tema 1.5.1 - Tronco del encéfalo","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-6","number":"6","statement":"En la división regional anteroposterior del tronco del encéfalo, el tectum (techo) es una región anatómica presente EXCLUSIVAMENTE en:","options":["El mesencéfalo (dorsal al acueducto cerebral, conteniendo los colículos superiores e inferiores) 3 12.","El bulbo raquídeo (dorsal a las pirámides).","La protuberancia (dorsal a los núcleos pontinos).","El diencéfalo (dorsal al tercer ventrículo)."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de Exclusividad del Tectum: Área Basilar (Anterior): Presente en mesencéfalo, puente y bulbo (alberga vías motoras descendentes) 3 12. Área Tegmental / Tegmento (Intermedia): Presente en mesencéfalo, puente y bulbo (alberga núcleos de pares craneales y formación reticular) 3 12. Área Tectal / Tectum (Dorsal al LCR): Existe ÚNICAMENTE en el mesencéfalo (formado por la lámina cuadrigémina / colículos) 3 12. En el puente y bulbo, la región posterior al tegmento es abierta y corresponde al cuarto ventrículo 3 12.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada N-006 / G0031 del banco canónico | archivos: Todos os exames de Neuro EXTRACAO(1).pdf | referencias indicadas: 09-22 Clase_ Anatomía del tronco del encéfalo / TEMA 3 – TRONCO DEL ENCÉFALO.pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-7","number":"7","statement":"Sobre la Formación Reticular (FR) del tronco del encéfalo y sus subdivisiones funcionales, señale la afirmación CORRECTA 14:","options":["La formación reticular pontina rostral y mesencefálica modula la actividad del prosencéfalo y los estados de consciencia (Sistema Activador Reticular Ascendente - SARA) 15 16.","La formación reticular bulbar solo contiene motoneuronas somáticas voluntarias 15.","La formación reticular no participa en la modulación de las vías del dolor 15.","Se localiza exclusivamente en la cara anterior de las pirámides bulbares 15."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de la Bipartición Funcional de la Formación Reticular: FR Rostral (Mesencéfalo y Puente rostral): Constituye el SARA (Sistema Activador Reticular Ascendente) 15 16 -> Proyecta al tálamo y corteza para mantener la alerta y la consciencia 15. FR Caudal (Puente caudal y Bulbo): Trabaja en coordinación con los núcleos autonómicos viscerales (cardiovascular, respiratorio) y modula motoneuronas inferiores mediante los tractos reticuloespinales 15 16.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada N-007 / G0033 del banco canónico | archivos: Todos os exames de Neuro EXTRACAO(1).pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #168) / Preguntas temas 3,4,5,6.pdf (Pregunta #6) / TEMA 3 – TRONCO DEL ENCÉFALO.pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-8","number":"8","statement":"¿Cuál de las siguientes estructuras o núcleos NO se encuentra en el mesencéfalo? 15:","options":["Los pedúnculos cerebrales 17","La sustancia negra 17","El acueducto cerebral (de Silvio) 17","Locus coeruleus 17"],"answer":3,"explanation":"No incluida en el material.","hack":"Hack del Intruso Noradrenérgico: El Locus Coeruleus es el principal núcleo noradrenérgico del encéfalo y se ubica en el tegmento de la protuberancia (puente), en la porción superior del suelo del IV ventrículo 17 18. NUNCA forma parte del mesencéfalo 17. Por el contrario, los pedúnculos cerebrales (porción basilar/anterior), la sustancia negra y el acueducto de Silvio son elementos exclusivos del mesencéfalo 17 19.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada N-008 / G0034 del banco canónico | archivos: Todos os exames de Neuro EXTRACAO(1).pdf | referencias indicadas: ex. 2021 (respuestas).pdf (Pregunta #15) / ex. 2021 (sin respuestas).pdf (Pregunta #15) / NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-9","number":"9","statement":"Respecto a los núcleos moduladores y neuroquímicos del tronco del encéfalo, señale la relación CORRECTA 24:","options":["Núcleos del Rafe — Sistema serotoninérgico localizado en la franja medial a lo largo del tronco del encéfalo 25 26.","Núcleo olivar inferior — Relacionado exclusivamente con la localización de la fuente sonora en el plano horizontal 26.","Área tegmental ventral — Componente del sistema límbico localizado en la porción posterior del tectum mesencefálico 26.","Locus coeruleus — Núcleo dopaminérgico ubicado en las pirámides bulbares 18 26."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de Mapeo Transmisor de la Banca: Núcleos del Rafe: Se sitúan en la línea media (mediales) e sintetizan serotonina (5-HT) 25 26. Oliva Superior (no la inferior): Procesa la localización del sonido en el plano horizontal 26. Área Tegmental Ventral: Contiene neuronas dopaminérgicas (DA) 19 en la cara VENTRAL del tegmento mesencefálico (no en el tectum) 19 26.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada N-009 / G0036 del banco canónico | archivos: Todos os exames de Neuro EXTRACAO(1).pdf | referencias indicadas: examenes neuro compl (1).pdf (Pregunta #20) / ex. 2 (respuestas).pdf / TEMA 3 – TRONCO DEL ENCÉFALO.pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-10","number":"10","statement":"Indica la afirmación FALSA sobre las relaciones anatómicas en las secciones del tronco del encéfalo 18 30:","options":["El tubérculo grácil es medial con respecto al tubérculo cuneiforme 22.","Las pirámides bulbares son ventrales con respecto al núcleo cuneiforme 30.","El locus coeruleus es un sistema difuso noradrenérgico que se localiza a nivel de la protuberancia 18 30.","En un corte transversal a nivel del bulbo raquídeo encontraremos el lemnisco lateral 16 30."],"answer":3,"explanation":"No incluida en el material.","hack":"Hack de la Ausencia Bulbar del Lemnisco Lateral: El lemnisco lateral es un tracto exclusivamente auditivo que nace en la PROTUBERANCIA (a partir de las fibras cruzadas del cuerpo trapezoide y núcleos cocleares/oliva superior) y asciende hacia el colículo inferior del mesencéfalo 31. Por consiguiente, jamás estará presente en ningún corte del bulbo raquídeo 15.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada N-010 / G0039 del banco canónico | archivos: Todos os exames de Neuro EXTRACAO(1).pdf | referencias indicadas: ex. 2022 (sin respuestas) 2.pdf (Pregunta #19) / Recopilación preguntas neuro (1).pdf / NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-11","number":"11","statement":"De las siguientes estructuras pertenecientes al tronco del encéfalo, ¿cuál se localiza en la posición más DORSAL y CAUDAL en la cara posterior del bulbo raquídeo?:","options":["Núcleo olivar inferior.","Pedúnculos cerebrales.","Colículos inferiores.","Núcleo cuneiforme."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de Disposición Anatómica Absoluta: En la clave oficial fijada por la banca examinadora para esta pregunta, el Núcleo Olivar Inferior se clasifica como la estructura más caudal del conjunto evaluado en comparación con estructuras mesencefálicas (colículos y pedúnculos cerebrales) y pontinas.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada N-011 / G0045 del banco canónico | archivos: Todos os exames de Neuro EXTRACAO(1).pdf; Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte3.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #8) / Recopilación preguntas neuro (1).pdf / 09-18 Clase_ Tronco del Encéfalo","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-12","number":"12","statement":"En un esquema anatómico del tronco del encéfalo en visión lateral o sagital, señale la identificación CORRECTA de las estructuras numeradas 1, 2 y 3:","options":["1. Colículo inferior, 2. Fosa romboidea (suelo del IV ventrículo), 3. Oliva bulbar.","1. Colículo superior, 2. Techo del IV ventrículo, 3. Pirámides del bulbo.","1. Cuerpos mamilares, 2. Fosa romboidea, 3. Oliva.","1. Glándula pineal, 2. Acueducto cerebral, 3. Pirámides del bulbo."],"answer":0,"explanation":"[Explicación 1 (Todos os exames de Neuro EXTRACAO(1).pdf Q33)] Hack de Identificación de Imágenes de Examen: En las preguntas con esquemas anatómicos numerados del tronco del encéfalo (frecuentes en pruebas tipo test) 41: 1: Señala el colículo inferior (elevación caudal de la lámina cuadrigémina en el tectum mesencefálico). 2: Señala la fosa romboidea (superficie dorsal del puente y bulbo rostral que forma el suelo del IV ventrículo) 43. 3: Señala la oliva bulbar (saliente anterolateral producido por el complejo olivar inferior) 40. || [Explicación 2 (Neuro_Adicional_Parte3.pdf Q33)] Hack de Identificación de Imágenes de Examen: En las preguntas con esquemas anatómicos numerados del tronco del encéfalo (frecuentes en pruebas tipo test):: Señala el colículo inferior (elevación caudal de la lámina cuadrigémina en el tectum mesencefálico).: Señala la fosa romboidea (superficie dorsal del puente y bulbo rostral que forma el suelo del IV ventrículo).: Señala la oliva bulbar (saliente anterolateral producido por el complejo olivar inferior).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada N-012 / G0049 del banco canónico | archivos: Todos os exames de Neuro EXTRACAO(1).pdf; Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte3.pdf | referencias indicadas: ex. 2021 (respuestas).pdf (Pregunta #17) / NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf / 09-18 Clase_ Tronco del Encéfalo","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-13","number":"13","statement":"Sobre la neuroanatomía descriptiva del tronco del encéfalo, señale la afirmación CIERTA:","options":["La protuberancia contiene los núcleos de los nervios craneales V, VI, VII y VIII.","Los tubérculos gráciles se encuentran a ambos lados de la fisura media anterior del bulbo raquídeo.","Los colículos superiores están involucrados primariamente en la integración de la información auditiva.","La sustancia negra se encuentra en la superficie dorsal del mesencéfalo, constituyendo el tectum."],"answer":0,"explanation":"[Explicación 1 (Todos os exames de Neuro EXTRACAO(1).pdf Q34)] Hack del Mapeo de Pares Craneales por Segmentos: Mesencéfalo: Pares III y IV. Protuberancia / Puente: Pares V, VI, VII y VIII 44. Bulbo Raquídeo: Pares IX, X, XI y XII. Las opciones falsas invierten la fisura media anterior con la posterior (tubérculos gráciles) 45, asignan audición a los colículos superiores (es función de los inferiores) 44 y ubican la sustancia negra en la superficie dorsal (se ubica ventral/tegmental en el mesencéfalo) 44. || [Explicación 2 (Neuro_Adicional_Parte3.pdf Q34)] Hack del Mapeo de Pares Craneales por Segmentos: Mesencéfalo: Pares III y IV.Protuberancia / Puente: Pares V, VI, VII y VIII.Bulbo Raquídeo: Pares IX, X, XI y XII. Las opciones falsas invierten la fisura media anterior con la posterior (tubérculos gráciles), asignan audición a los colículos superiores (es función de los inferiores) y ubican la sustancia negra en la superficie dorsal (se ubica ventral/tegmental en el mesencéfalo).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada N-013 / G0050 del banco canónico | archivos: Todos os exames de Neuro EXTRACAO(1).pdf; Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte3.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #26) / wuolah-free-examen- 3.pdf / 09-23 Clase_ Neuroanatomía del Tronco Encefálico","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-14","number":"14","statement":"En relación con la organización funcional de la Formación Reticular a lo largo del eje del tronco del encéfalo, señale la afirmación CORRECTA:","options":["La formación reticular mesencefálica y pontina rostral modula la actividad del encéfalo anterior (alerta/SARA), mientras que la reticular pontina caudal y bulbar coordina funciones reflejas autonómicas y motoras.","La formación reticular se extiende únicamente a nivel del mesencéfalo.","La formación reticular no influye en los ritmos circadianos de sueño.","Los núcleos del rafe de la formación reticular liberan acetilcolina como neurotransmisor primario."],"answer":0,"explanation":"[Explicación 1 (Todos os exames de Neuro EXTRACAO(1).pdf Q35)] Hack de la Bipartición Funcional de la Formación Reticular: Porción Rostral (Mesencéfalo y Puente alto): Función moduladora ascendente sobre la corteza cerebral (SARA - estado de vigilia y consciencia) 46. Porción Caudal (Puente bajo y Bulbo): Función moduladora descendente sobre la médula y coordinación de centros motores viscerales (respiratorio, cardiovascular) 46. (Recordar: los núcleos del rafe liberan serotonina, NO acetilcolina). || [Explicación 2 (Neuro_Adicional_Parte3.pdf Q35)] Hack de la Bipartición Funcional de la Formación Reticular: Porción Rostral (Mesencéfalo y Puente alto): Función moduladora ascendente sobre la corteza cerebral (SARA - estado de vigilia y consciencia). Porción Caudal (Puente bajo y Bulbo): Función moduladora descendente sobre la médula y coordinación de centros motores viscerales (respiratorio, cardiovascular). (Recordar: los núcleos del rafe liberan serotonina, NO acetilcolina).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada N-014 / G0051 del banco canónico | archivos: Todos os exames de Neuro EXTRACAO(1).pdf; Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte3.pdf | referencias indicadas: wuolah-free-examen-3.pdf (Pregunta #6) / 09-18 Clase_ Tronco del Encéfalo / NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-15","number":"15","statement":"Señale la afirmación CORRECTA sobre las huellas o relieves ventriculares del suelo del cuarto ventrículo en el tronco del encéfalo:","options":["Los núcleos de los nervios vago (X) e hipogloso (XII) dejan una impronta en el suelo del cuarto ventrículo.","Los tubérculos gráciles se localizan a ambos lados de la fisura media anterior del bulbo.","Los colículos inferiores se localizan en el área tectal de la protuberancia.","El núcleo rojo se encuentra en una posición más dorsal que la sustancia gris periacueductal del mesencéfalo."],"answer":0,"explanation":"[Explicación 1 (Todos os exames de Neuro EXTRACAO(1).pdf Q36)] Hack de la Impronta del Suelo Ventricular (Pregunta Fija de Examen): En la porción inferior del suelo del IV ventrículo (fosa romboidea), los núcleos de origen del XII par (trígono del hipogloso) y del X par (trígono del vago) sobresalen produciendo elevaciones triangulares visibles (improntas) 47 49. Los colículos inferiores están en el mesencéfalo (no en la protuberancia) 48, y el núcleo rojo es ventral a la sustancia gris periacueductal 48. || [Explicación 2 (Neuro_Adicional_Parte3.pdf Q36)] Hack de la Impronta del Suelo Ventricular (Pregunta Fija de Examen): En la porción inferior del suelo del IV ventrículo (fosa romboidea), los núcleos de origen del XII par (trígono del hipogloso) y del X par (trígono del vago) sobresalen produciendo elevaciones triangulares visibles (improntas). Los colículos inferiores están en el mesencéfalo (no en la protuberancia), y el núcleo rojo es ventral a la sustancia gris periacueductal.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada N-015 / G0052 del banco canónico | archivos: Todos os exames de Neuro EXTRACAO(1).pdf; Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte3.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #201) / Examem 2025 outro modelo juneka.pdf (Pregunta #53) / 09-19C~1.MP3","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-16","number":"16","statement":"Señale cuáles de las siguientes estructuras NO se encuentran en el bulbo raquídeo:","options":["Núcleos parabraquiales","Oliva inferior y núcleo grácil","Núcleo ambiguo y pirámides bulbares","Fibras arciformes internas"],"answer":0,"explanation":"No incluida en el material.","hack":"Hack del Intruso Pontino: Los núcleos parabraquiales se localizan en la región dorsolateral de la protuberancia superior/alta (alrededor del pedúnculo cerebeloso superior) y participan en la integración gustativa, visceral y del dolor. La oliva inferior, los núcleos grácil y ambiguo, las pirámides y las fibras arciformes internas son componentes típicos y exclusivos del bulbo raquídeo.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada N-016 / G0057 del banco canónico | archivos: Todos os exames de Neuro EXTRACAO(1).pdf; Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte3.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #191) / ex. 2 (sin respuestas) (1, 2, 3 y 16).pdf (Pregunta #13) / 09-18 Clase_ Tronco del Encéfalo","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-17","number":"17","statement":"Respecto a la localización topográfica de los colículos superiores e inferiores en el tronco del encéfalo, señale la afirmación CORRECTA:","options":["Ambos se localizan en la parte posterior (tectum) del mesencéfalo.","Se encuentran en la parte anterior de la protuberancia.","El colículo superior se encuentra en el mesencéfalo y el inferior en la protuberancia.","Se sitúan en el tegmento ventral del bulbo raquídeo."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de Desplazamiento Falso de Colículos: Un distractor clásico de los exámenes (y enfatizado por la profesora Aitana) es afirmar que el colículo inferior \"se localiza en la protuberancia\". ¡FALSO! Tanto el colículo superior (visión) como el colículo inferior (audición) forman la lámina cuadrigémina en la cara DORSAL (tectum) del MESENCÉFALO.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada N-017 / G0060 del banco canónico | archivos: Todos os exames de Neuro EXTRACAO(1).pdf; Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte3.pdf | referencias indicadas: wuolah-free-tema-3-preguntas.pdf (Pregunta #5) / 09-24 Clase de Anatomía_ Estructuras del Mesencéfalo / NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-18","number":"18","statement":"De los siguientes núcleos situados en el tegmento de la protuberancia, ¿cuál participa activamente en el control de los movimientos oculares horizontales coordinados facilitando la fijación de la mirada?:","options":["Núcleo prepósito (prepósito del hipogloso).","Núcleo ambiguo.","Núcleo olivar inferior.","Núcleo rojo."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack del Núcleo Oculomotor Oculto: El núcleo prepósito se ubica en la zona dorsomedial de la protuberancia caudal (cerca del suelo del IV ventrículo y del núcleo del VI par). A pesar de su nombre histórico (\"prepósito del hipogloso\"), no interviene en los movimientos de la lengua, sino que es un integrador neural clave para el mantenimiento de la mirada conjugada horizontal.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada N-018 / G0061 del banco canónico | archivos: Todos os exames de Neuro EXTRACAO(1).pdf; Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte3.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #166) / 09-23 Clase_ Núcleos de la Protuberancia / wuolah-free-tema-4-preguntas.pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-19","number":"19","statement":"En la superficie anterior del tronco del encéfalo, señale la relación anatómica CORRECTA entre el surco o fisura y la estructura que discurre sobre él:","options":["El surco basilar discurre longitudinalmente por la línea media de la cara anterior de la protuberancia y aloja a la arteria basilar.","La fisura media anterior del bulbo aloja a la arteria cerebral media.","El surco pontoperpeduncular aloja a la vena de Galeno.","El surco retroolivar aloja al nervio troclear."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack del Surco Basilar: El surco basilar es la depresión longitudinal central de la protuberancia ventral producida por la presencia de la arteria basilar (formada por la unión de las dos arterias vertebrales). La fisura media anterior del bulbo aloja ramas de la arteria espinal anterior (no la ACM).","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada N-019 / G0063 del banco canónico | archivos: Todos os exames de Neuro EXTRACAO(1).pdf; Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte3.pdf | referencias indicadas: 09-22 Clase_ Anatomía del tronco del encéfalo / NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #164) / perguntas neuro julio exame.docx","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-20","number":"20","statement":"Respecto a la anatomía funcional de la porción posterior del tegmento pontino, el fascículo central del tegmento (tracto tegmental central) contiene fibras que conectan el núcleo rojo con la oliva inferior. ¿Qué cuadro neurológico hipercinético característico se produce tras una lesión destructiva fOCAL de este haz o del triángulo de Guillain-Mollaret?:","options":["Mioclonías del velo del paladar (mioclonus palatino / palatal).","Hemibalismo contralateral violentos.","Corea de Huntington.","Parálisis supranuclear progresiva."],"answer":0,"explanation":"[Explicación 1 (Todos os exames de Neuro EXTRACAO(1).pdf Q56)] Hack del Triángulo de Guillain-Mollaret (Dorsal Pontino-Mesencefálico): El triángulo de Guillain-Mollaret une el Núcleo Rojo -> Tracto Tegmental Central -> Oliva Inferior -> Fibras olivocerebelosas -> Núcleo Dentado del Cerebelo. Una interrupción en esta vía hipertrofia la oliva inferior y desencadena mioclonías rítmicas del velo del paladar (mioclonus palatino).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada N-020 / G0072 del banco canónico | archivos: Todos os exames de Neuro EXTRACAO(1).pdf; Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte3.pdf | referencias indicadas: 10-30 Clase magistral_ Desarrollo embrionario del sistema nervioso / TEMA 3 – TRONCO DEL ENCÉFALO.pdf / NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-21","number":"21","statement":"Señale la afirmación CORRECTA sobre la anatomía microscópica y macroscópica del suelo del cuarto ventrículo (fosa romboidea):","options":["Los núcleos de los nervios hipogloso (XII) y vago (X) provocan elevaciones superficiales visibles denominadas trígono del hipogloso y trígono del vago en la porción bulbar.","Los colículos inferiores forman la eminencia medial de la protuberancia.","Los tubérculos grácil y cuneiforme constituyen las paredes laterales del acueducto mesencefálico.","El colículo facial es producido por el núcleo del nervio oculomotor rodeado por el nervio troclear."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q11)] Hack de las Huellas Ventriculares (Trígonos Bulbares): En la mitad inferior (porción bulbar) de la fosa romboidea, la presencia de los núcleos subyacentes proyecta relieves en forma de triángulo perfectamente identificables en la superficie: Trígono del hipogloso: Medial, sobre el núcleo del XII par. Trígono del vago: Intermedio/inferior, sobre el núcleo motor dorsal del X par. Área vestibular: Lateral, sobre los núcleos vestibulares. (Pregunta fija de examen para verificar si el alumno diferencia la porción bulbar de la pontina en el suelo ventricular).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada N-021 / G0099 del banco canónico | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte3.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #201) / perguntas neuro julio exame.docx (Pregunta #53) / Tema 1.5.1 - Tronco del encéfalo","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-22","number":"22","statement":"En la división regional anteroposterior del tronco del encéfalo, el tectum (techo) es una región anatómica presente EXCLUSIVAMENTE en:","options":["El mesencéfalo (dorsal al acueducto cerebral, conteniendo los colículos superiores e inferiores).","El bulbo raquídeo (dorsal a las pirámides).","La protuberancia (dorsal a los núcleos pontinos).","El diencéfalo (dorsal al tercer ventrículo)."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q15)] Hack de Exclusividad del Tectum: Área Basilar (Anterior): Presente en mesencéfalo, puente y bulbo (alberga vías motoras descendentes). Área Tegmental / Tegmento (Intermedia): Presente en mesencéfalo, puente y bulbo (alberga núcleos de pares craneales y formación reticular). Área Tectal / Tectum (Dorsal al LCR): Existe ÚNICAMENTE en el mesencéfalo (formado por la lámina cuadrigémina / colículos). En el puente y bulbo, la región posterior al tegmento es abierta y corresponde al cuarto ventrículo.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada N-022 / G0103 del banco canónico | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte3.pdf | referencias indicadas: 09-22 Clase_ Anatomía del tronco del encéfalo / TEMA 3 – TRONCO DEL ENCÉFALO.pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-23","number":"23","statement":"Sobre la Formación Reticular (FR) del tronco del encéfalo y sus subdivisiones funcionales, señale la afirmación CORRECTA:","options":["La formación reticular pontina rostral y mesencefálica modula la actividad del prosencéfalo y los estados de consciencia (Sistema Activador Reticular Ascendente - SARA).","La formación reticular bulbar solo contiene motoneuronas somáticas voluntarias.","La formación reticular no participa en la modulación de las vías del dolor.","Se localiza exclusivamente en la cara anterior de las pirámides bulbares."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q17)] Hack de la Bipartición Funcional de la Formación Reticular: FR Rostral (Mesencéfalo y Puente rostral): Constituye el SARA (Sistema Activador Reticular Ascendente) -> Proyecta al tálamo y corteza para mantener la alerta y la consciencia. FR Caudal (Puente caudal y Bulbo): Trabaja en coordinación con los núcleos autonómicos viscerales (cardiovascular, respiratorio) y modula motoneuronas inferiores mediante los tractos reticuloespinales.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada N-023 / G0105 del banco canónico | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte3.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #168) / Preguntas temas 3,4,5,6.pdf (Pregunta #6) / TEMA 3 – TRONCO DEL ENCÉFALO.pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-24","number":"24","statement":"¿Cuál de las siguientes estructuras o núcleos NO se encuentra en el mesencéfalo?:","options":["Los pedúnculos cerebrales","La sustancia negra","El acueducto cerebral (de Silvio)","Locus coeruleus"],"answer":3,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q18)] Hack del Intruso Noradrenérgico: El Locus Coeruleus es el principal núcleo noradrenérgico del encéfalo y se ubica en el tegmento de la protuberancia (puente), en la porción superior del suelo del IV ventrículo. NUNCA forma parte del mesencéfalo. Por el contrario, los pedúnculos cerebrales (porción basilar/anterior), la sustancia negra y el acueducto de Silvio son elementos exclusivos del mesencéfalo.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada N-024 / G0106 del banco canónico | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte3.pdf | referencias indicadas: ex. 2021 (respuestas).pdf (Pregunta #15) / ex. 2021 (sin respuestas).pdf (Pregunta #15) / NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-25","number":"25","statement":"Respecto a los núcleos moduladores y neuroquímicos del tronco del encéfalo, señale la relación CORRECTA:","options":["Núcleos del Rafe — Sistema serotoninérgico localizado en la franja medial a lo largo del tronco del encéfalo.","Núcleo olivar inferior — Relacionado exclusivamente con la localización de la fuente sonora en el plano horizontal.","Área tegmental ventral — Componente del sistema límbico localizado en la porción posterior del tectum mesencefálico.","Locus coeruleus — Núcleo dopaminérgico ubicado en las pirámides bulbares."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q20)] Hack de Mapeo Transmisor de la Banca: Núcleos del Rafe: Se sitúan en la línea media (mediales) e sintetizan serotonina (5-HT). Oliva Superior (no la inferior): Procesa la localización del sonido en el plano horizontal. Área Tegmental Ventral: Contiene neuronas dopaminérgicas (DA) en la cara VENTRAL del tegmento mesencefálico (no en el tectum).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada N-025 / G0108 del banco canónico | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte3.pdf | referencias indicadas: examenes neuro compl (1).pdf (Pregunta #20) / ex. 2 (respuestas).pdf / TEMA 3 – TRONCO DEL ENCÉFALO.pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-26","number":"26","statement":"Indica la afirmación FALSA sobre las relaciones anatómicas en las secciones del tronco del encéfalo:","options":["El tubérculo grácil es medial con respecto al tubérculo cuneiforme.","Las pirámides bulbares son ventrales con respecto al núcleo cuneiforme.","El locus coeruleus es un sistema difuso noradrenérgico que se localiza a nivel de la protuberancia.","En un corte transversal a nivel del bulbo raquídeo encontraremos el lemnisco lateral."],"answer":3,"explanation":"No incluida en el material.","hack":"Hack de la Ausencia Bulbar del Lemnisco Lateral: El lemnisco lateral es un tracto exclusivamente auditivo que nace en la PROTUBERANCIA (a partir de las fibras cruzadas del cuerpo trapezoide y núcleos cocleares/oliva superior) y asciende hacia el colículo inferior del mesencéfalo. Por consiguiente, jamás estará presente en ningún corte del bulbo raquídeo.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada N-026 / G0111 del banco canónico | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte3.pdf | referencias indicadas: ex. 2022 (sin respuestas) 2.pdf (Pregunta #19) / Recopilación preguntas neuro (1).pdf / NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-27","number":"27","statement":"Los colículos superior e inferior se encuentran en:","options":["La parte posterior de la protuberancia.","La parte anterior de la protuberancia.","La parte posterior del mesencéfalo (área tectal / tectum).","La parte anterior del mesencéfalo.","El colículo superior en el mesencéfalo y el colículo inferior en la protuberancia."],"answer":2,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada N-027 / G0633 del banco canónico | archivos: Neuro_Parte3.pdf | referencias indicadas: wuolah-free-tema-3-preguntas.pdf / wuolah-free-examen-3.pdf (Pregunta #5 - Tectum y Colículos)","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-28","number":"28","statement":"Señala cuál de las siguientes estructuras NO se encuentra en el bulbo raquídeo:","options":["Oliva inferior y núcleo grácil.","Núcleos parabraquiales.","Núcleo ambiguo y pirámides.","Fibras arciformes internas."],"answer":1,"explanation":"[Nota de la clave] Os núcleos parabraquiais encontram-se na protuberância/puente, enquanto a oliva inferior, núcleo grácil, núcleo ambíguo e pirâmides pertencem ao bulbo raquídeo)1213.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada N-028 / G0634 del banco canónico | archivos: Neuro_Parte3.pdf | referencias indicadas: ex. 2021 (respuestas).pdf / examenes neuro compl (1).pdf (Pregunta #14 - Estructuras del Bulbo)","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-29","number":"29","statement":"¿Cuál de las siguientes estructuras NO se encuentra en el mesencéfalo?:","options":["Los pedúnculos cerebrales.","La sustancia negra.","El acueducto de Silvio (cerebral).","Locus coeruleus."],"answer":3,"explanation":"[Nota de la clave] O locus coeruleus é um núcleo noradrenérgico localizado no tegmento da protuberância/puente, não no mesencéfalo).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada N-029 / G0635 del banco canónico | archivos: Neuro_Parte3.pdf | referencias indicadas: ex. 2021 (respuestas).pdf / examenes neuro compl (1).pdf (Pregunta #15 - Estructuras del Mesencéfalo)","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-30","number":"30","statement":"¿Cuál de los siguientes núcleos NO se localiza en la protuberancia?:","options":["Núcleo ambiguo.","Núcleo prepósito.","Complejo olivar superior.","Locus coeruleus."],"answer":0,"explanation":"[Nota de la clave] O núcleo ambíguo localiza-se no bulbo raquídeo e dá origem a eferências motoras branquiais para os pares IX, X e XI)1217.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada N-030 / G0636 del banco canónico | archivos: Neuro_Parte3.pdf | referencias indicadas: perguntas neuro julio exame.docx / examenes neuro compl (1).pdf (Pregunta #20 - Núcleos Pontinos)","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-31","number":"31","statement":"Indica la afirmación FALSA sobre las estructuras troncoencefálicas:","options":["El tubérculo grácil es medial con respecto al tubérculo cuneiforme.","Las pirámides son ventrales con respecto al núcleo cuneiforme.","El locus coeruleus es un sistema difuso noradrenérgico que podemos encontrar en una sección transversal a nivel de la protuberancia.","En un corte transversal a nivel del bulbo raquídeo encontraremos tractos como el lemnisco lateral."],"answer":3,"explanation":"[Nota de la clave] Esta é a FALSA porque o lemnisco lateral se origina a partir do corpo trapezoide na protuberância e ascende rumo ao colículo inferior no mesencéfalo, estando ausente no bulbo raquídeo).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada N-031 / G0637 del banco canónico | archivos: Neuro_Parte3.pdf | referencias indicadas: ex. 2022 (sin respuestas) 2.pdf / examenes neuro compl (1).pdf (Pregunta #19 - Afirmación Falsa en Tronco)","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-32","number":"32","statement":"Indica la afirmación FALSA sobre el tronco del encéfalo y sus núcleos:","options":["El neurotransmisor liberado desde los núcleos del rafe es la serotonina.","Las fibras arciformes internas contienen axones decusados procedentes de los núcleos grácil y cuneiforme que forman el lemnisco medial.","Los colículos inferiores se encuentran en el tectum mesencefálico.","El colículo facial se distingue en el suelo (que es la parte más anterior o ventral) de la fosa romboidea."],"answer":3,"explanation":"[Nota de la clave] Hack Direcional: É a FALSA pois o pavimento da fossa romboide situa-se na superfície POSTERIOR / dorsal da protuberância e do bulbo, e não na ventral).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada N-032 / G0643 del banco canónico | archivos: Neuro_Parte3.pdf | referencias indicadas: ex. 2 (respuestas).pdf / examenes neuro compl (1).pdf / Exame Neuro 2022.pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-33","number":"33","statement":"En la fosa romboidea (suelo del cuarto ventrículo), ¿cuál de las siguientes estructuras NO existe ni forma elevación en la superficie posterior del tronco del encéfalo?:","options":["Colículo facial.","Trígono del vago.","Trígono glosofaríngeo.","Trígono del hipogloso."],"answer":2,"explanation":"[Nota de la clave] Pegadinha Falso-Verdadeiro da Professora Aitana: Existem no soalho do 4º ventrículo o trígono do hipogloso XII e o trígono do vago X, mas NÃO existe \"trígono glosofaríngeo\"320).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada N-033 / G0644 del banco canónico | archivos: Neuro_Parte3.pdf | referencias indicadas: 10-30 Clase magistral_ Neuroanatomía meníngea / TEMA 3 – TRONCO DEL ENCÉFALO.pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-34","number":"34","statement":"En relación a la formación reticular del tronco del encéfalo:","options":["La formación reticular mesencefálica y pontina rostral modula la actividad del encéfalo anterior (mantenimiento del estado de alerta y vigilia).","La formación reticular pontina caudal y del bulbo raquídeo inhibe totalmente las funciones motoras somáticas.","Carece de conexiones con la médula espinal.","Se compone exclusivamente de núcleos motores de los nervios craneales."],"answer":0,"explanation":"[Nota de la clave] La formación reticular mesencefálica y pontina rostral modula la actividad del encéfalo anterior.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada N-034 / G0648 del banco canónico | archivos: Neuro_Parte3.pdf | referencias indicadas: wuolah-free-tema-3-preguntas.pdf / wuolah-free-examen-3.pdf / TEMA 3 – TRONCO DEL ENCÉFALO.pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-35","number":"35","statement":"Indica la relación CORRECTA sobre los núcleos localizados del tronco del encéfalo:","options":["Núcleo cuneiforme — Región medial en la parte anterior del bulbo raquídeo.","Núcleo vestibular lateral — Región lateral en la parte posterior del bulbo raquídeo.","Núcleos interpedunculares — Región medial en la parte anterior del mesencéfalo.","Área tegmental ventral — Alrededor del acueducto mesencefálico."],"answer":2,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada N-035 / G0652 del banco canónico | archivos: Neuro_Parte3.pdf; NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf; NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf | referencias indicadas: perguntas neuro julio exame.docx / examenes neuro compl (1).pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-36","number":"36","statement":"Respecto al mesencéfalo es CORRECTO que:","options":["El nervio troclear (IV par craneal) surge por debajo de los colículos superiores en la cara posterior.","La cavidad ventricular que lo atraviesa se denomina acueducto cerebral (de Silvio).","La fosa interpeduncular está limitada a ambos lados por los pedúnculos cerebelosos.","El nervio oculomotor emerge desde la superficie posterior, debajo de los colículos inferiores."],"answer":1,"explanation":"Análise de Distratores: O nervo troclear emerge abaixo dos colículos inferiores na cara posterior; a fita interpeduncular é delimitada pelos pedúnculos cerebrais; o oculomotor emerge na superfície anterior).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada N-036 / G0653 del banco canónico | archivos: Neuro_Parte3.pdf | referencias indicadas: examenes neuro compl (1).pdf / TEMA 3 – TRONCO DEL ENCÉFALO.pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-37","number":"37","statement":"Identifica las estructuras señaladas en la vista posterior del tronco del encéfalo: (1) tubérculo en el tectum mesencefálico, (2) piso del cuarto ventrículo en la superficie dorsal del puente/bulbo, (3) relieve prominente en la cara anterolateral del bulbo raquídeo:","options":["1. Colículo superior | 2. Techo del IV ventrículo | 3. Pirámides del bulbo","1. Cuerpos mamilares | 2. Fosa romboidal | 3. Oliva","1. Glándula pineal | 2. Acueducto cerebral | 3. Pirámides del bulbo","1. Colículo inferior | 2. Fosa romboidal (suelo del IV ventrículo) | 3. Oliva inferior"],"answer":3,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada N-037 / G0656 del banco canónico | archivos: Neuro_Parte3.pdf | referencias indicadas: ex. 2021 (respuestas).pdf (Pregunta #17) / examenes neuro compl (1).pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-38","number":"38","statement":"¿Cuál es la estructura que delimita el extremo inferior (caudal) en forma de punta de la fosa romboidea en la superficie posterior del bulbo raquídeo?:","options":["El óbex (óbeces / calamus scriptorius).","El acueducto de Silvio.","La decusación de las pirámides.","El surco basilar."],"answer":0,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada N-038 / G0660 del banco canónico | archivos: Neuro_Parte3.pdf | referencias indicadas: 10-30 Clase magistral_ Neuroanatomía meníngea / TEMA 3 – TRONCO DEL ENCÉFALO.pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-39","number":"39","statement":"¿Cuál de las siguientes estructuras NO deja una impronta o elevación en la fosa romboidea (suelo del cuarto ventrículo) en la superficie posterior de la protuberancia y el bulbo?:","options":["Colículo facial (núcleo del VI rodeado por fibras del VII).","Trígono del hipogloso (núcleo del XII par).","Trígono del vago (núcleo motor dorsal del X par).","Colículo inferior (área tectal mesencefálica)."],"answer":3,"explanation":"Hack de Localización Anatómica: Os colículos inferiores situam-se no tectum mesencefálico, acima do 4º ventrículo e posteriores ao aqueduto de Silvio, pelo que NÃO fazem parte do soalho da fossa romboide).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada N-039 / G0666 del banco canónico | archivos: Neuro_Parte3.pdf | referencias indicadas: 10-30 Clase magistral_ Neuroanatomía meníngea / ex. 2022 (sin respuestas) 2.pdf / examenes neuro compl (1).pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-40","number":"40","statement":"Señale la afirmación FALSA respecto a la oliva inferior y las olivas accesorias en el bulbo raquídeo:","options":["Reciben eferencias directas del cerebelo a través del pedúnculo cerebeloso superior.","Reciben aferencias del núcleo rojo a través del tracto tegmental central.","Proyectan axones que cruzan la línea media y entran al cerebelo contralateral como fibras trepadoras.","Se localizan en la región basilar del puente por encima del surco bulbopontino."],"answer":3,"explanation":"[Nota de la clave] É a FALSA: o complexo olivar inferior é uma estrutura característica do bulbo raquídeo, localizando-se lateralmente às pirâmides no bulbo e NÃO na protuberância/puente).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada N-040 / G0673 del banco canónico | archivos: Neuro_Parte3.pdf | referencias indicadas: 10-30 Clase magistral_ Neuroanatomía meníngea / TEMA 3 – TRONCO DEL ENCÉFALO.pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-41","number":"41","statement":"En un corte transversal del mesencéfalo a nivel de los colículos superiores, la Sustancia Gris Periacueductal (SGP / PAG) destaca por su implicación directa en:","options":["La modulación descendente del dolor (analgesia) y respuestas defensivas emocionales.","La transmisión de información gustativa primaria.","La coordinación del equilibrio vestibular fino.","La decusación de las pirámides."],"answer":0,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada N-041 / G0677 del banco canónico | archivos: Neuro_Parte3.pdf | referencias indicadas: 09-25 Clase_ Neuroanatomía del Mesencéfalo / TEMA 3 – TRONCO DEL ENCÉFALO.pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-42","number":"42","statement":"El área postrema se localiza en la superficie dorsal del bulbo raquídeo, adyacente al óbex en el extremo inferior del cuarto ventrículo. ¿Cuál es su particularidad anatómica e integración funcional clave?:","options":["Presenta una barrera hematoencefálica muy gruesa para proteger las pirámides bulbares.","Carece de barrera hematoencefálica (órgano circunventricular), funcionando como zona quimiorreceptora desencadenante del vómito (centro emético) ante toxinas circulantes en sangre.","Contiene el centro neumotáxico responsable del ritmo respiratorio involuntario.","Se ubica en el tectum mesencefálico junto a los colículos inferiores."],"answer":1,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada N-042 / G0689 del banco canónico | archivos: Neuro_Parte3.pdf | referencias indicadas: Tema 1.5.1 - Tronco del encéfalo 25-26.pdf / 10-30 Clase magistral_ Neuroanatomía meníngea / wuolah-free-tema-3-preguntas.pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-43","number":"43","statement":"El núcleo ambiguo es una columna motora branquial profunda situada en la formación reticular del bulbo raquídeo. Sus motoneuronas dan origen a las eferencias motoras voluntarias dirigidas a:","options":["Los músculos de la mímica facial exclusivamente.","Los músculos de la masticación (masetero, temporal y pterigoideos).","Los músculos de la faringe, laringe y tercio superior del esófago (a través de los pares IX, X y porción craneal del XI).","Los músculos intrínsecos y extrínsecos de la lengua."],"answer":2,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada N-043 / G0690 del banco canónico | archivos: Neuro_Parte3.pdf | referencias indicadas: wuolah-free-tema-3-preguntas.pdf / TEMA 3 – TRONCO DEL ENCÉFALO.pdf / 09-18 Clase_ Tronco del Encéfalo","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-44","number":"44","statement":"La regulación automática del ritmo respiratorio requiere de centros integradores en el tronco del encéfalo. ¿Dónde se localiza el Grupo Respiratorio Dorsal (GRD) —asociado al núcleo del tracto solitario— que controla la inspiración básica y recibe aferencias viscerales de quimiorreceptores?:","options":["En el tegmento del mesencéfalo.","En la región dorsolateral del bulbo raquídeo.","En la porción basilar de la protuberancia.","En los pedúnculos cerebrales."],"answer":1,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada N-044 / G0692 del banco canónico | archivos: Neuro_Parte3.pdf | referencias indicadas: Tema 1.5.1 - Tronco del encéfalo 25-26.pdf / 09-16 Clase_ Sistema Nervioso, Cardiovascular y Respiratorio","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-45","number":"45","statement":"En una pregunta identificativa de examen con una imagen y una flecha señalando la masa ventral prominente de sustancia blanca en la cara anterior del mesencéfalo por la que descienden las vías motoras corticoespinales, ¿cuál es la estructura anatómica específica de máxima precisión?:","options":["Pedúnculo cerebral (crus cerebri / pie peduncular).","Pedúnculo cerebeloso medio.","Pirámide bulbar.","Colículo superior."],"answer":0,"explanation":"Hack de Precisão da Banca: Na aula de revisão de exame, os alunos perguntaram se bastava responder \"mesencéfalo\" ou \"tronco\". A professora esclareceu que para obter a pontuação máxima a resposta exata exigida é Pedúnculo cerebral).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada N-045 / G0699 del banco canónico | archivos: Neuro_Parte3.pdf | referencias indicadas: Nervioso T21-T22-20251014_163523 / 10-14 Clase_ Control Motor","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-46","number":"46","statement":"La irrigación arterial de la región basilar y medial de la protuberancia (por donde desciende la vía corticoespinal) depende predominantemente de ramas procedentes de:","options":["Ramas paramedianas y pontinas cortas de la Arteria Basilar.","Arteria Cerebelosa Posteroinferior (PICA).","Arteria Cerebral Anterior (ACA).","Arteria Espinal Posterior."],"answer":0,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada N-046 / G0702 del banco canónico | archivos: Neuro_Parte3.pdf | referencias indicadas: 10-30 Clase de repaso_ sistema nervioso / TEMA 3 – TRONCO DEL ENCÉFALO.pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-47","number":"47","statement":"Respecto a la organización general de las tres porciones del tronco del encéfalo (Bulbo, Protuberancia y Mesencéfalo) y su cavidad ventricular relacionada, señale la afirmación CORRECTA:","options":["El bulbo raquídeo rostral y la protuberancia limitan anteriormente el cuarto ventrículo, mientras que el mesencéfalo es atravesado por el acueducto cerebral (de Silvio).","El mesencéfalo forma el suelo del cuarto ventrículo.","El acueducto cerebral atraviesa el bulbo raquídeo caudal.","El tercer ventrículo se ubica en el interior de la protuberancia."],"answer":0,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada N-047 / G0711 del banco canónico | archivos: Neuro_Parte3.pdf | referencias indicadas: 10-28 Clase_ Estructura del Examen de Neuroanatomía / TEMA 3 – TRONCO DEL ENCÉFALO.pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-48","number":"48","statement":"¿Cuál de las siguientes estructuras se localiza más dorsal y caudal en el tronco del encéfalo?","options":["Núcleo cuneiforme.","Colículos inferiores.","Pedúnculos cerebrales.","Núcleo olivar inferior."],"answer":3,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada N-048 / G0949 del banco canónico | archivos: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf; NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf | referencias indicadas: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-49","number":"49","statement":"La fosa romboidea:","options":["Es una depresión en forma de rombo que constituye el techo del cuarto ventrículo.","Se forma en la superficie dorsal del mesencéfalo.","Se encuentra limitada lateralmente por los pedúnculos cerebelosos superiores.","Contiene el núcleo motor del nervio trigémino."],"answer":2,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada N-049 / G0950 del banco canónico | archivos: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf; NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf | referencias indicadas: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-50","number":"50","statement":"Sobre el tronco del encéfalo es CIERTO que:","options":["Los tubérculos gráciles se encuentran a ambos lados de la fisura media anterior del bulbo raquídeo.","La protuberancia contiene los núcleos de los nervios craneales V, VI, VII y VIII.","Los colículos superiores están involucrados en la integración de la información auditiva.","La sustancia negra se encuentra en la superficie dorsal del mesencéfalo."],"answer":1,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada N-050 / G0951 del banco canónico | archivos: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf; NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf | referencias indicadas: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-51","number":"51","statement":"Indica la relación INCORRECTA sobre los siguientes tractos del tronco del encéfalo:","options":["Lemnisco espinal - Atraviesa todos los segmentos del tronco del encéfalo.","Lemnisco medial - Se origina a nivel de la protuberancia.","Lemnisco trigeminal - Transporta información somatosensitiva de la cara.","Lemnisco lateral - No se encuentra en el bulbo raquídeo."],"answer":1,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada N-051 / G0952 del banco canónico | archivos: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf; NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf | referencias indicadas: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-52","number":"52","statement":"La formación reticular:","options":["Se encuentra exclusivamente en la protuberancia y el bulbo raquídeo.","Participa en la modulación del dolor.","No tiene influencia en los ciclos de sueño y vigilia.","Está involucrada únicamente en la regulación de las funciones motoras somáticas."],"answer":1,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada N-052 / G0953 del banco canónico | archivos: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf; NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf | referencias indicadas: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-53","number":"53","statement":"Con relación a la descripción anatómica del tronco del encéfalo es FALSO que:","options":["Las pirámides se localizan a ambos lados de la fisura media anterior bulbar, mientras que los tubérculos gráciles están a ambos lados de la fisura media posterior bulbar.","La fosa romboidea forma el suelo del cuarto ventrículo en la parte posterior del tronco del encéfalo.","El surco basilar discurre longitudinalmente sobre la línea media anterior de la protuberancia.","Los colículos (tubérculos cuadrigéminos) se localizan ventrales al acueducto mesencefálico."],"answer":3,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada N-053 / G0954 del banco canónico | archivos: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf; NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf | referencias indicadas: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-54","number":"54","statement":"¿Cuál de los siguientes núcleos NO se localiza en la protuberancia?","options":["Núcleo ambiguo.","Núcleo prepósito.","Complejo olivar superior.","Locus coeruleus."],"answer":0,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada N-054 / G0955 del banco canónico | archivos: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf; NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf | referencias indicadas: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-55","number":"55","statement":"Indica la relación INCORRECTA sobre los tractos del tronco del encéfalo:","options":["Lemnisco espinal - Atraviesa todos los segmentos del tronco del encéfalo.","Lemnisco medial - Se origina a nivel de la protuberancia.","Lemnisco trigeminal - Lleva información somatosensitiva de la cara.","Lemnisco lateral - No se encuentra en el bulbo raquídeo."],"answer":1,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada N-055 / G0956 del banco canónico | archivos: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf; NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf | referencias indicadas: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-56","number":"56","statement":"Sobre la formación reticular (FR) es CIERTO que:","options":["La FR pontina caudal modula los estados de consciencia al modular la actividad del prosencéfalo.","La FR pontina rostral presenta actividad sobre las motoneuronas viscerales y somáticas inferiores.","El reflejo barorreceptor se relaciona con los centros de control cardiovascular de la FR bulbar.","Los quimiorreceptores centrales se encuentran en los centros mesencefálicos de control respiratorio."],"answer":2,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada N-056 / G0957 del banco canónico | archivos: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf; NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf | referencias indicadas: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-57","number":"57","statement":"¿Cuál de las siguientes estructuras NO se encuentran en el bulbo raquídeo?","options":["Núcleo olivar inferior.","Núcleos parabraquiales.","Núcleo ambiguo.","Fibras arciformes internas."],"answer":1,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada N-057 / G0958 del banco canónico | archivos: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf; NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf | referencias indicadas: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-58","number":"58","statement":"Señale la relación CORRECTA sobre los núcleos del tronco del encéfalo:","options":["Núcleo olivar superior - Control vasomotor lagrimal.","Núcleos pontinos - Relevo de información entre la corteza motora y el cerebelo.","Colículo inferior - Reflejos visuales.","Núcleo grácil - Relevo de información nociceptiva de las extremidades inferiores."],"answer":1,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada N-058 / G0959 del banco canónico | archivos: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf; NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf | referencias indicadas: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-59","number":"59","statement":"Sobre la formación reticular es CIERTO que:","options":["Solo se encuentra en el mesencéfalo y la protuberancia.","Su única función es regular la función cardíaca y respiratoria.","Está constituida por multitud de núcleos, como por ejemplo el núcleo de Edinger-Westphal o el núcleo salivar superior.","Sus neuronas sinaptan con múltiples estructuras cerebrales, como el tálamo o el hipotálamo, utilizando diferentes neurotransmisores."],"answer":3,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada N-059 / G0960 del banco canónico | archivos: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf; NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf | referencias indicadas: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-60","number":"60","statement":"Señale la afirmación CORRECTA sobre el tronco del encéfalo:","options":["Los tubérculos gráciles se localizan a ambos lados de la fisura media anterior del bulbo raquídeo.","Los núcleos de los nervios X y XII dejan una impronta en el suelo del cuarto ventrículo.","Los colículos inferiores se localizan en el área tectal (o techo) de la protuberancia.","El núcleo rojo se encuentra en una posición más dorsal que la sustancia gris periacueductal del mesencéfalo."],"answer":1,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada N-060 / G0961 del banco canónico | archivos: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf; NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf | referencias indicadas: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-61","number":"61","statement":"El tracto ascendente que nace en la protuberancia y termina en el mesencéfalo se denomina:","options":["Lemnisco medial.","Lemnisco trigeminal.","Lemnisco espinal.","Lemnisco lateral."],"answer":3,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada N-061 / G0962 del banco canónico | archivos: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf; NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf | referencias indicadas: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-62","number":"62","statement":"Señale la relación CORRECTA sobre los núcleos del tronco del encéfalo:","options":["Núcleo salivar inferior - Control vasomotor lagrimal.","Núcleo olivar inferior - Origen de fibras aferentes al cerebelo.","Colículo inferior - Reflejos visuales.","Núcleo grácil - Relevo de información nociceptiva de las extremidades inferiores."],"answer":1,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada N-062 / G0963 del banco canónico | archivos: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf; NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf | referencias indicadas: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-63","number":"63","statement":"La formación reticular:","options":["Solamente se encuentra en la protuberancia y el bulbo raquídeo.","Participa en la modulación del dolor.","No tiene influencia en los ciclos de sueño y vigilia.","Su única función es regular la función cardiaca y respiratoria."],"answer":1,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada N-063 / G0964 del banco canónico | archivos: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf; NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf | referencias indicadas: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-64","number":"64","statement":"El tracto ascendente que nace en la protuberancia y termina en mesencéfalo se llama:","options":["Lemnisco medial.","Lemnisco trigeminal.","Lemnisco espinal.","Lemnisco lateral."],"answer":3,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada N-064 / G0965 del banco canónico | archivos: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf; NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf | referencias indicadas: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-65","number":"65","statement":"La fosa romboidea:","options":["Es una depresión en forma de rombo que constituye el techo del 4º ventrículo.","Se forma en la superficie dorsal del mesencéfalo.","Se encuentra limitada lateralmente por los pedúnculos cerebelosos.","Contiene exclusivamente núcleos motores de los nervios craneales."],"answer":2,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada N-065 / G0966 del banco canónico | archivos: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf; NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf | referencias indicadas: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-66","number":"66","statement":"Señale la afirmación CORRECTA sobre el tronco del encéfalo:","options":["Los tubérculos gráciles se localizan a ambos lados de la fisura media anterior del bulbo raquídeo.","Los núcleos de los nervios X y XII dejan una imprenta en el suelo del 4º ventrículo.","Los colículos inferiores se localizan en el área tectal ventral (o techo) de la protuberancia.","El núcleo rojo se encuentra en una posición más dorsal que la sustancia gris periacueductal del mesencéfalo."],"answer":1,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada N-066 / G0967 del banco canónico | archivos: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf; NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf | referencias indicadas: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-67","number":"67","statement":"Señale la relación CORRECTA sobre núcleos del tronco del encéfalo:","options":["Núcleo salivar inferior — control vasomotor lagrimal.","Núcleo olivar inferior — origen de fibras aferentes al cerebelo.","Colículo inferior — reflejos visuales.","Núcleo grácil — relevo de información nociceptiva de las extremidades inferiores."],"answer":1,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada N-067 / G0968 del banco canónico | archivos: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf; NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf | referencias indicadas: NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-68","number":"68","statement":"¿Cuál es el ÚNICO nervio craneal que tiene su origen aparente en la cara posterior (dorsal) del tronco del encéfalo y cuyas fibras cruzan (decusan) completamente la línea media antes de emerger?:","options":["Nervio Oculomotor (III par)","Nervio Troclear / Patético (IV par)","Nervio Abducens (VI par)","Nervio Accesorio (XI par)"],"answer":1,"explanation":"No incluida en el material.","hack":"Hack de las Dos Unicidades del IV Par: 1. Es el único par craneal que emerge por la cara dorsal/posterior del tronco del encéfalo (a nivel del colículo inferior del mesencéfalo). 2. Es el único cuyas fibras decusan intrínsecamente en el velo medular superior, de modo que el núcleo troclear izquierdo inerva el músculo oblicuo superior del ojo derecho y viceversa.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-001 / G0012 del banco canónico | integración: Tema 1.5.1 + Tema 1.5.2 | archivos: Todos os exames de Neuro EXTRACAO(1).pdf; Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte2.pdf | referencias indicadas: examenes neuro compl (1).pdf (Pregunta #74) / wuolah-free-EXAMEN-2017-2018-1.pdf (Pregunta #71) / 10-30 Clase magistral_ Neuroanatomía meníngea","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-69","number":"69","statement":"El tracto ascendente que nace en los núcleos de la protuberancia (núcleos cocleares y oliva superior) y asciende hacia el colículo inferior del mesencéfalo, formando la vía auditiva principal del tronco, se denomina:","options":["Lemnisco medial","Lemnisco trigeminal","Lemnisco espinal","Lemnisco lateral"],"answer":3,"explanation":"No incluida en el material.","hack":"Hack dos Quatro Lemniscos: Lemnisco Medial: Propriocepção consciente e tacto epicrítico do corpo (de Gracilis/Cuneatus no bulbo ao tálamo VPL). Lemnisco Espinal: Dor e temperatura do corpo (tracto espinotalâmico). Lemnisco Trigeminal: Sensibilidade da face. Lemnisco Lateral: Exclusivamente AUDITIVO (nasce na ponte e termina no colículo inferior do mesencéfalo).","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-002 / G0019 del banco canónico | integración: Tema 1.5.1 + Tema 1.11.2 | archivos: Todos os exames de Neuro EXTRACAO(1).pdf; Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte2.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #202) / Examem 2025 outro modelo juneka.pdf (Pregunta #54) / 09-24 Clase_ Vías Auditivas","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-70","number":"70","statement":"En la cara ventral de la protuberancia, ¿cuál es la función de los núcleos pontinos y a través de qué pedúnculo cerebeloso envían sus axones cruzados hacia el cerebelo?:","options":["Actúan como relevo de información entre la corteza cerebral y el cerebelo a través del pedúnculo cerebeloso medio.","Relevan información propioceptiva de la médula directamente al tálamo.","Reciben información auditiva y proyectan al colículo superior.","Originan las fibras corticoespinales descendentes hacia la médula."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de Falso Conector: Na prova, a banca costuma colocar a alternativa errada dizendo que os núcleos pontinos \"relavam informação entre a corteza e a médula espinal\". FALSO: Os núcleos pontinos relavam informação entre a corteza e o CEREBELO (vía cortico-ponto-cerebelosa) através do pedúnculo cerebeloso médio.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-003 / G0021 del banco canónico | integración: Tema 1.5.1 + Tema 1.7 + Tema 1.9.3 | archivos: Todos os exames de Neuro EXTRACAO(1).pdf; Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte2.pdf | referencias indicadas: ex. 2 (respuestas).pdf (Pregunta #14) / Tema 1.5.1 - Tronco del encéfalo 25-26.pdf / 09-23 Clase_ Núcleos de la Protuberancia","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-71","number":"71","statement":"Señale la afirmación INCORRECTA en relación a la disposición de la sustancia blanca en el tronco del encéfalo:","options":["El lemnisco medial discurre contralateralmente al origen de la información del circuito del que forma parte.","El cuerpo trapezoide es un espacio en la protuberancia ocupado por fibras procedentes de los núcleos cocleares que decusan la línea media.","El tracto corticoespinal a nivel de la protuberancia se localiza en la parte posterior (tegmental) de dicha estructura, adyacente a la línea media.","Los fascículos cuneiforme y grácil no aparecen a nivel de la protuberancia ni del mesencéfalo."],"answer":2,"explanation":"No incluida en el material.","hack":"Hack de Localização do Tracto Corticoespinal: Na protuberância, o tracto corticoespinal NUNCA fica no tegmento (posterior). Ele fragmenta-se em múltiplos feixes longitudinais localizados na PORÇÃO ANTERIOR / BASILAR / VENTRAL, imerso no meio dos núcleos pontinos e das fibras transversas.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-004 / G0022 del banco canónico | integración: Tema 1.5.1 + Tema 1.9.1 | archivos: Todos os exames de Neuro EXTRACAO(1).pdf; Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte2.pdf | referencias indicadas: ex. 2021 (respuestas).pdf (Pregunta #16) / ex. 2022 (sin respuestas) 2.pdf / 09-22 Clase_ Ubicación de tractos","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-72","number":"72","statement":"Respecto a la anatomía macroscópica de la fosa romboidea en la cara posterior del tronco del encéfalo, señale la opción CORRECTA:","options":["Es una depresión en forma de rombo que constituye el techo del cuarto ventrículo.","Se forma en la superficie dorsal del mesencéfalo.","Se encuentra limitada lateralmente por los pedúnculos cerebelosos.","Contiene exclusivamente núcleos motores de los nervios craneales."],"answer":2,"explanation":"No incluida en el material.","hack":"Hack Techo vs. Suelo Ventricular: A fosa romboide forma o SUELO (piso) do IV ventrículo (não o teto). O teto do IV ventrículo é formado pelo véu medular superior e inferior com o cerebelo. Lateralmente, a fosa romboide é anatomicamente delimitada pelos pedúnculos cerebelosos superiores, médios e inferiores.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-005 / G0023 del banco canónico | integración: Tema 1.5.1 + Tema 1.9.3 | archivos: Todos os exames de Neuro EXTRACAO(1).pdf; Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte2.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #25, #270) / Examem 2025 outro modelo juneka.pdf (Pregunta #52)","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-73","number":"73","statement":"La decusación de las pirámides (cruzamiento del 80-90% de las fibras eferentes del tracto corticoespinal) se produce anatómicamente a nivel de:","options":["El bulbo raquídeo (porción inferior/caudal) 1 2.","La protuberancia (puente de Varolio).","El mesencéfalo (pedúnculos cerebrales).","El diencéfalo."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de Localización Fija de la Decusación: La profesora Aitana enfatiza en clase la trayectoria del tracto corticoespinal: desciende por los pedúnculos cerebrales en el mesencéfalo 1 2, atraviesa fragmentado la porción basilar de la protuberancia 2 y forma las elevaciones prominentes llamadas pirámides en la superficie anterior del bulbo raquídeo 2 3. Es justamente en la porción más caudal del bulbo raquídeo donde tiene lugar la decusación piramidal, dando origen al tracto corticoespinal lateral de la médula 1 2.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-006 / G0025 del banco canónico | integración: Tema 1.5.1 + Tema 1.9.1 | archivos: Todos os exames de Neuro EXTRACAO(1).pdf | referencias indicadas: wuolah-free-tema-3-preguntas.pdf (Pregunta #1) / 12-04 Clase magistral_ Tracto corticoespinal / wuolah-free-examenes-2011.pdf (Pregunta #1)","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-74","number":"74","statement":"Respecto al origen y trayecto de las fibras arciformes internas en el tronco del encéfalo, señale la afirmación CORRECTA:","options":["Nacen en los núcleos grácil y cuneiforme del bulbo raquídeo, cruzan la línea media y forman el lemnisco medial 4 5.","Nacen en la oliva superior de la protuberancia y forman el lemnisco lateral 6.","Originan las fibras tectoespinales que descienden directamente al cordón posterior 6.","Son fibras corticoespinales que inervan el núcleo motor del facial."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de Inversión Lemniscal (Pregunta Trampa de Examen): En las opciones falsas de los exmenes antiguos, la banca coloca afirmaciones como \"las fibras arciformes internas forman el lemnisco lateral\" o \"las fibras tectoespinales forman el lemnisco medial\" 6. Las fibras arciformes internas son los axones de las segundas neuronas de la vía del cordón posterior (cuyos somas están en los núcleos grácil y cuneiforme del bulbo posterior) 4. Al salir de estos núcleos, describen una trayectoria arqueada hacia adelante, decusan la línea media y ascienden formando el lemnisco medial rumbo al tálamo VPL 4 5.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-007 / G0026 del banco canónico | integración: Tema 1.5.1 + Tema 1.10 | archivos: Todos os exames de Neuro EXTRACAO(1).pdf | referencias indicadas: Tema 1.5.1 - Tronco del encéfalo 25-26.pdf / 09-19C~1.MP3 / wuolah-free-Examen-Neuro- 3.pdf (Pregunta #78) / wuolah-free-tema-3-preguntas.pdf (Pregunta #12)","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-75","number":"75","statement":"En el suelo de la fosa romboidea (porción pontina), ¿qué estructura produce la prominencia denominada \"colículo facial\" (eminencia teres)?:","options":["Las fibras eferentes del nervio facial (VII) al rodear o hacer un bucle (rodilla del facial) alrededor del núcleo del nervio abducens (VI) 6 8.","El soma del núcleo motor del facial al situarse por encima del acueducto de Silvio.","El núcleo del tracto solitario rodeado por las fibras del nervio glosofaríngeo.","La masa principal del núcleo coclear dorsal."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de la Falsa Anatomía del Colículo Facial: La banca intenta inducir al error sugiriendo que el colículo facial está formado \"exclusivamente por el núcleo del facial\" 6. Realidad anatómica: El núcleo motor del VII par se sitúa más ventrolateralmente en el tegmento pontino. Lo que abulta en el suelo del IV ventrículo y crea la elevación llamada colículo facial son las axones eferentes del VII par que ascienden y rodean medialmente por detrás al núcleo del VI par (Abducens) 6 8.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-008 / G0028 del banco canónico | integración: Tema 1.5.1 + Tema 1.5.2 | archivos: Todos os exames de Neuro EXTRACAO(1).pdf | referencias indicadas: 09-29 Clase de Anatomía_ Nervios V, VI y VII / TEMA 3 – TRONCO DEL ENCÉFALO.pdf / PHOTO-2025-11-06-11-01-30 (2).jpg (Pregunta #24)","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-76","number":"76","statement":"El núcleo olivar inferior es la gran masa de sustancia gris que forma la oliva en la cara anterolateral del bulbo raquídeo 9 10. ¿Cuál es su principal destino de proyección eferente y a través de qué pedúnculo accede a él?:","options":["Envía fibras trepadoras hacia la corteza del cerebelo a través del pedúnculo cerebeloso inferior (cuerpo restiforme) 9.","Envía fibras auditivas directamente al cuerpo geniculado medial del tálamo por el pedúnculo superior.","Proyecta al área motora primaria por la cápsula extrema.","Inerva los músculos extrínsecos del ojo a través del fascículo longitudinal medial."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de Confusión Olivar (Inferior vs. Superior): Oliva Superior (Protuberancia): Vía AUDITIVA (procesa la localización de la fuente sonora en el plano horizontal) 11. Oliva Inferior (Bulbo Raquídeo): Vía MOTOR-CEREBELOSA (es el origen masivo de las fibras trepadoras que entran al cerebelo a través del pedúnculo cerebeloso inferior para el aprendizaje y corrección del movimiento) 9. (¡La trampa más repetida por la profesora Aitana es poner 'información auditiva' como función de la oliva inferior en el examen!) 9 10.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-009 / G0029 del banco canónico | integración: Tema 1.5.1 + Tema 1.9.3 | archivos: Todos os exames de Neuro EXTRACAO(1).pdf | referencias indicadas: 09-19C~1.MP3 / 09-25 Clase_ Neuroanatomía del Mesencéfalo / wuolah-free-Examen-Neuro-1 (1).pdf (Pregunta #2)","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-77","number":"77","statement":"De las siguientes estructuras pertenecientes a la vía auditiva ascendente, ¿cuál se encuentra localizada en la posición más superior (rostral / diencefálica)?:","options":["Núcleo geniculado medial del tálamo 11","Colículo inferior del mesencéfalo 11","Lemnisco lateral 11","Complejo olivar superior de la protuberancia 11"],"answer":0,"explanation":"No incluida en el material.","hack":"Hack del Eje Craniocaudal en las Vías Sensoriales (Aviso de Examen de Aitana): Esta pregunta exige ordenar la vía auditiva de inferior (caudal) a superior (rostral) 11: 1. Oliva Superior / Núcleos Cocleares: Protuberancia/Puente (más inferior) 11. 2. Lemnisco Lateral: Tracto que asciende por la protuberancia hacia el mesencéfalo 4 11. 3. Colículo Inferior: Tecto del mesencéfalo 11. 4. Núcleo Geniculado Medial: Tálamo (Diencéfalo) 11. Como el diencéfalo se ubica estructuralmente por encima de todo el tronco del encéfalo, el Núcleo Geniculado Medial es indiscutiblemente la estructura más superior de la lista 11.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-010 / G0030 del banco canónico | integración: Tema 1.5.1 + Tema 1.6 + Tema 1.11.2 | archivos: Todos os exames de Neuro EXTRACAO(1).pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #202 y Notas) / Examem 2025 outro modelo juneka.pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-78","number":"78","statement":"En la microanatomía del mesencéfalo, la Sustancia Gris Periacueductal (PAG) rodea al acueducto cerebral 13. ¿Cuál es su papel neurofisiológico determinante en el control de la nocicepción?:","options":["Es el centro primordial de la vía descendente de modulación endógena del dolor, liberando encefalinas y endorfinas que proyectan a los núcleos del rafe y a la médula espinal 13.","Sintetiza dopamina para el circuito mesocorticolímbico de recompensa 13.","Origina la vía corticoespinal lateral 2.","Releva la sensibilidad propioceptiva consciente de la cara al tálamo VPM."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de Diferenciación Mesencefálica (PAG vs. VTA): Sustancia Gris Periacueductal (PAG): Rodea al acueducto -> Modulación descendente del dolor / Analgesia endógena (vía opioide) 13. Área Tegmental Ventral (VTA): Cerca de la línea media en el suelo del tegmento -> Neuronas dopaminérgicas del circuito mesocorticolímbico de recompensa/adicción 13. (¡La banca suele intercambiar las funciones de la PAG y de la VTA para confundir al estudiante en el examen!) 13.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-011 / G0032 del banco canónico | integración: Tema 1.4 + Tema 1.5.1 + Tema 1.10 | archivos: Todos os exames de Neuro EXTRACAO(1).pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #165) / Tema 1.5.1 - Tronco del encéfalo / 12-15 Lección_ Neurobiología del Dolor","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-79","number":"79","statement":"En la anatomía interna del mesencéfalo y del tronco encefálico, señale la afirmación INCORRECTA 15:","options":["El colículo superior se localiza en el tectum mesencefálico y participa en reflejos visuales 20 21.","Los núcleos grácil y cuneiforme reciben información sensorial procedente del cordón anterior de la médula espinal 21.","La oliva inferior se localiza en el bulbo raquídeo y envía eferencias hacia el cerebelo 20 21.","El núcleo rojo es una masa motora ubicada en el tegmento del mesencéfalo 21."],"answer":1,"explanation":"No incluida en el material.","hack":"Hack de Inversión de Cordones Medulares: Los núcleos grácil y cuneiforme (en el bulbo posterior) reciben aferencias de las neuronas pseudounipolares del CORDÓN POSTERIOR (fascículos grácil y cuneiforme) 22, encargados de la propiocepción consciente y el tacto epicrítico 22 23. La alternativa es FALSA porque nunca reciben axones del cordón anterior 21.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-012 / G0035 del banco canónico | integración: Tema 1.4 + Tema 1.5.1 | archivos: Todos os exames de Neuro EXTRACAO(1).pdf | referencias indicadas: examenes neuro compl (1).pdf (Pregunta #22) / wuolah-free-tema-4-preguntas.pdf / NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-80","number":"80","statement":"En relación con los tractos y lemniscos que atraviesan el tronco del encéfalo, señale la afirmación INCORRECTA 15:","options":["El lemnisco espinal atraviesa todos los segmentos del tronco del encéfalo 15.","El lemnisco medial se origina a nivel de la protuberancia 15.","El lemnisco trigeminal transporta información somatosensitiva de la cara 15.","El lemnisco lateral no se encuentra en el bulbo raquídeo 15."],"answer":1,"explanation":"No incluida en el material.","hack":"Hack del Origen Falso del Lemnisco Medial: El lemnisco medial se origina en el BULBO RAQUÍDEO 23 27 inmediatamente después de que las fibras arciformes internas cruzan y decusan la línea media desde los núcleos grácil y cuneiforme 23 27. Afirmar que \"nace o se origina en la protuberancia\" es la mentira estándar usada por los profesores en los exámentes para evaluar la vía dorsal 15.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-013 / G0037 del banco canónico | integración: Tema 1.5.1 + Tema 1.10 | archivos: Todos os exames de Neuro EXTRACAO(1).pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #27, #167) / perguntas neuro julio exame.docx (Pregunta #16, #21)","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-81","number":"81","statement":"Respecto a la configuración externa y cavidades del mesencéfalo, es CORRECTO afirmar que 28:","options":["El nervio troclear (IV par) emerge por debajo de los colículos inferiores en la superficie posterior (dorsal) 28 29.","La cavidad interior del mesencéfalo se denomina cuarto ventrículo 29.","La fosa interpeduncular se encuentra limitada a ambos lados por los pedúnculos cerebelosos 29.","El nervio oculomotor (III par) emerge desde la superficie posterior del mesencéfalo 29."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack del IV Par y del Acueducto Mesencefálico: La cavidad interior del mesencéfalo es el ACUEDUCTO CEREBRAL / DE SILVIO 28. La fosa interpeduncular está flanqueada lateralmente por los pedúnculos cerebrales (no cerebelosos) 19 29. El III par (Oculomotor) emerge por la fosa interpeduncular en la cara ANTERIOR / VENTRAL 23 29. Únicamente el IV par (Troclear) emerge por la cara DORSAL / POSTERIOR por debajo de los colículos inferiores 28 29.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-014 / G0038 del banco canónico | integración: Tema 1.5.1 + Tema 1.5.2 | archivos: Todos os exames de Neuro EXTRACAO(1).pdf | referencias indicadas: examenes neuro compl (1).pdf (Pregunta #52) / Tema 1.5.1 - Tronco del encéfalo 25-26.pdf / TEMA 3 – TRONCO DEL ENCÉFALO.pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-82","number":"82","statement":"El tracto tegmental central es un importante haz de sustancia blanca que discurre longitudinalmente por el tegmento del tronco del encéfalo 19 32. ¿Qué regiones conecta principalmente para transmitir aferencias motoras hacia el bulbo?:","options":["Conecta el núcleo rojo y los ganglios basales del mesencéfalo con el complejo olivar inferior del bulbo raquídeo 32.","Conecta la corteza visual con los colículos inferiores 33.","Conecta los núcleos vestibulares con los músculos extensores de la médula 34.","Conecta las pirámides bulbares con el asta posterior de la médula espinal 34 35."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de la Vía Tegmental Central: La profesora Aitana explica que el tracto tegmental central es la principal vía descendente que comunica el núcleo rojo mesencefálico y el globo pálido/estriado con el núcleo olivar inferior del bulbo raquídeo 32. Desde allí, el complejo olivar origina las fibras trepadoras que entran al cerebelo 36.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-015 / G0040 del banco canónico | integración: Tema 1.5.1 + Tema 1.9.2 | archivos: Todos os exames de Neuro EXTRACAO(1).pdf | referencias indicadas: 09-25 Clase_ Neuroanatomía del Mesencéfalo / TEMA 3 – TRONCO DEL ENCÉFALO.pdf / Tema 1.5.1 - Tronco del encéfalo","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-83","number":"83","statement":"Señale la relación CORRECTA sobre los núcleos del tronco del encéfalo y sus proyecciones:","options":["Núcleo salivar inferior — Control vasomotor lagrimal.","Núcleo olivar inferior — Origen de las fibras trepadoras aferentes a la corteza del cerebelo.","Colículo inferior — Reflejos visuales de seguimiento.","Núcleo grácil — Relevo de información nociceptiva de las extremidades inferiores."],"answer":1,"explanation":"[Explicación 1 (Todos os exames de Neuro EXTRACAO(1).pdf Q25)] Hack de Disociación Funcional Olivar y Tectal: Oliva Inferior: Da origen a las fibras trepadoras (vía olivocerebelosa) que entran al cerebelo por el pedúnculo cerebeloso inferior (cuerpo restiforme) para el aprendizaje motor. (NO confundir con la oliva superior, que pertenece a la vía auditiva). Colículo Inferior: Pertenece a la vía AUDITIVA (los reflejos visuales corresponden al colículo superior). Núcleo Grácil: Releva tacto fino epicrítico y propiocepción consciente (NO nocicepción).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-016 / G0041 del banco canónico | integración: Tema 1.5.1 + Tema 1.9.3 | archivos: Todos os exames de Neuro EXTRACAO(1).pdf; Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte3.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #203) / Examem 2025 outro modelo juneka.pdf (Pregunta #55) / 09-19C~1.MP3","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-84","number":"84","statement":"En una sección transversal del tronco del encéfalo realizada a nivel del mesencéfalo superior, a la altura de la sustancia negra, ¿cuál de las siguientes estructuras se encuentra presente de forma característica?:","options":["El área tegmental ventral, el núcleo rojo y la sustancia gris periacueductal.","Las pirámides bulbares y el núcleo ambiguo.","El complejo olivar superior y los núcleos cocleares.","El cuerpo trapezoide y los núcleos pontinos."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de Cortes Transversales del Mesencéfalo: A nivel del mesencéfalo rostral (sustancia negra), encontramos en posición ventral los pedúnculos cerebrales, la sustancia negra, el núcleo rojo, el área tegmental ventral (VTA), la sustancia gris periacueductal (PAG) rodeando el acueducto y los colículos superiores en el tectum. Pirámides y núcleo ambiguo corresponden al bulbo; núcleos pontinos, cocleares y cuerpo trapezoide corresponden a la protuberancia.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-017 / G0042 del banco canónico | integración: Tema 1.5.1 + Tema 1.9.2 | archivos: Todos os exames de Neuro EXTRACAO(1).pdf; Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte3.pdf | referencias indicadas: ex. 2 (sin respuestas) (1, 2, 3 y 16).pdf (Pregunta #15) / examenes neuro compl (1).pdf (Pregunta #15) / 10-20 Clase magistral_ Sistema somatosensorial","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-85","number":"85","statement":"¿Cómo se denomina el tracto motor involuntario que se origina en los colículos superiores, decusa en el tegmento del mesencéfalo (decusación tegmental dorsal de Meynert) y desciende por el cordón anterior de la médula para mediar reflejos posturales oculocervicales en respuesta a estímulos visuales?:","options":["Tracto tectoespinal.","Tracto rubroespinal.","Tracto corticoespinal lateral.","Tracto vestibuloespinal lateral."],"answer":0,"explanation":"[Explicación 1 (Todos os exames de Neuro EXTRACAO(1).pdf Q27)] Hack de los Tractos Eferentes Mesencefálicos: Tracto Tectoespinal: Nace en el colículo superior (tectum mesencefálico), decusa en el mesencéfalo y viaja por el cordón anterior de la médula (reflejos de giro de cabeza/cuello ante estímulos visuales). Tracto Rubroespinal: Nace en el núcleo rojo (tegmento mesencefálico), decusa en el mesencéfalo (decusación de Forel) y viaja por el cordón lateral.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-018 / G0043 del banco canónico | integración: Tema 1.5.1 + Tema 1.9.1 | archivos: Todos os exames de Neuro EXTRACAO(1).pdf; Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte3.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #42, #43) / 09-23 Clase_ Neuroanatomía del Tronco Encefálico / wuolah-free-tema-3-preguntas.pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-86","number":"86","statement":"En la cara anterolateral del bulbo raquídeo, el complejo olivar inferior está delimitado por el surco preolivar y el surco retroolivar (postolivar). ¿Qué par craneal emerge a través de múltiples filetes radiculares de forma exclusiva por el surco PREOLIVAR?:","options":["Nervio Hipogloso (XII par).","Nervio Glosofaríngeo (IX par).","Nervio Vago (X par).","Nervio Accesorio (XI par)."],"answer":0,"explanation":"[Explicación 1 (Todos os exames de Neuro EXTRACAO(1).pdf Q28)] Hack del Surco Preolivar vs. Retroolivar (Pregunta de Examen Recurrente): Surco PREOLIVAR (Anterior a la oliva): Emerge ÚNICAMENTE el XII par (Hipogloso). Surco RETROOLIVAR / Postolivar (Posterior a la oliva): Emergen de arriba a abajo los pares IX (Glosofaríngeo), X (Vago) y XI (Accesorio / Espinal).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-019 / G0044 del banco canónico | integración: Tema 1.5.1 + Tema 1.5.2 | archivos: Todos os exames de Neuro EXTRACAO(1).pdf; Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte3.pdf | referencias indicadas: 09-26 Clase_ Nervios Craneales - Neuroanatomía / wuolah-free-tema-4-preguntas.pdf (Pregunta #11) / TEMA 4 – PARES CRANEALES .pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-87","number":"87","statement":"En la porción anterior del tegmento de la protuberancia caudal se identifica una prominente franja transversal de fibras mielínicas denominada cuerpo trapezoide. ¿Cuál es el origen y la función de las fibras que cruzan en esta estructura?:","options":["Axones procedentes de los núcleos cocleares que decusan la línea media hacia la oliva superior y el lemnisco lateral para la vía auditiva.","Fibras corticoespinales descendentes que cruzan hacia la médula.","Axones de los núcleos vestibulares que forman el tracto vestibuloespinal.","Fibras sensitivas procedentes del núcleo grácil."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack del Cuerpo Trapezoide: El cuerpo trapezoide es el cruce comisural de la vía auditiva en la protuberancia. Las fibras nacidas en el núcleo coclear ventral cruzan la línea media en el cuerpo trapezoide para hacer sinapsis en el complejo olivar superior contralateral y ascender por el lemnisco lateral.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-020 / G0046 del banco canónico | integración: Tema 1.5.1 + Tema 1.11.2 | archivos: Todos os exames de Neuro EXTRACAO(1).pdf; Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte3.pdf | referencias indicadas: 09-22 Clase_ Ubicación de tractos del tronco del encéfalo / TEMA 3 – TRONCO DEL ENCÉFALO.pdf / NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-88","number":"88","statement":"Durante la embriogénesis del tronco del encéfalo, el rombencéfalo se subdivide en metencéfalo y mielencéfalo. ¿Qué estructuras maduras adultas derivan de la placa alar (sensitiva) y de la placa basal (motora) de estas vesículas secundarias?:","options":["El mielencéfalo origina el bulbo raquídeo; los núcleos motores de los pares craneales (como el XII y el ambiguo) derivan de la placa basal, mientras que los núcleos sensitivos (como el del tracto solitario, grácil y cuneiforme) y el núcleo olivar inferior derivan de la placa alar.","El metencéfalo origina exclusivamente los pedúnculos cerebrales.","La placa basal da origen a los colículos superiores e inferiores.","La placa alar da origen al tracto corticoespinal lateral."],"answer":0,"explanation":"[Explicación 1 (Todos os exames de Neuro EXTRACAO(1).pdf Q31)] Hack Embriológico del Tronco: Placa Basal (Ventral / Motora): Da origen a las columnas eferentes motoras de los pares craneales (somáticas, viscerales y branquiales). Placa Alar (Dorsal / Sensitiva): Da origen a las columnas aferentes sensitivas de los pares craneales, a los núcleos pontinos, al núcleo olivar inferior (que migra desde la placa alar) y a los colículos tectales.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-021 / G0047 del banco canónico | integración: Tema 1.2 + Tema 1.5.1 + Tema 1.5.2 | archivos: Todos os exames de Neuro EXTRACAO(1).pdf; Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte3.pdf | referencias indicadas: 10-30 Clase magistral_ Desarrollo embrionario del sistema nervioso / TEMA 16 – EMBRIOLOGÍA.pdf / Tema 1.5.1 - Tronco del encéfalo","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-89","number":"89","statement":"En la superficie posterior del bulbo raquídeo, el orificio o ángulo caudal donde el cuarto ventrículo se estrecha para continuarse con el conducto ependimario central de la médula espinal recibe el nombre de:","options":["Obex (o calamus scriptorius).","Receso lateral de Luschka.","Agujero de Magendie.","Escotadura tentorial."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack del Obex (Gatillo Anatómico de Clase): La profesora Aitana resalta en el audio que el Obex es el ángulo o vértice más caudal de la fosa romboidea en el bulbo raquídeo, marcando el punto exacto donde finaliza el cuarto ventrículo abierto y se inicia el conducto ependimario cerrado de la médula.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-022 / G0048 del banco canónico | integración: Tema 1.4 + Tema 1.5.1 | archivos: Todos os exames de Neuro EXTRACAO(1).pdf; Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte3.pdf | referencias indicadas: 09-18 Clase_ Tronco del Encéfalo.mp / 09-22 Clase_ Anatomía del tronco del encéfalo / NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-90","number":"90","statement":"En el complejo olivar inferior del bulbo raquídeo, ¿cuál es la función de la información que releva y cuál es su vía eferente hacia el cerebelo?:","options":["Releva información propioceptiva de músculos y articulaciones hacia el cerebelo a través de las fibras trepadoras.","Releva información auditiva de tono hacia el tálamo medial.","Releva información visual directa desde la retina hasta los músculos extraoculares.","Releva impulsos del tacto fino hacia el cordón anterior de la médula."],"answer":0,"explanation":"[Explicación 1 (Todos os exames de Neuro EXTRACAO(1).pdf Q37)] Hack de las Fibras Trepadoras del Núcleo Olivar Inferior: El núcleo olivar inferior recibe aferencias de la médula espinal (tracto espinoolivar), núcleo rojo y corteza motora, enviando axones eferentes cruzados que penetran al cerebelo como fibras trepadoras a través del pedúnculo cerebeloso inferior (cuerpo restiforme), clave en la coordinación y corrección de la actividad motora voluntaria 40 50. || [Explicación 2 (Neuro_Adicional_Parte3.pdf Q37)] Hack de las Fibras Trepadoras del Núcleo Olivar Inferior: El núcleo olivar inferior recibe aferencias de la médula espinal (tracto espinoolivar), núcleo rojo y corteza motora, enviando axones eferentes cruzados que penetran al cerebelo como fibras trepadoras a través del pedúnculo cerebeloso inferior (cuerpo restiforme), clave en la coordinación y corrección de la actividad motora voluntaria.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-023 / G0053 del banco canónico | integración: Tema 1.5.1 + Tema 1.9.3 | archivos: Todos os exames de Neuro EXTRACAO(1).pdf; Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte3.pdf | referencias indicadas: wuolah-free-tema-3-preguntas.pdf (Pregunta #2) / 09-25 Clase_ Neuroanatomía del Mesencéfalo / 12-10 Clase_ Microanatomía y Fisiología del Cerebelo","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-91","number":"91","statement":"Respecto a la neuroanatomía y localización del núcleo de Edinger-Westphal (núcleo accesorio del III par craneal), señale la afirmación CORRECTA:","options":["Se ubica en el tegmento del mesencéfalo, ventral a la sustancia gris periacueductal, y da origen a las fibras parasimpáticas preganglionares del III par.","Se ubica en la oliva bulbar y envía fibras motoras somáticas al músculo recto lateral.","Se ubica en el piso del cuarto ventrículo en la protuberancia caudal.","Inerva los músculos de la masticación derivados del primer arco branquial."],"answer":0,"explanation":"[Explicación 1 (Todos os exames de Neuro EXTRACAO(1).pdf Q38)] Hack del Núcleo Parasimpático Mesencefálico: El núcleo de Edinger-Westphal (núcleo accesorio del oculomotor) es el único núcleo parasimpático ubicado en el mesencéfalo rostral. Sus axones eferentes viscerales generales (EVG) viajan por el III par craneal hacia el ganglio ciliar para inervar el músculo esfínter de la pupila (miosis) y el músculo ciliar (acomodación) 51 52. || [Explicación 2 (Neuro_Adicional_Parte3.pdf Q38)] Hack del Núcleo Parasimpático Mesencefálico: El núcleo de Edinger-Westphal (núcleo accesorio del oculomotor) es el único núcleo parasimpático ubicado en el mesencéfalo rostral. Sus axones eferentes viscerales generales (EVG) viajan por el III par craneal hacia el ganglio ciliar para inervar el músculo esfínter de la pupila (miosis) y el músculo ciliar (acomodación).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-024 / G0054 del banco canónico | integración: Tema 1.5.1 + Tema 1.5.2 + Tema 1.12 | archivos: Todos os exames de Neuro EXTRACAO(1).pdf; Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte3.pdf | referencias indicadas: wuolah-free-EXAMEN-2017-2018-1.pdf (Pregunta #63) / 09-25 Clase_ Neuroanatomía del Mesencéfalo y Sistemas Moduladores","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-92","number":"92","statement":"En la organización de las vías somatosensitivas que cruzan el tronco del encéfalo, ¿qué diferencia estructural existe entre el lemnisco medial y el lemnisco espinal?:","options":["El lemnisco medial se origina por la decusación de las fibras arciformes internas en el bulbo (vía grácil y cuneiforme), mientras que el lemnisco espinal corresponde a las fibras espinotalámicas que ya decusaron en la médula espinal.","El lemnisco espinal no llega al tálamo.","El lemnisco medial transporta dolor y temperatura corporal.","El lemnisco espinal se origina en el núcleo motor del trigémino."],"answer":0,"explanation":"[Explicación 1 (Todos os exames de Neuro EXTRACAO(1).pdf Q39)] Hack de Decusación Medular vs. Bulbar: Lemnisco Espinal (Tracto Espinotalámico): Decusa en la médula espinal (comisura blanca anterior) y asciende ipsilateralmente por todo el tronco del encéfalo hacia el tálamo VPL (dolor y temperatura) 53. Lemnisco Medial: Decusa en el bulbo raquídeo (fibras arciformes internas) y asciende por el centro del tegmento hacia el tálamo VPL (tacto epicrítico y propiocepción consciente) 43 53. || [Explicación 2 (Neuro_Adicional_Parte3.pdf Q39)] Hack de Decusación Medular vs. Bulbar: Lemnisco Espinal (Tracto Espinotalámico): Decusa en la médula espinal (comisura blanca anterior) y asciende ipsilateralmente por todo el tronco del encéfalo hacia el tálamo VPL (dolor y temperatura). Lemnisco Medial: Decusa en el bulbo raquídeo (fibras arciformes internas) y asciende por el centro del tegmento hacia el tálamo VPL (tacto epicrítico y propiocepción consciente).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-025 / G0055 del banco canónico | integración: Tema 1.4 + Tema 1.5.1 + Tema 1.6 + Tema 1.10 | archivos: Todos os exames de Neuro EXTRACAO(1).pdf; Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte3.pdf | referencias indicadas: 09-22 Clase_ Ubicación de tractos del tronco del encéfalo / NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #167)","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-93","number":"93","statement":"El núcleo motor dorsal del vago y el núcleo ambiguo se localizan en el bulbo raquídeo. Indique la diferencia de modalidad funcional entre ambos núcleos:","options":["El núcleo ambiguo proporciona inervación motora branquial (faringe y laringe), mientras que el núcleo dorsal del vago proporciona inervación parasimpática visceral (corazón y vísceras abdominales).","El núcleo ambiguo es puramente gustativo.","El núcleo dorsal del vago inerva los músculos de la masticación.","Ambos núcleos son la fuente de la sensibilidad táctil de la cara."],"answer":0,"explanation":"[Explicación 1 (Todos os exames de Neuro EXTRACAO(1).pdf Q40)] Hack de la Bipartición Motora del X Par: Núcleo Ambiguo: Eferente Visceral Especial / Branquial -> Músculos estriados derivados de arcos branquiales (deglución y fonación). Núcleo Dorsal Motor del Vago: Eferente Visceral General / Parasimpático -> Músculo liso, músculo cardíaco y glándulas de las vísceras torácicas y abdominales.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-026 / G0056 del banco canónico | integración: Tema 1.5.1 + Tema 1.12 | archivos: Todos os exames de Neuro EXTRACAO(1).pdf; Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte3.pdf | referencias indicadas: 09-26 Clase_ Nervios Craneales / TEMA 3 – TRONCO DEL ENCÉFALO.pdf / NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-94","number":"94","statement":"Los núcleos grácil y cuneiforme se ubican en la porción posterior del bulbo raquídeo. Respecto a su conectividad y función, señale la afirmación CORRECTA:","options":["Reciben la información somatosensorial de propiocepción consciente, vibración y tacto epicrítico del cuerpo y originan las fibras arciformes internas.","Forman parte directa de la vía espinotalámica lateral del dolor.","Envían eferencias directas a la corteza motora primaria sin pasar por el tálamo.","Relevan aferencias viscerales procedentes del nervio vago."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de la Vía Dorsal: Los núcleos grácil (miembro inferior/tronco caudal, medial) y cuneiforme (miembro superior/tronco rostral, lateral) son los núcleos de relevo de la vía del cordón posterior. Sus axones eferentes forman las fibras arciformes internas que cruzan la línea media en la decusación sensitiva del bulbo para constituir el lemnisco medial.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-027 / G0058 del banco canónico | integración: Tema 1.5.1 + Tema 1.10 | archivos: Todos os exames de Neuro EXTRACAO(1).pdf; Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte3.pdf | referencias indicadas: wuolah-free-PREGUNTAS-EXAMEN-DE-NEURO.pdf (Pregunta #1) / 09-18 Clase_ Tronco del Encéfalo / NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-95","number":"95","statement":"En relación con la disposición de la sustancia blanca y los tractos que atraviesan la protuberancia, señale la afirmación INCORRECTA:","options":["El tracto corticoespinal a nivel de la protuberancia se localiza en la porción tegmental (posterior), adyacente a la línea media.","El lemnisco medial discurre contralateralmente al origen de la información periférica.","El cuerpo trapezoide es un espacio ocupado por fibras procedentes de los núcleos cocleares que decusan la línea media.","Los fascículos grácil y cuneiforme no están presentes a nivel de la protuberancia."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de la Porción Basilar vs. Tegmental: A nivel del puente/protuberancia, el tracto corticoespinal transcurre fragmentado en la porción basilar (ANTERIOR/VENTRAL), inmerso entre los núcleos pontinos y las fibras pontocerebelosas transversas. En el tegmento (posterior) discurren los lemniscos (medial, espinal, trigeminal y lateral) y la formación reticular, NUNCA el tracto corticoespinal.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-028 / G0059 del banco canónico | integración: Tema 1.5.1 + Tema 1.9.1 | archivos: Todos os exames de Neuro EXTRACAO(1).pdf; Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte3.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #167) / ex. 2021 (respuestas).pdf (Pregunta #16) / 09-22 Clase_ Ubicación de tractos del tronco del encéfalo","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-96","number":"96","statement":"Durante el desarrollo embrionario del tronco del encéfalo, el surco limitante separa la placa alar de la placa basal en las paredes del tubo neural. ¿Qué organización funcional adoptan los núcleos derivados de ambas placas a nivel del bulbo y la protuberancia tras la apertura del cuarto ventrículo?:","options":["Los núcleos motores (derivados de la placa basal) quedan ubicados medialmente, mientras que los núcleos sensitivos (derivados de la placa alar) quedan desplazados lateralmente.","Los núcleos sensitivos quedan mediales y los motores laterales.","Los núcleos motores migran exclusivamente al tectum mesencefálico.","La placa alar desaparece por completo en el tronco del encéfalo."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q46)] Hack de la Regla Medial-Motor / Lateral-Sensitivo: La apertura del tubo neural para formar la fosa romboidea desplaza las paredes dorsalmente como un \"libro abierto\". Como resultado: Placa Basal (Motora): Queda pegada a la línea media (MEDIAL). Placa Alar (Sensitiva): Queda desplazada hacia afuera (LATERAL). (Mnemotecnia de examen: Motor = Medial; Sensitivo = Lateral).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-029 / G0062 del banco canónico | integración: Tema 1.2 + Tema 1.5.1 | archivos: Todos os exames de Neuro EXTRACAO(1).pdf; Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte3.pdf | referencias indicadas: 10-30 Clase magistral_ Desarrollo embrionario del sistema nervioso / TEMA 16 – EMBRIOLOGÍA.pdf / NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-97","number":"97","statement":"En el estudio del tronco del encéfalo y su relación con el sistema ventricular, ¿qué estructura anatómica constituye el límite lateral superior de la fosa romboidea (suelo del cuarto ventrículo) en la transición hacia el mesencéfalo?:","options":["Pedúnculos cerebelosos superiores.","Pirámides bulbares.","Cuerpos mamilares.","Tubérculos gráciles."],"answer":0,"explanation":"[Explicación 1 (Todos os exames de Neuro EXTRACAO(1).pdf Q48)] Hack de los Límites de la Fosa Romboidea: Límite Superolateral: Pedúnculos cerebelosos superiores (brachium conjunctivum). Límite Inferolateral: Pedúnculos cerebelosos inferiores (cuerpo restiforme) y tubérculos grácil y cuneiforme. Vértice Caudal: Obex. Vértice Rostral: Acueducto cerebral de Silvio.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-030 / G0064 del banco canónico | integración: Tema 1.5.1 + Tema 1.9.3 | archivos: Todos os exames de Neuro EXTRACAO(1).pdf; Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte3.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #201) / 09-18 Clase_ Tronco del Encéfalo / TEMA 3 – TRONCO DEL ENCÉFALO.pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-98","number":"98","statement":"El tracto corticonuclear (corticobulbar) es la vía motora voluntaria que controla las motoneuronas de los núcleos de los nervios craneales en el tronco del encéfalo. Respecto a su organización e inervación, señale la afirmación CORRECTA:","options":["Proporciona inervación bilateral a la mayoría de los núcleos motores de los nervios craneales, con excepción de la porción inferior del núcleo del facial (VII), que recibe inervación predominantemente contralateral.","Proporciona inervación puramente ipsilateral a todos los núcleos motores del tronco.","Se origina exclusivamente en el área visual primaria (área 17 de Brodmann).","Desciende por el cordón posterior de la médula espinal."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q49)] Hack de la Regla de Inervación del VII Par: El tracto corticonuclear envía fibras eferentes cortico- bulbares bilaterales a la mayoría de los núcleos motores (V, ambiguo, etc.). La EXCEPCIÓN DE EXAMEN MÁS REPETIDA es el núcleo motor del facial: la parte del núcleo que inerva la musculatura de la mitad inferior de la cara recibe axones exclusivamente contralaterales (por eso una lesión de la motoneurona superior causa parálisis facial central que respeta la frente).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-031 / G0065 del banco canónico | integración: Tema 1.5.1 + Tema 1.9.1 | archivos: Todos os exames de Neuro EXTRACAO(1).pdf; Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte3.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #169) / 12-04 Clase_ Tractos Corticoespinal, Corticonuclear / TEMA 3 – TRONCO DEL ENCÉFALO.pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-99","number":"99","statement":"El síndrome de Wallenberg (síndrome bulbar lateral) es provocado típicamente por la oclusión de la Arteria Cerebelosa Posteroinferior (PICA). De las siguientes estructuras del tronco del encéfalo, ¿cuál NO se destruye en este síndrome por localizarse en la porción medial/ventral del bulbo?:","options":["Las pirámides bulbares y el lemnisco medial.","El núcleo ambiguo.","El núcleo espinal del nervio trigémino.","El tracto espinotalámico lateral."],"answer":0,"explanation":"[Explicación 1 (Todos os exames de Neuro EXTRACAO(1).pdf Q50)] Hack de Anatomía del Síndrome de Wallenberg (Bulbar Lateral vs Medial): Síndrome de Wallenberg (Bulbar LATERAL / PICA): Afecta al núcleo ambiguo (disfagia/disfonía), núcleo espinal del V (hipoestesia facial ipsilateral), tracto espinotalámico (hipoestesia corporal contralateral) y vías simpáticas (Horner). Las pirámides y el lemnisco medial son estructuras MEDIALES/VENTRALES irrigadas por la arteria espinal anterior (su afectación causa el síndrome bulbar medial o de Dejerine, respetando la región lateral).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-032 / G0066 del banco canónico | integración: Tema 1.5.1 + Tema 1.9.3 + Tema 1.10 | archivos: Todos os exames de Neuro EXTRACAO(1).pdf; Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte3.pdf | referencias indicadas: 09-26 Clase_ Nervios Craneales - Neuroanatomía / wuolah-free-tema-4-preguntas.pdf (Pregunta #14) / NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-100","number":"100","statement":"El lemnisco trigeminal es la vía ascendente que conduce la sensibilidad somática de la cara hacia el tálamo. ¿Dónde se originan las neuronas de segunda orden cuyos axones cruzan la línea media para formar este lemnisco?:","options":["En los núcleos principal (pontino) y espinal (bulbomedular) del nervio trigémino.","En el ganglio de Gasser exclusivamente.","En el núcleo mesencefálico del trigémino.","En el núcleo del tracto solitario."],"answer":0,"explanation":"[Explicación 1 (Todos os exames de Neuro EXTRACAO(1).pdf Q51)] Hack de las Neuronas del Lemnisco Trigeminal: Primera neurona: Somas en el ganglio trigeminal (de Gasser). Segunda neurona: Somas en el Núcleo Principal (tacto fino) y Núcleo Espinal (termoalgesia) del V par en el tronco. Sus axones cruzan al lado opuesto y ascienden como lemnisco trigeminal hacia el núcleo VPM del tálamo.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-033 / G0067 del banco canónico | integración: Tema 1.5.1 + Tema 1.5.2 + Tema 1.6 + Tema 1.10 | archivos: Todos os exames de Neuro EXTRACAO(1).pdf; Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte3.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #204) / 09-26 Clase_ Nervio Trigémino / 10-20 Clase magistral_ Sistema somatosensorial","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-101","number":"101","statement":"En el tegmento del puente y del bulbo raquídeo, las fibras parasimpáticas preganglionares de los nervios craneales nacen de núcleos eferentes viscerales generales. Indique la pareja de núcleos que da origen a la inervación secretomotora de las glándulas salivales submandibular, sublingual y parótida respectivamente:","options":["Núcleo salival superior (VII par) para las glándulas submandibular y sublingual | Núcleo salival inferior (IX par) para la glándula parótida.","Núcleo salival inferior para submandibular | Núcleo de Edinger-Westphal para la parótida.","Núcleo ambiguo para la parótida | Núcleo dorsal del vago para la sublingual.","Núcleo motor del V3 para todas las glándulas salivales."],"answer":0,"explanation":"[Explicación 1 (Todos os exames de Neuro EXTRACAO(1).pdf Q52)] Hack de Inversión de Núcleos Salivales: Núcleo Salival Superior (Protuberancia caudal / VII par): Ganglio submandibular -> Glándulas Submandibular y Sublingual (+ lagrimal vía pterigopalatino). Núcleo Salival Inferior (Bulbo rostral / IX par): Ganglio óptico -> Glándula Parótida. (¡La banca suele invertir los nombres afirmando que el salival inferior inerva la submandibular!).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-034 / G0068 del banco canónico | integración: Tema 1.5.1 + Tema 1.5.2 + Tema 1.12 | archivos: Todos os exames de Neuro EXTRACAO(1).pdf; Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte3.pdf | referencias indicadas: 09-24 Clase_ Vías Sensitivas y Auditivas del Tronco Encefálico / TEMA 4 – PARES CRANEALES .pdf / NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-102","number":"102","statement":"Los tres pares de pedúnculos cerebelosos (superior, medio e inferior) conectan el tronco del encéfalo con el cerebelo. Señale la afirmación CORRECTA sobre el contenido y origen del Pedúnculo Cerebeloso Medio (brachium pontis):","options":["Está formado exclusivamente por las fibras pontocerebelosas transversas procedentes de los núcleos pontinos del lado contralateral.","Está formado por las fibras trepadoras procedentes de la oliva inferior.","Es el principal pedúnculo eferente que conecta el núcleo dentado con el tálamo.","Discurre por la cara posterior del mesencéfalo."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de la Composición Unidireccional del Pedúnculo Cerebeloso Medio: El Pedúnculo Cerebeloso Medio (PCM) es el más voluminoso. Es una vía 100% AFERENTE al cerebelo, compuesta por las fibras transversas que cruzan desde los núcleos pontinos contralaterales (vía corticopontocerebelosa). No contiene eferencias hacia el tálamo ni fibras olivocerebelosas (esas van por el pedúnculo inferior).","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-035 / G0069 del banco canónico | integración: Tema 1.5.1 + Tema 1.9.3 | archivos: Todos os exames de Neuro EXTRACAO(1).pdf; Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte3.pdf | referencias indicadas: 12-10 Clase magistral_ Cerebelo, Sistema Somatosensorial / TEMA 10 – CEREBELO Y COORDINACIÓN.pdf / NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-103","number":"103","statement":"El síndrome de Weber es un síndrome alterno mesencefálico provocado por una oclusión vascular de las ramas pedunculares de la arteria cerebral posterior. ¿Qué combinación clínica caracteriza a este síndrome por la destrucción de la base del pedúnculo cerebral y de las fibras radiculares adyacentes?:","options":["Parálisis ipsilateral del nervio oculomotor (III par) con midriasis + Hemiparesia contralateral (por afectación del tracto corticoespinal en el pie peduncular).","Parálisis contralateral del VI par + Anestesia facial ipsilateral.","Síndrome de Horner ipsilateral + Ataxia auditiva.","Cuadriplejía flácida con conservación de los movimientos verticales del ojo exclusivamente (síndrome de cautiverio)."],"answer":0,"explanation":"[Explicación 1 (Todos os exames de Neuro EXTRACAO(1).pdf Q54)] Hack del Síndrome de Weber (Mesencefálico Medial): Déficit ipsilateral de par craneal: Parálisis del III par (ptosis, ojo \"abajo y afuera\", midriasis) por lesión de sus fibras emergentes en la fosa interpeduncular. Déficit motor contralateral: Hemiparesia corporal contralateral por lesión del tracto corticoespinal en el pie del pedúnculo cerebral.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-036 / G0070 del banco canónico | integración: Tema 1.3 + Tema 1.5.1 + Tema 1.5.2 + Tema 1.9.1 | archivos: Todos os exames de Neuro EXTRACAO(1).pdf; Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte3.pdf | referencias indicadas: 09-25 Clase_ Neuroanatomía del Mesencéfalo / NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #172) / TEMA 3 – TRONCO DEL ENCÉFALO.pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-104","number":"104","statement":"En la fosa romboidea del tronco del encéfalo, los núcleos vestibulares (superior, inferior, medial y lateral) ocupan el área vestibular. ¿A través de qué haz eferente coordinan los movimientos oculares compensatorios en respuesta a la estimulación vestibular (reflejo vestibulOcular - RVO)?:","options":["Fascículo Longitudinal Medial (FLM).","Lemnisco Medial.","Tracto Espinotalámico Lateral.","Fascículo Uncinado de Russell."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q55)] Hack del Reflejo Vestíbulo-Ocular (FLM): Los axones que nacen en los núcleos vestibulares ascienden por el Fascículo Longitudinal Medial (FLM) e inervan los núcleos motores oculares (III, IV y VI pares) de forma coordinada, permitiendo mantener la fijación foveal de la mirada durante los movimientos de la cabeza (Reflejo Vestíbulo- Ocular).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-037 / G0071 del banco canónico | integración: Tema 1.5.1 + Tema 1.7 + Tema 1.11.2 | archivos: Todos os exames de Neuro EXTRACAO(1).pdf; Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte3.pdf | referencias indicadas: 09-24 Clase_ Vías Sensitivas y Auditivas / TEMA 13 – SENTIDO DE LA AUDICIÓN.pdf / NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-105","number":"105","statement":"El núcleo pulvinar constituye la gran masa prominente del extremo posterior del tálamo. ¿A qué grupo funcional pertenece y con qué cortezas cerebrales establece sus principales conexiones asociativas?:","options":["Pertenece al grupo asociativo multimodal; recibe aferencias del colículo superior y áreas visuales/auditivas, proyectando hacia las cortezas de asociación parietal, occipital y temporal.","Es un núcleo de relevo motor que recibe del globo pálido interno y proyecta a la corteza M1.","Es la única lámina del tálamo encargada de secretar melatonina.","Se ubica en el piso del cuarto ventrículo en el bulbo raquídeo."],"answer":0,"explanation":"No incluida en el material.","hack":"El Pulvinar es el núcleo más volumétrico del extremo posterior del tálamo. No es un núcleo de relevo sensorial primario, sino un núcleo asociativo multimodal clave en la integración de estímulos visuales, acústicos y somatosensoriales hacia la corteza parieto-occipito- temporal.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-038 / G0082 del banco canónico | integración: Tema 1.5.1 + Tema 1.6 + Tema 1.11.2 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte2.pdf | referencias indicadas: TEMA 5 – DIENCÉFALO .pdf / ex. 2 (respuestas).pdf (Pregunta #21) / 10-01 Clase_ Neuroanatomía - Tálamo e Hipotálamo","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-106","number":"106","statement":"Los núcleos intralaminares del tálamo (entre los que destaca el núcleo centromediano) se encuentran inmersos en el espesor de la lámina medular interna. ¿Cuál es su papel neurofisiológico en la modulación de la actividad cerebral?:","options":["Reciben aferencias de la formación reticular, cerebelo y ganglios basales, y envían proyecciones difusas no específicas a la corteza cerebral para modular el nivel de alerta (arousal) y el dolor crónico.","Relevan de forma específica la información gustativa hacia el área 43 de Brodmann.","Son núcleos motores dedicados exclusivamente a la miosis pupilar.","Inervan las glándulas salivales submandibular y sublingual."],"answer":0,"explanation":"No incluida en el material.","hack":"Los Núcleos Intralaminares (Centromediano) no proyectan a un área cortical única, sino que envían proyecciones difusas a todo el manto neocortical, participando en el mantenimiento de la consciencia, el estado de vigilia y la percepción afectivo-difusa del dolor crónico.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-039 / G0083 del banco canónico | integración: Tema 1.5.1 + Tema 1.6 + Tema 1.7 + Tema 1.9.2 + Tema 1.9.3 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte2.pdf | referencias indicadas: 10-30 Clase magistral_ Neuroanatomía meníngea / NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #48) / TEMA 5 – DIENCÉFALO .pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-107","number":"107","statement":"En las clases magistrales se explica la modulación de la excitabilidad talámica por parte de la formación reticular troncoencefálica (complejo ponto-mesencefálico tegmental). ¿Cuál es el mecanismo neurológico mediante el cual este complejo promueve el estado de alerta cortical?:","options":["Inactiva transitoriamente al Núcleo Reticular del Tálamo (NRT), desinhibiendo a los núcleos de relevo talámico para que transmitan información hacia la corteza cerebral (vigilia).","Estimula directamente la secreción de GABA en la corteza motora primaria.","Destruye los plexos coroideos del tercer ventrículo.","Inerva los músculos estriados de la pierna."],"answer":0,"explanation":"No incluida en el material.","hack":"El Complejo Ponto- Mesencefálico Tegmental (colinérgico) envía axones al Núcleo Reticular del Tálamo (NRT). Al bloquear la inhibición GABAérgica del NRT sobre los núcleos de relevo, el tálamo \"abre la puerta\" e inunda la corteza de señales, generando el patrón electroencefálico de vigilia y desincronización.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-040 / G0087 del banco canónico | integración: Tema 1.5.1 + Tema 1.6 + Tema 1.7 + Tema 1.8 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte2.pdf | referencias indicadas: 10-01C~1.MP3 / 10-30 Clase magistral_ Neuroanatomía meníngea / TEMA 5 – DIENCÉFALO .pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-108","number":"108","statement":"La habénula (núcleo habenular) se ubica en el epitálamo y actúa como un centro de integración entre el sistema límbico y el tronco. ¿A través de qué importante fascículo eferente envía sus axones hacia el núcleo interpeduncular del mesencéfalo para modular las vías dopaminérgicas y serotoninérgicas?:","options":["Fascículo retroflexo de Meynert (tracto habenulo-interpeduncular)","Fascículo mamilotalámico de Vicq d'Azyr","Fórnix","Comisura blanca anterior"],"answer":0,"explanation":"No incluida en el material.","hack":"Eferencia clave de la Habénula: Fascículo Retroflexo de Meynert (vía habenulo-interpeduncular). Conecta el epitálamo con el núcleo interpeduncular del mesencéfalo, regulando respuestas de aversión, decepción y modulación de dopamina/serotonina.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-041 / G0093 del banco canónico | integración: Tema 1.5.1 + Tema 1.6 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte2.pdf | referencias indicadas: 09-30 Clase_ Diencéfalo - Tálamo, Hipotálamo y Epitálamo.mp / TEMA 5 – DIENCÉFALO .pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-109","number":"109","statement":"La decusación de las pirámides (cruzamiento del 80-90% de las fibras eferentes del tracto corticoespinal) se produce anatómicamente a nivel de:","options":["El bulbo raquídeo (porción inferior/caudal).","La protuberancia (puente de Varolio).","El mesencéfalo (pedúnculos cerebrales).","El diencéfalo."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q9)] Hack de Localización Fija de la Decusación: La profesora Aitana enfatiza en clase la trayectoria del tracto corticoespinal: desciende por los pedúnculos cerebrales en el mesencéfalo, atraviesa fragmentado la porción basilar de la protuberancia y forma las elevaciones prominentes llamadas pirámides en la superficie anterior del bulbo raquídeo. Es justamente en la porción más caudal del bulbo raquídeo donde tiene lugar la decusación piramidal, dando origen al tracto corticoespinal lateral de la médula.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-042 / G0097 del banco canónico | integración: Tema 1.5.1 + Tema 1.9.1 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte3.pdf | referencias indicadas: wuolah-free-tema-3-preguntas.pdf (Pregunta #1) / 12-04 Clase magistral_ Tracto corticoespinal / wuolah-free-examenes-2011.pdf (Pregunta #1)","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-110","number":"110","statement":"Respecto al origen y trayecto de las fibras arciformes internas en el tronco del encéfalo, señale la afirmación CORRECTA:","options":["Nacen en los núcleos grácil y cuneiforme del bulbo raquídeo, cruzan la línea media y forman el lemnisco medial.","Nacen en la oliva superior de la protuberancia y forman el lemnisco lateral.","Originan las fibras tectoespinales que descienden directamente al cordón posterior.","Son fibras corticoespinales que inervan el núcleo motor del facial."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q10)] Hack de Inversión Lemniscal (Pregunta Trampa de Examen): En las opciones falsas de los exmenes antiguos, la banca coloca afirmaciones como \"las fibras arciformes internas forman el lemnisco lateral\" o \"las fibras tectoespinales forman el lemnisco medial\". Las fibras arciformes internas son los axones de las segundas neuronas de la vía del cordón posterior (cuyos somas están en los núcleos grácil y cuneiforme del bulbo posterior). Al salir de estos núcleos, describen una trayectoria arqueada hacia adelante, decusan la línea media y ascienden formando el lemnisco medial rumbo al tálamo VPL. || [Explicación 2 (Neuro_Adicional_Parte3.pdf Q10)] Hack de Inversión Lemniscal (Pregunta Trampa de Examen): En las opciones falsas de los exmenes antiguos, la banca coloca afirmaciones como \"las fibras arciformes internas forman el lemnisco lateral\" o \"las fibras tectoespinales forman el lemnisco medial\"6.Las fibras arciformes internas son los axones de las segundas neuronas de la vía del cordón posterior (cuyos somas están en los núcleos grácil y cuneiforme del bulbo posterior). Al salir de estos núcleos, describen una trayectoria arqueada hacia adelante, decusan la línea media y ascienden formando el lemnisco medial rumbo al tálamo VPL.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-043 / G0098 del banco canónico | integración: Tema 1.5.1 + Tema 1.10 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte3.pdf | referencias indicadas: Tema 1.5.1 - Tronco del encéfalo 25-26.pdf / 09-19C~1.MP3 / wuolah-free-Examen-Neuro- 3.pdf (Pregunta #78) / wuolah-free-tema-3-preguntas.pdf (Pregunta #12)","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-111","number":"111","statement":"En el suelo de la fosa romboidea (porción pontina), ¿qué estructura produce la prominencia denominada \"colículo facial\" (eminencia teres)?:","options":["Las fibras eferentes del nervio facial (VII) al rodear o hacer un bucle (rodilla del facial) alrededor del núcleo del nervio abducens (VI).","El soma del núcleo motor del facial al situarse por encima del acueducto de Silvio.","El núcleo del tracto solitario rodeado por las fibras del nervio glosofaríngeo.","La masa principal del núcleo coclear dorsal."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q12)] Hack de la Falsa Anatomía del Colículo Facial: La banca intenta inducir al error sugiriendo que el colículo facial está formado \"exclusivamente por el núcleo del facial\". Realidad anatómica: El núcleo motor del VII par se sitúa más ventrolateralmente en el tegmento pontino. Lo que abulta en el suelo del IV ventrículo y crea la elevación llamada colículo facial son las axones eferentes del VII par que ascienden y rodean medialmente por detrás al núcleo del VI par (Abducens). || [Explicación 2 (Neuro_Adicional_Parte3.pdf Q12)] Hack de la Falsa Anatomía del Colículo Facial: La banca intenta inducir al error sugiriendo que el colículo facial está formado \"exclusivamente por el núcleo del facial\"6.Realidad anatómica: El núcleo motor del VII par se sitúa más ventrolateralmente en el tegmento pontino. Lo que abulta en el suelo del IV ventrículo y crea la elevación llamada colículo facial son las axones eferentes del VII par que ascienden y rodean medialmente por detrás al núcleo del VI par (Abducens).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-044 / G0100 del banco canónico | integración: Tema 1.5.1 + Tema 1.5.2 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte3.pdf | referencias indicadas: 09-29 Clase de Anatomía_ Nervios V, VI y VII / TEMA 3 – TRONCO DEL ENCÉFALO.pdf / PHOTO-2025-11-06-11-01-30 (2).jpg (Pregunta #24)","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-112","number":"112","statement":"El núcleo olivar inferior es la gran masa de sustancia gris que forma la oliva en la cara anterolateral del bulbo raquídeo. ¿Cuál es su principal destino de proyección eferente y a través de qué pedúnculo accede a él?:","options":["Envía fibras trepadoras hacia la corteza del cerebelo a través del pedúnculo cerebeloso inferior (cuerpo restiforme).","Envía fibras auditivas directamente al cuerpo geniculado medial del tálamo por el pedúnculo superior.","Proyecta al área motora primaria por la cápsula extrema.","Inerva los músculos extrínsecos del ojo a través del fascículo longitudinal medial."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q13)] Hack de Confusión Olivar (Inferior vs. Superior): Oliva Superior (Protuberancia): Vía AUDITIVA (procesa la localización de la fuente sonora en el plano horizontal). Oliva Inferior (Bulbo Raquídeo): Vía MOTOR-CEREBELOSA (es el origen masivo de las fibras trepadoras que entran al cerebelo a través del pedúnculo cerebeloso inferior para el aprendizaje y corrección del movimiento). (¡La trampa más repetida por la profesora Aitana es poner 'información auditiva' como función de la oliva inferior en el examen!).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-045 / G0101 del banco canónico | integración: Tema 1.5.1 + Tema 1.9.3 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte3.pdf | referencias indicadas: 09-19C~1.MP3 / 09-25 Clase_ Neuroanatomía del Mesencéfalo / wuolah-free-Examen-Neuro-1 (1).pdf (Pregunta #2)","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-113","number":"113","statement":"De las siguientes estructuras pertenecientes a la vía auditiva ascendente, ¿cuál se encuentra localizada en la posición más superior (rostral / diencefálica)?:","options":["Núcleo geniculado medial del tálamo","Colículo inferior del mesencéfalo","Lemnisco lateral","Complejo olivar superior de la protuberancia"],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q14)] Hack del Eje Craniocaudal en las Vías Sensoriales (Aviso de Examen de Aitana): Esta pregunta exige ordenar la vía auditiva de inferior (caudal) a superior (rostral): 1. Oliva Superior / Núcleos Cocleares: Protuberancia/Puente (más inferior). 2. Lemnisco Lateral: Tracto que asciende por la protuberancia hacia el mesencéfalo. 3. Colículo Inferior: Tecto del mesencéfalo. 4. Núcleo Geniculado Medial: Tálamo (Diencéfalo). Como el diencéfalo se ubica estructuralmente por encima de todo el tronco del encéfalo, el Núcleo Geniculado Medial es indiscutiblemente la estructura más superior de la lista. || [Explicación 2 (Neuro_Adicional_Parte3.pdf Q14)] Hack del Eje Craniocaudal en las Vías Sensoriales (Aviso de Examen de Aitana): Esta pregunta exige ordenar la vía auditiva de inferior (caudal) a superior (rostral): Oliva Superior / Núcleos Cocleares: Protuberancia/Puente (más inferior). Lemnisco Lateral: Tracto que asciende por la protuberancia hacia el mesencéfalo. Colículo Inferior: Tecto del mesencéfalo. Núcleo Geniculado Medial: Tálamo (Diencéfalo). Como el diencéfalo se ubica estructuralmente por encima de todo el tronco del encéfalo, el Núcleo Geniculado Medial es indiscutiblemente la estructura más superior de la lista.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-046 / G0102 del banco canónico | integración: Tema 1.5.1 + Tema 1.6 + Tema 1.11.2 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte3.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #202 y Notas) / Examem 2025 outro modelo juneka.pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-114","number":"114","statement":"En la microanatomía del mesencéfalo, la Sustancia Gris Periacueductal (PAG) rodea al acueducto cerebral. ¿Cuál es su papel neurofisiológico determinante en el control de la nocicepción?:","options":["Es el centro primordial de la vía descendente de modulación endógena del dolor, liberando encefalinas y endorfinas que proyectan a los núcleos del rafe y a la médula espinal.","Sintetiza dopamina para el circuito mesocorticolímbico de recompensa.","Origina la vía corticoespinal lateral.","Releva la sensibilidad propioceptiva consciente de la cara al tálamo VPM."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q16)] Hack de Diferenciación Mesencefálica (PAG vs. VTA): Sustancia Gris Periacueductal (PAG): Rodea al acueducto -> Modulación descendente del dolor / Analgesia endógena (vía opioide). Área Tegmental Ventral (VTA): Cerca de la línea media en el suelo del tegmento -> Neuronas dopaminérgicas del circuito mesocorticolímbico de recompensa/adicción. (¡La banca suele intercambiar las funciones de la PAG y de la VTA para confundir al estudiante en el examen!).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-047 / G0104 del banco canónico | integración: Tema 1.4 + Tema 1.5.1 + Tema 1.10 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte3.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #165) / Tema 1.5.1 - Tronco del encéfalo / 12-15 Lección_ Neurobiología del Dolor","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-115","number":"115","statement":"En la anatomía interna del mesencéfalo y del tronco encefálico, señale la afirmación INCORRECTA:","options":["El colículo superior se localiza en el tectum mesencefálico y participa en reflejos visuales.","Los núcleos grácil y cuneiforme reciben información sensorial procedente del cordón anterior de la médula espinal.","La oliva inferior se localiza en el bulbo raquídeo y envía eferencias hacia el cerebelo.","El núcleo rojo es una masa motora ubicada en el tegmento del mesencéfalo."],"answer":1,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q19)] Hack de Inversión de Cordones Medulares: Los núcleos grácil y cuneiforme (en el bulbo posterior) reciben aferencias de las neuronas pseudounipolares del CORDÓN POSTERIOR (fascículos grácil y cuneiforme), encargados de la propiocepción consciente y el tacto epicrítico. La alternativa es FALSA porque nunca reciben axones del cordón anterior.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-048 / G0107 del banco canónico | integración: Tema 1.4 + Tema 1.5.1 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte3.pdf | referencias indicadas: examenes neuro compl (1).pdf (Pregunta #22) / wuolah-free-tema-4-preguntas.pdf / NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-116","number":"116","statement":"En relación con los tractos y lemniscos que atraviesan el tronco del encéfalo, señale la afirmación INCORRECTA:","options":["El lemnisco espinal atraviesa todos los segmentos del tronco del encéfalo.","El lemnisco medial se origina a nivel de la protuberancia.","El lemnisco trigeminal transporta información somatosensitiva de la cara.","El lemnisco lateral no se encuentra en el bulbo raquídeo."],"answer":1,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q21)] Hack del Origen Falso del Lemnisco Medial: El lemnisco medial se origina en el BULBO RAQUÍDEO inmediatamente después de que las fibras arciformes internas cruzan y decusan la línea media desde los núcleos grácil y cuneiforme. Afirmar que \"nace o se origina en la protuberancia\" es la mentira estándar usada por los profesores en los exámentes para evaluar la vía dorsal.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-049 / G0109 del banco canónico | integración: Tema 1.5.1 + Tema 1.10 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte3.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #27, #167) / perguntas neuro julio exame.docx (Pregunta #16, #21)","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-117","number":"117","statement":"Respecto a la configuración externa y cavidades del mesencéfalo, es CORRECTO afirmar que:","options":["El nervio troclear (IV par) emerge por debajo de los colículos inferiores en la superficie posterior (dorsal).","La cavidad interior del mesencéfalo se denomina cuarto ventrículo.","La fosa interpeduncular se encuentra limitada a ambos lados por los pedúnculos cerebelosos.","El nervio oculomotor (III par) emerge desde la superficie posterior del mesencéfalo."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q22)] Hack del IV Par y del Acueducto Mesencefálico: La cavidad interior del mesencéfalo es el ACUEDUCTO CEREBRAL / DE SILVIO. La fosa interpeduncular está flanqueada lateralmente por los pedúnculos cerebrales (no cerebelosos). El III par (Oculomotor) emerge por la fosa interpeduncular en la cara ANTERIOR / VENTRAL. Únicamente el IV par (Troclear) emerge por la cara DORSAL / POSTERIOR por debajo de los colículos inferiores.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-050 / G0110 del banco canónico | integración: Tema 1.5.1 + Tema 1.5.2 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte3.pdf | referencias indicadas: examenes neuro compl (1).pdf (Pregunta #52) / Tema 1.5.1 - Tronco del encéfalo 25- 26.pdf / TEMA 3 – TRONCO DEL ENCÉFALO.pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-118","number":"118","statement":"El tracto tegmental central es un importante haz de sustancia blanca que discurre longitudinalmente por el tegmento del tronco del encéfalo. ¿Qué regiones conecta principalmente para transmitir aferencias motoras hacia el bulbo?:","options":["Conecta el núcleo rojo y los ganglios basales del mesencéfalo con el complejo olivar inferior del bulbo raquídeo.","Conecta la corteza visual con los colículos inferiores.","Conecta los núcleos vestibulares con los músculos extensores de la médula.","Conecta las pirámides bulbares con el asta posterior de la médula espinal."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q24)] Hack de la Vía Tegmental Central: La profesora Aitana explica que el tracto tegmental central es la principal vía descendente que comunica el núcleo rojo mesencefálico y el globo pálido/estriado con el núcleo olivar inferior del bulbo raquídeo. Desde allí, el complejo olivar origina las fibras trepadoras que entran al cerebelo.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-051 / G0112 del banco canónico | integración: Tema 1.5.1 + Tema 1.9.2 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte3.pdf | referencias indicadas: 09-25 Clase_ Neuroanatomía del Mesencéfalo / TEMA 3 – TRONCO DEL ENCÉFALO.pdf / Tema 1.5.1 - Tronco del encéfalo","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-119","number":"119","statement":"En la neuroquímica del ciclo sueño-vigilia, ¿cuál es el neurotransmisor promotor del sueño NREM liberado por las neuronas del núcleo preóptico ventrolateral (VLPO) del hipotálamo para inhibir los centros de la vigilia (SARA, locus coeruleus, núcleos del rafe y tuberomamilar)?:","options":["GABA (Ácido Gamma-Aminobutírico) y galanina.","Glutamato y aspartato.","Histamina y dopamina.","Norepinefrina y serotonina."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack del Núcleo VLPO (Interruptor del Sueño): El Núcleo Preóptico Ventrolateral (VLPO) del hipotálamo es el \"interruptor principal del sueño\". Sus neuronas liberan GABA y galanina (neurotransmisores inhibidores) sobre los núcleos monaminérgicos y colinérgicos del arousal (Locus Coeruleus, Rafe, Tuberomamilar), apagando la vigilia e induciendo el sueño NO REM.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-052 / G0136 del banco canónico | integración: Tema 1.5.1 + Tema 1.6 + Tema 1.8 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte3.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #182) / 10-13 Clase_ Funciones Cerebrales, Ritmos Circadianos y Sueño / Design sem nome (2).pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-120","number":"120","statement":"Respecto a la trayectoria del tracto corticoespinal anterior (directo o no decusado en el bulbo), señale la afirmación CORRECTA sobre su comportamiento al llegar a la médula espinal:","options":["Discurre por el cordón blanco anterior ipsilateral a su origen cortical, pero sus fibras decusan en la comisura blanca de los segmentos medulares de destino para sinaptar bilateralmente sobre motoneuronas del asta anterior (lámina IX) que controlan la musculatura axial y proximal del tronco.","Decusa en las pirámides bulbares y desciende por el cordón lateral para el control de la musculatura distal de los dedos.","No llega a la médula espinal y finaliza exclusivamente en el núcleo olivar superior.","Transporta únicamente sensibilidad dolorosa de la cara."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q3)] Hack del Ojo de Aitana (Decusación Bulbar vs Medular): Aitana advierte en sus clases que hay que fijarse bien si la pregunta se refiere a lo que ocurre en las pirámides o en la médula: El tracto corticoespinal anterior (10-20%) NO decusa en las pirámides del bulbo (baja por el cordón anterior del mismo lado). ¡Sin embargo, SÍ decusa dentro de la propia médula espinal a nivel del segmento meta donde va a actuar, ejerciendo un control bilateral sobre la musculatura axial ! || [Explicación 2 (Neuro_Adicional_Parte4.pdf Q3)] Hack del Ojo de Aitana (Decusación Bulbar vs Medular): Aitana advierte en sus clases que hay que fijarse bien si la pregunta se refiere a lo que ocurre en las pirámides o en la médula: El tracto corticoespinal anterior (10-20%) NO decusa en las pirámides del bulbo (baja por el cordón anterior del mismo lado). ¡Sin embargo, SÍ decusa dentro de la propia médula espinal a nivel del segmento meta donde va a actuar, ejerciendo un control bilateral sobre la musculatura axial7!","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-053 / G0155 del banco canónico | integración: Tema 1.4 + Tema 1.5.1 + Tema 1.9.1 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte4.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #41, #182) / 10-14 Clase_ Vías Motoras y Corteza Cerebral / TEMA 3 – TRONCO DEL ENCÉFALO.pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-121","number":"121","statement":"El tracto corticonuclear (corticobulbar) desciende por la rodilla de la cápsula interna para inervar los núcleos motores somáticos y branquiales de los pares craneales en el tronco del encéfalo. ¿Qué característica de inervación presenta el núcleo motor del nervio facial (VII par) que la convierte en la gran excepción del grupo?:","options":["La porción del núcleo del facial que inerva los músculos de la mitad inferior de la cara recibe inervación cortical exclusivamente contralateral, mientras que la porción para la mitad superior de la cara recibe inervación bilateral.","Todo el núcleo del facial recibe inervación exclusivamente ipsilateral.","El núcleo del facial recibe únicamente aferencias del cerebelo.","La mitad superior de la cara está inervada por el tracto rubroespinal."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q4)] Hack de la Parálisis Facial Central vs. Periférica: Generalidad corticonuclear: Inervación BILATERAL a casi todos los núcleos motores craneales (V, ambiguo, XII, etc.). EXCEPCIÓN DE EXAMEN (VII Par): La mitad superior del rostro (frente y orbicular de los ojos) recibe fibras bilaterales. La mitad inferior (boca) recibe fibras únicamente contralaterales. Un ictus en la corteza motora causa parálisis del cuadrante inferior contralateral respetando la frente (parálisis central).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-054 / G0156 del banco canónico | integración: Tema 1.5.1 + Tema 1.5.2 + Tema 1.7 + Tema 1.9.1 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte4.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #181, #182) / Tema 1.9.1 - Corteza motora / 09-26 Clase_ Nervios Craneales","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-122","number":"122","statement":"En relación con el tracto rubroespinal, una de las principales vías extrapiramidales/indirectas del control motor, señale la afirmación VERDADERA:","options":["Se origina en la porción magnocelular del núcleo rojo del mesencéfalo, decusa inmediatamente en la decusación tegmental ventral (de Forel) y desciende por el cordón blanco lateral para facilitar los músculos flexores de las extremidades superiores e inhibir los extensores.","Nace en la protuberancia caudal y no decusa en ningún punto de su trayecto.","Desciende exclusivamente por el cordón posterior de la médula espinal.","Se origina en el colículo superior y controla los movimientos de la lengua."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q5)] Hack del Núcleo Rojo y la Decusación Tegmental Ventral: Origen: Porción magnocelular del núcleo rojo (mesencéfalo). Decusación: Decusación tegmental ventral (Forel) en el propio mesencéfalo (¡NUNCA en la protuberancia ni en el bulbo!). Función: Estimula la musculatura FLEXORA e inhibe la extensora en miembros superiores (vía lateral que acompaña al corticoespinal lateral). || [Explicación 2 (Neuro_Adicional_Parte4.pdf Q5)] Hack del Núcleo Rojo y la Decusación Tegmental Ventral: Origen: Porción magnocelular del núcleo rojo (mesencéfalo). Decusación: Decusación tegmental ventral (Forel) en el propio mesencéfalo (¡NUNCA en la protuberancia ni en el bulbo!1213). Función: Estimula la musculatura FLEXORA e inhibe la extensora en miembros superiores (vía lateral que acompaña al corticoespinal lateral).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-055 / G0157 del banco canónico | integración: Tema 1.5.1 + Tema 1.9.1 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte4.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #46, #96, #139) / ex. 2 (respuestas).pdf (Pregunta #37) / 12-04 Clase_ Tractos Corticoespinal, Corticonuclear y Rubroespinal","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-123","number":"123","statement":"El tracto que nace en la formación reticular pontina medial, desciende de forma no cruzada (ipsilateral) por el cordón blanco anterior de la médula espinal y activa masivamente las motoneuronas de los músculos extensores (antigravitacionales) de las extremidades inferiores es el:","options":["Tracto reticuloespinal pontino (medial).","Tracto reticuloespinal bulbar (lateral).","Tracto rubroespinal.","Tracto corticoespinal lateral."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q6)] Hack Reticuloespinal Pontino (Extensor) vs. Bulbar (Inhibidor): Tracto Reticuloespinal Pontino (Medial): Nace en la ponte -> IPSILATERAL -> Cordón Anterior -> ACTIVA extensores (antigravitacionales) de piernas y tronco. Tracto Reticuloespinal Bulbar (Lateral): Nace en el bulbo -> BILATERAL -> Cordón Lateral -> INHIBE el tono extensor y libera flexores.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-056 / G0158 del banco canónico | integración: Tema 1.4 + Tema 1.5.1 + Tema 1.9.1 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte4.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #139, #242) / ex. 2 (respuestas).pdf (Pregunta #36) / 12-05 Clase magistral_ Tractos extrapiramidales","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-124","number":"124","statement":"Respecto a los tractos vestibuloespinales descendentes procedentes de los núcleos vestibulares del tronco del encéfalo, indique la afirmación CORRECTA:","options":["El tracto vestibuloespinal lateral desciende ipsilateralmente por toda la longitud de la médula espinal para activar los músculos extensores posturales, mientras que el tracto vestibuloespinal medial desciende bilateralmente solo hasta niveles cervicales para ajustar la posición de la cabeza.","El tracto vestibuloespinal medial desciende hasta el segmento sacro S5 para inhibir la marcha.","Ambos tractos nacen en la capa V del área 4 de Brodmann.","El tracto vestibuloespinal lateral decusa masivamente en las pirámides bulbares."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q7)] Hack Vestibuloespinal Cervical vs. Toda la Médula (Trap Recurrente): Tracto Vestibuloespinal MEDIAL: Desciende BILATERALMENTE por el FLM ÚNICAMENTE hasta metámeras CERVICALES (coordinación cabeza/cuello). Tracto Vestibuloespinal LATERAL: Desciende IPSILATERALMENTE por TODOS los niveles de la médula (activación de extensores y tono postural).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-057 / G0159 del banco canónico | integración: Tema 1.4 + Tema 1.5.1 + Tema 1.9.1 + Tema 1.11.2 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte4.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #96, #139, #242) / 12-05 Clase magistral_ Tractos extrapiramidales / ex. 2021 (respuestas).pdf (Pregunta #47)","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-125","number":"125","statement":"Durante su descenso por la sustancia blanca profunda del telencéfalo hacia el tronco del encéfalo, los axones de la vía piramidal atraviesan la cápsula interna. ¿En qué porciones específicas de la cápsula interna se sitúan las fibras del tracto corticoespinal y del tracto corticonuclear respectivamente?:","options":["El tracto corticoespinal discurre por el brazo posterior de la cápsula interna, mientras que el tracto corticonuclear atraviesa la rodilla de la cápsula interna.","El tracto corticoespinal pasa por el brazo anterior y el corticonuclear por el rodete.","Ambos tractos descienden agrupados exclusivamente por la cápsula extrema.","El tracto corticonuclear discurre posterior al tracto corticoespinal en el brazo posterior."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q9)] Hack de la Cápsula Interna (Rodilla vs. Brazo Posterior): La profesora Aitana enfatiza la somatotopía en la cápsula interna: Rodilla de la cápsula interna: Punto de paso específico del Tracto Corticonuclear (fibras para la región craneofacial). Brazo posterior (ramo posterior): Punto de paso específico del Tracto Corticoespinal (fibras para extremidades y tronco). La banca invierte las posiciones afirmando que el corticonuclear va por el brazo posterior.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-058 / G0161 del banco canónico | integración: Tema 1.5.1 + Tema 1.7 + Tema 1.9.1 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte4.pdf | referencias indicadas: Tema 1.9.1 - Corteza motora y vías motoras descendentes 25-26.pdf / 12-04 Clase_ Tractos Corticoespinal, Corticonuclear / 10-15 Clase_ Vías Motoras Descendentes.mp","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-126","number":"126","statement":"Respecto al tracto tectoespinal, una de las vías motoras indirectas o extrapiramidales, señale la opción CORRECTA sobre su origen, decusación y nivel de finalización en la médula espinal:","options":["Se origina en el colículo superior del mesencéfalo, cruza la línea media en la decusación tegmental dorsal y desciende por el cordón anterior únicamente hasta los segmentos cervicales y torácicos superiores para coordinar reflejos oculocervicales.","Nace en el colículo inferior del bulbo raquídeo y desciende hasta el segmento sacro S5.","Se origina en la oliva inferior y no decusa en ningún punto del tronco.","Desciende por el cordón posterior para la sensibilidad táctil."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q11)] Hack del Falso Colículo Inferior e Intruso Lumbar: Las dos trampas más comunes de los exámentes son: 1. Afirmar que \"nace en el colículo inferior\" (FALSO: el inferior es auditivo; el tectoespinal nace en el colículo SUPERIOR visual). 2. Afirmar que \"recorre toda la médula\" (FALSO: solo llega a niveles cervicales/torácicos altos para mover cuello y cabeza). || [Explicación 2 (Neuro_Adicional_Parte4.pdf Q11)] Hack del Falso Colículo Inferior e Intruso Lumbar: Las dos trampas más comunes de los exámentes son: Afirmar que \"nace en el colículo inferior\" (FALSO: el inferior es auditivo; el tectoespinal nace en el colículo SUPERIOR visual). Afirmar que \"recorre toda la médula\" (FALSO: solo llega a niveles cervicales/torácicos altos para mover cuello y cabeza).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-059 / G0163 del banco canónico | integración: Tema 1.4 + Tema 1.5.1 + Tema 1.9.1 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte4.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #42, #181, #242) / 12-05 Clase magistral_ Tractos extrapiramidales / TEMA 3 – TRONCO DEL ENCÉFALO.pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-127","number":"127","statement":"Una paciente ingresada en coma tras sufrir un traumatismo craneoencefálico severo muestra ante un estímulo nociceptivo una postura anormal caracterizada por extensión tónica de las extremidades inferiores y flexión tónica fija de las extremidades superiores (postura de decorticación). ¿Dónde se localiza la lesión encefálica?:","options":["En el tronco encefálico por ENCIMA del núcleo rojo (conservando la función del tracto rubroespinal sobre los flexores de los brazos).","En el tronco encefálico por DEBAJO del núcleo rojo.","En el cono medular lumbar L5.","En la cauda equina."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q13)] Hack de la Altura de la Lesión (Decorticación vs. Descerebración): Lesión POR ENCIMA del Núcleo Rojo (Decorticación): El núcleo rojo está indemne -> el tracto rubroespinal estimula la FLEXIÓN de los brazos, mientras que las piernas quedan extendidas por los tractos vestibuloespinales. Lesión POR DEBAJO del Núcleo Rojo (Descerebración): Se destruye el núcleo rojo -> se pierde la flexión y se produce EXTENSIÓN TÓNICA DE LAS CUATRO EXTREMIDADES.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-060 / G0165 del banco canónico | integración: Tema 1.5.1 + Tema 1.9.1 + Tema 1.10 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte4.pdf | referencias indicadas: wuolah-free-Examen-Neuro-2.pdf (Pregunta #30) / wuolah-free-Examen-Neuro-3.pdf (Pregunta #39) / 12-04 Clase_ Tractos Corticoespinal, Corticonuclear y Rubroespinal- transcript.txt","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-128","number":"128","statement":"Respecto a la vía extrapiramidal y la modulación del tono muscular, señale la afirmación VERDADERA sobre el tracto reticuloespinal bulbar (lateral):","options":["Se origina en la formación reticular del bulbo raquídeo, desciende por el cordón lateral y ejerce una acción inhibitoria sobre los músculos extensores, modulando el tono muscular a través de sus contactos con motoneuronas gamma.","Nace en la protuberancia y estimula masivamente la extensión de las piernas.","Se origina en el área 4 y forma las pirámides bulbares.","Es un tracto puramente gustativo que finaliza en el núcleo solitario."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q16)] Hack Antagónico Reticular (Pontino vs. Bulbar): Reticuloespinal Pontino (Medial): Nace en puente -> Cordón anterior -> ACTIVADOR de extensores. Reticuloespinal Bulbar (Lateral): Nace en bulbo -> Cordón lateral -> INHIBIDOR de extensores (modula el tono reflejo actuando sobre motoneuronas gamma).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-061 / G0168 del banco canónico | integración: Tema 1.5.1 + Tema 1.9.1 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte4.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #242) / 12-05 Clase magistral_ Tractos extrapiramidales / wuolah-free-EXAMEN-2017-2018-1.pdf (Pregunta #16)","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-129","number":"129","statement":"La dopamina proyectada desde la Sustancia Negra pars compacta (SNpc) hacia el neoestriado ejerce un efecto modulador dual sobre el movimiento. ¿Cómo actúa la dopamina sobre las dos vías motoras de los ganglios basales?:","options":["Excita la vía directa al unirse a receptores D1 en el estriado e inhibe la vía indirecta al unirse a receptores D2, favoreciendo globalmente la motilidad.","Inhibe la vía directa mediante receptores D1 y activa la vía indirecta por receptores D2.","Bloquea la liberación de GABA en el tálamo actuando sobre receptores muscarínicos.","Inactiva la corteza motora primaria directamente."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q5)] Hack de la Acción Dual Dopaminérgica (D1 vs D2): Receptores D1: Presentes en neuronas estriatales de la vía directa -> Efecto EXCITADOR -> Potencia el movimiento. Receptores D2: Presentes en neuronas estriatales de la vía indirecta -> Efecto INHIBIDOR -> Desactiva el freno motor. Resultado: Ambas acciones de la dopamina se suman para FACILITAR EL MOVIMIENTO CORTICAL.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-062 / G0173 del banco canónico | integración: Tema 1.5.1 + Tema 1.9.2 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte4.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #99, #209, #245) / wuolah- free-Examen-Neuro-3.pdf (Pregunta #10) / 10-16 Clase_ Ganglios Basales y Circuitos Motores","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-130","number":"130","statement":"En la patofisiología de la Enfermedad de Parkinson, la destrucción progresiva de las neuronas dopaminérgicas de la sustancia negra pars compacta rompe el equilibrio funcional de los ganglios basales. ¿Qué alteración de circuito explica los síntomas hipocinéticos (acinesia, rigidez y bradicinesia)?:","options":["Pérdida de la estimulación D1 en la vía directa y pérdida de la inhibición D2 en la vía indirecta, provocando una sobreactivación tónica del Globo Pálido Interno que inhibe masivamente al tálamo motor.","Destrucción masiva de interneuronas colinérgicas dentro del globo pálido interno.","Hipertrofia del núcleo caudado con liberación masiva de dopamina a la corteza.","Desaparición del núcleo subtalámico con abolición del GABA."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack del Falso Detalle en Parkinson (Trampa de Aitana): En las alternativas de examen, la banca coloca como distractor que el Parkinson ocurre \"por la destrucción de interneuronas colinérgicas del globo pálido interno\". ¡FALSO! El Parkinson se debe a la pérdida de neuronas dopaminérgicas de la sustancia negra pars compacta.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-063 / G0174 del banco canónico | integración: Tema 1.5.1 + Tema 1.6 + Tema 1.9.2 + Tema 1.11.2 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte4.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #99, #100) / ex. 2 (respuestas).pdf (Pregunta #42) / 10-16 Aula_ Ganglios Basales y Patologías del Movimiento","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-131","number":"131","statement":"Además del control de los músculos esqueléticos del tronco y extremidades, los ganglios basales participan en la regulación de los movimientos oculares sacádicos voluntarios. ¿Qué porción de la Sustancia Negra actúa como núcleo de salida (output) primordial en el circuito oculomotor?:","options":["Sustancia Negra pars reticulata (SNr), enviando eferencias GABAérgicas hacia el colículo superior.","Sustancia Negra pars compacta (SNpc), enviando acetilcolina a la retina.","Núcleo caudado posterior, enviando noradrenalina al núcleo Edinger-Westphal.","Putamen ventral, proyectando al oído interno."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack del Circuito Oculomotor (SNr vs GPi): La profesora Aitana explica en audio que mientras el Globo Pálido Interno (GPi) es el núcleo de salida principal para el cuerpo, en el circuito oculomotor la Sustancia Negra pars reticulata (SNr) asume el papel dominante proyectando directamente sobre el colículo superior del mesencéfalo.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-064 / G0176 del banco canónico | integración: Tema 1.5.1 + Tema 1.9.2 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte4.pdf | referencias indicadas: 09-30 Clase de Neuroanatomía_ Tálamo, Sistema Límbico y Ganglios Basales / 10-15 Clase_ Ganglios Basales / NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #99, #100)","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-132","number":"132","statement":"Respecto a las vías motoras descendentes indirectas/extrapiramidales, señale la afirmación VERDADERA:","options":["Las fibras del tracto rubroespinal nacen en la porción magnocelular del núcleo rojo del mesencéfalo y decusan a nivel del propio mesencéfalo (decusación tegmental ventral de Forel).","El tracto tectoespinal nace en el colículo inferior de la protuberancia.","El tracto rubroespinal decusa en la porción caudal de la protuberancia.","El tracto vestibuloespinal inerva únicamente a los músculos flexores de la pierna contralateral."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de la Decusación de Forel del Tracto Rubroespinal: El tracto rubroespinal decusa en el MESENCÉFALO (decusación tegmental ventral de Forel). La banca intenta confundir afirmando que decusa en la protuberancia.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-065 / G0180 del banco canónico | integración: Tema 1.5.1 + Tema 1.9.1 + Tema 1.9.2 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte4.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #96, #139) / wuolah-free- EXAMEN-2017-2018-1 (1).pdf (Pregunta #15, #16) / Recopilación preguntas neuro (1).pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-133","number":"133","statement":"Sobre la estructura y contenido axonal de las pirámides del bulbo raquídeo, señale la afirmación CIERTA:","options":["Contienen los axones descendentes no decusados del tracto corticoespinal anterior que decusarán posteriormente en los niveles medulares de destino.","En ellas encontramos los axones del tracto corticorrúbrico.","El tracto corticoespinal lateral representa la población axonal minoritaria en las pirámides.","En la pirámide izquierda, por encima de la decusación, encontramos axones procedentes de la corteza motora secundaria derecha."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q22)] Hack de la Decusación Bulbar vs. Medular: En las pirámides bulbares superiores, o sea antes de la decusación piramidal, las fibras son 100% ipsilaterales. El ~80-90% cruza en la decusación piramidal (corticoespinal lateral) e el ~10-20% continúa directo como corticoespinal anterior, decusando más abajo en la comisura blanca de la médula.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-066 / G0182 del banco canónico | integración: Tema 1.5.1 + Tema 1.9.1 + Tema 1.9.2 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte4.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #189) / perguntas neuro julio exame.docx (Pregunta #38) / 09-19C~1.MP3","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-134","number":"134","statement":"Señale la afirmación VERDADERA sobre las características del tracto tectoespinal:","options":["Nace en las capas profundas del colículo superior del mesencéfalo, decusa en el tegmento mesencefálico (decusación dorsal de Meynert) y participa en el control reflejo de la cabeza y cuello ante estímulos visuales.","Nace en el colículo inferior del tectum mesencefálico.","Desciende por el cordón posterior de la médula espinal.","Es el tracto responsable de la propiocepción consciente de la mano."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q27)] Hack de los Colículos en Vías Motoras: El tracto tectoespinal nace en el colículo SUPERIOR (integración visual). Afirmar que \"nace en el colículo inferior\" (que es auditivo) es la trampa clásica.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-067 / G0187 del banco canónico | integración: Tema 1.5.1 + Tema 1.9.1 + Tema 1.9.2 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte4.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #42, #96) / EXAMEN NEURO (1).pdf (Pregunta #44, #45) / wuolah-free-EXAMEN-2017-2018-1 (1).pdf (Pregunta #16)","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-135","number":"135","statement":"Analice las siguientes afirmaciones sobre las vías motoras descendentes extraídas de las opciones de los exámenes oficiales. Indique cuál es la ÚNICA afirmación VERDADERA:","options":["Las fibras del tracto rubroespinal nacen en el mesencéfalo y decusan en el propio mesencéfalo (decusación tegmental ventral de Forel).","El tracto tectoespinal nace en el colículo inferior de la protuberancia.","El tracto vestibuloespinal medial desciende por toda la médula hasta metámeras sacras.","Las fibras del tracto corticoespinal anterior nunca decusan, ni en el bulbo ni en la médula espinal."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q35)] Hack de Gran Resumen del || [Explicación 2 (Neuro_Adicional_Parte4.pdf Q35)] Hack de Gran Resumen del Tema 1.9.1:Option A (VERDADERA): Rubroespinal = Mesencéfalo + Decusación de Forel. Option B (FALSA): Tectoespinal = Nace en Colículo SUPERIOR.Option C (FALSA): Vestibuloespinal Medial = Solo llega a niveles CERVICALES.Option D (FALSA): Corticoespinal Anterior = Decusa abajo en la comisura blanca de la médula.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-068 / G0195 del banco canónico | integración: Tema 1.5.1 + Tema 1.9.1 + Tema 1.9.2 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Adicional_Parte4.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Preguntas #41, #42, #43, #96, #97, #138, #139, #157, #158, #181, #182, #189, #190, #207, #242) / 08_Tema_1.9.1...docx","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-136","number":"136","statement":"En el trayecto descendente del tracto corticoespinal a través del tronco del encéfalo, ¿cuál es la disposición somatotópica de las fibras nerviosas a nivel de los pedúnculos cerebrales del mesencéfalo (pie peduncular)?:","options":["Las fibras para el miembro inferior se sitúan en la porción más lateral del pie peduncular, mientras que las fibras para el miembro superior y cara se ubican medialmente.","Las fibras para el miembro inferior ocupan el tercio medial del pie peduncular.","Las fibras corticoespinales se disponen al azar sin somatotopía en el mesencéfalo.","Las fibras corticonucleares ocupan el tercio lateral del pie peduncular."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q36)] Hack Somatotópico del Pie Peduncular (Mesencéfalo): En el pie peduncular (tercio medio del pedúnculo cerebral): Medial: Fibras corticonucleares (cara) y fibras cervicales (brazo). Lateral: Fibras lumbosacras (pierna/pie). La banca invierte la somatotopía afirmando que \"las piernas van por el lado medial\". ¡FALSO! Las piernas van laterales.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-069 / G0210 del banco canónico | integración: Tema 1.5.1 + Tema 1.9.1 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Archivo3_Parte1.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #189) / 08_Tema_1.9.1...docx (Pregunta #45) / 12-04 Clase magistral_ Tracto corticoespinal","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-137","number":"137","statement":"Respecto a la neurotransmisión y las aferencias que recibe el neoestriado (núcleo caudado y putamen), señale la afirmación CORRECTA:","options":["Recibe aferencias glutamatérgicas excitadoras de la corteza cerebral y del tálamo, y aferencias dopaminérgicas de la sustancia negra pars compacta.","Recibe únicamente axones GABAérgicos de la médula espinal.","Sus principales aferencias son noradrenérgicas procedentes del locus coeruleus.","La corteza motora libera GABA para inhibir directamente al putamen."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q10)] Hack de las Aferencias Estriatales (Input): El Estriado (Caudado + Putamen) es el principal núcleo de ENTRADA (input) de los ganglios basales. Recibe: 1. Corteza cerebral: Glutamatérgica (+). 2. Tálamo: Glutamatérgica (+). 3. Sustancia Negra pars compacta (SNpc): Dopaminérgica (moduladora). || [Explicación 2 (Neuro_Archivo3_Parte1.pdf Q10)] Hack de las Aferencias Estriatales (Input): El Estriado (Caudado + Putamen) es el principal núcleo de ENTRADA (input) de los ganglios basales. Recibe: Corteza cerebral: Glutamatérgica (+). Tálamo: Glutamatérgica (+). Sustancia Negra pars compacta (SNpc): Dopaminérgica (moduladora).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-070 / G0214 del banco canónico | integración: Tema 1.5.1 + Tema 1.6 + Tema 1.7 + Tema 1.9.2 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Archivo3_Parte1.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #118) / 10-16 Clase_ Ganglios Basales y Circuitos Motores / Tema 1.9.2 - Ganglios basales y movimiento","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-138","number":"138","statement":"Respecto a la anatomía e histología de la Sustancia Negra en el mesencéfalo, señale la afirmación VERDADERA:","options":["La porción compacta (pars compacta) contiene neuronas dopaminérgicas con inclusiones de neuromelanina, mientras que la porción reticular (pars reticulata) contiene neuronas GABAérgicas sin pigmento.","La pars compacta se localiza lateralmente al putamen en el telencéfalo.","La pars reticulata libera únicamente acetilcolina a la retina.","La pars compacta pertenece al cerebelo."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q16)] Hack de la Bipartición de la Sustancia Negra: Pars Compacta: Dorsal/posterior -> Dopaminérgica + Neuromelanina (destruida en Parkinson). Pars Reticulata: Ventral/anterior -> GABAérgica (análoga al GPi).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-071 / G0220 del banco canónico | integración: Tema 1.5.1 + Tema 1.9.2 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Archivo3_Parte1.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #98, #208) / 09-24 Clase_ Estructuras del Mesencéfalo / TEMA 9 – GANGLIOS BASLES Y MOVIMIENTO.pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-139","number":"139","statement":"En la vía indirecta de los ganglios basales, ¿cuál es el único núcleo intrínseco de naturaleza GLUTAMATÉRGICA (excitadora) y sobre qué estructuras proyecta sus axones?:","options":["El Núcleo Subtalámico (STN), que proyecta axones excitadores sobre el Globo Pálido Interno (GPi) y la Sustancia Negra pars reticulata.","El Globo Pálido Externo sobre el tálamo.","El Núcleo Caudado sobre la médula espinal.","El Núcleo Accumbens sobre el cerebelo."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack del STN Glutamatérgico: Todos los núcleos de los ganglios basales son GABAérgicos (inhibidores), EXCEPTO el Núcleo Subtalámico, que es el ÚNICO excitador (Glutamato).","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-072 / G0227 del banco canónico | integración: Tema 1.5.1 + Tema 1.6 + Tema 1.9.2 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Archivo3_Parte1.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #210, #265) / 10-16 Clase_ Ganglios Basales / TEMA 9 – GANGLIOS BASLES Y MOVIMIENTO.pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-140","number":"140","statement":"Además del control somático de las extremidades, los ganglios basales regulan los movimientos oculares sacádicos. ¿Qué estructura actúa como estación de salida principal en el circuito oculomotor proyectando sobre el colículo superior?:","options":["Sustancia Negra pars reticulata (SNr).","Núcleo caudado anterior.","Globo pálido externo.","Núcleo olivar inferior."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q24)] Hack de la SNr y Movimientos Oculares (Aitana): En el cuerpo el núcleo de salida dominante es el GPi, pero para los movimientos oculares sacádicos el núcleo de salida principal es la Sustancia Negra pars reticulata (SNr) proyectando al colículo superior.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-073 / G0228 del banco canónico | integración: Tema 1.5.1 + Tema 1.9.2 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Archivo3_Parte1.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #99, #100) / 09-24 Clase_ Estructuras del Mesencéfalo / 10-16 Aula_ Ganglios Basales","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-141","number":"141","statement":"Respecto al origen, trayecto y sinapsis de las fibras trepadoras del cerebelo, señale la afirmación CORRECTA:","options":["Se originan exclusivamente en el núcleo olivar inferior del bulbo raquídeo, trepan por el árbol dendrítico de las neuronas de Purkinje y ejercen una potente acción sináptica excitadora (potenciales de acción complejos) clave en la corrección de errores motores.","Proceden de la médula espinal y hacen sinapsis directa con las células granulares.","Liberan GABA sobre el núcleo dentado para inhibir la corteza motora.","Se originan en los núcleos vestibulares y forman el pedúnculo cerebeloso medio."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q2)] Hack de las Fibras Trepadoras y la Oliva Inferior: Único Origen: Núcleo Olivar Inferior (Bulbo raquídeo). Acción: Excitadora masiva sobre el árbol dendrítico de Purkinje (1 fibra trepadora inerva 1 sola célula de Purkinje con miles de contactos sinápticos).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-074 / G0238 del banco canónico | integración: Tema 1.5.1 + Tema 1.9.3 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Archivo3_Parte1.pdf | referencias indicadas: ex. 2 (respuestas).pdf (Pregunta #40) / NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #247) / 10-17 Clase magistral_ Circuitería del cerebelo","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-142","number":"142","statement":"Respecto a las características anatómicas y funcionales del Pedúnculo Cerebeloso Medio (Brachium pontis), señale la afirmación CORRECTA:","options":["Es el pedúnculo más voluminoso y constituye una vía predominantemente AFERENTE al cerebelo formada por axones pontocerebelosos transversos procedentes de los núcleos del puente contralaterales.","Es una vía puramente eferente que conecta el núcleo dentado con el tálamo.","Transporta únicamente la sensibilidad dolorosa de la cara.","Está formado por las fibras del tracto espinocerebeloso posterior."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack del Pedúnculo Medio Aferente: El Pedúnculo Cerebeloso Medio une la protuberancia con el cerebelo y es 100% AFERENTE (vía corticopontocerebelosa para el cerebrocerebelo).","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-075 / G0242 del banco canónico | integración: Tema 1.5.1 + Tema 1.9.3 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Archivo3_Parte1.pdf | referencias indicadas: Exame Neuro 2022.pdf (Pregunta #42) / Recopilación preguntas neuro (1).pdf / 10-17 Clase magistral_ Vía retinohipotalámica y circuitería del cerebelo","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-143","number":"143","statement":"Respecto al Pedúnculo Cerebeloso Superior (Brachium conjunctivum), señale la afirmación VERDADERA:","options":["Es la principal vía de salida (eferente) del cerebelo, transportando axones desde el núcleo dentado e interpósitos hacia el núcleo rojo contralateral y hacia el núcleo ventral lateral (VL) del tálamo.","Es una vía 100% aferente que nace en el núcleo coclear.","Une el cerebelo con el bulbo raquídeo caudal.","Transporta únicamente fibras parasimpáticas para el estómago."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack Eferente del Pedúnculo Superior: El Pedúnculo Cerebeloso Superior conecta el cerebelo con el mesencéfalo y diencéfalo. Es la vía eferente primaria (haces dentadotalámico e interpuestorrúbrico).","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-076 / G0250 del banco canónico | integración: Tema 1.5.1 + Tema 1.6 + Tema 1.9.3 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Archivo3_Parte1.pdf | referencias indicadas: Recopilación preguntas neuro (1).pdf / 10-17 Clase magistral_ Circuitería del cerebelo / NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-144","number":"144","statement":"Sobre la anatomía topográfica de la fosa romboidea y su relación con el cerebelo, señale la afirmación CORRECTA:","options":["Se encuentra limitada lateralmente por los pedúnculos cerebelosos y constituye el suelo del cuarto ventrículo, quedando expuesta al retirar el cerebelo.","Constituye el techo del tercer ventrículo.","Se ubica en la cara anterior del pie peduncular mesencefálico.","Contiene únicamente fibras motoras del tracto corticoespinal."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de la Fosa Romboidea y el 4º Ventrículo: La fosa romboidea es el suelo del 4º ventrículo (ubicado en la superficie dorsal del puente y bulbo). El cerebelo forma su techo.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-077 / G0251 del banco canónico | integración: Tema 1.5.1 + Tema 1.9.3 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Archivo3_Parte1.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #25, #270) / Examem 2025 outro modelo juneka.pdf (Pregunta #52) / 09-19C~1.MP3","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-145","number":"145","statement":"Además de proyectar sobre los núcleos cerebelosos profundos, las neuronas de Purkinje de la corteza del vestibulocerebelo (lóbulo flóculo-nodular) envían axones eferentes inhibidores GABAérgicos directamente hacia:","options":["Los núcleos vestibulares del tronco del encéfalo (protuberancia y bulbo).","Las astas anteriores de la médula espinal sacra.","El núcleo caudado.","El quiasma óptico."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de la Eferencia Directa al Tronco: Las células de Purkinje del lóbulo flóculo-nodular son la única excepción que no sinapta en los núcleos profundos cerebelosos: envían sus axones inhibidores directamente a los núcleos vestibulares.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-078 / G0257 del banco canónico | integración: Tema 1.5.1 + Tema 1.9.3 + Tema 1.11.2 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Archivo3_Parte1.pdf | referencias indicadas: 12-10 Clase_ Microanatomía y Fisiología del Cerebelo / Examem 2025 outro modelo juneka.pdf (Pregunta #27) / NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-146","number":"146","statement":"En la circuitería aferente del cerebelo, las fibras musgosas ingresan desde la médula, puente y núcleos vestibulares. ¿Sobre qué elemento realizan su sinapsis directa excitadora dentro de la corteza?:","options":["Sobre las dendritas de las células granulares en el glomérulo cerebeloso.","Directamente sobre el soma de la célula de Purkinje en la capa molecular.","Sobre las células piramidales de Betz.","Sobre los capilares de la piamadre."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de la Sinapsis de Fibras Musgosas: Las fibras musgosas NO tocan directamente a Purkinje; hacen sinapsis sobre las células granulares, las cuales envían sus fibras paralelas a la capa molecular para excitar a Purkinje.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-079 / G0271 del banco canónico | integración: Tema 1.5.1 + Tema 1.9.3 + Tema 1.11.2 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Archivo3_Parte1.pdf | referencias indicadas: TEMA 10 – CEREBELO Y COORDINACIÓN.pdf / NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #89)","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-147","number":"147","statement":"Debido a que el Núcleo Torácico de Clarke no se extiende por encima del segmento medular C8, la información propioceptiva inconsciente de los músculos y articulaciones del MIEMBRO SUPERIOR y cuello utiliza una vía homóloga diferenciada. ¿Dónde se localiza la neurona de segundo orden de esta vía?:","options":["En el Núcleo Cuneiforme Accesorio (o de Monakow) en el bulbo raquídeo, dando origen al tracto cuneocerebeloso.","En el núcleo gracilis del bulbo raquídeo.","En la lámina IX de la médula espinal sacra.","En el área tegmental ventral del mesencéfalo."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q7)] Hack de la Ausencia de Clarke en Brazos (Pregunta de Examen): Dado que el Núcleo de Clarke sólo existe de C8 a L3: Piernas (Propiocepción Inconsciente): Relevo en Núcleo de Clarke -> Tracto Espinocerebeloso Dorsal. Brazos (Propiocepción Inconsciente): Ascienden por el fascículo cuneiforme hasta el Núcleo Cuneiforme ACCESORIO del bulbo -> Tracto Cuneocerebeloso.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-080 / G0285 del banco canónico | integración: Tema 1.4 + Tema 1.5.1 + Tema 1.9.3 + Tema 1.10 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Archivo3_Parte2.pdf | referencias indicadas: 12-15 Clase magistral_ Sistema somatosensorial / 12-11 Lección_ Fisiología Sensorial / NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-148","number":"148","statement":"La vía del cordón posterior-lemnisco medial conduce la sensibilidad táctil epicrítica, propiocepción consciente y sensibilidad vibratoria (palestesia). Señale la ubicación exacta de la decusación de esta vía y el nombre que reciben sus fibras cruzadas:","options":["Decusan en el bulbo raquídeo caudal como fibras arqueadas (arcuatas) internas, formando inmediatamente el lemnisco medial que asciende hacia el tálamo VPL.","Decusan en la comisura blanca anterior de la médula espinal dos segmentos por encima del nivel de entrada.","Decusan en el mesencéfalo a nivel de los colículos superiores.","No decusan en ningún punto y ascienden ipsilateralmente hasta la corteza parietal."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q8)] Hack de la Decusación Lemniscal (Bulbo) vs. Espinotalámica (Médula): Vía Lemniscal (Tacto fino/Propiocepción): Sube IPSILATERAL por la médula (Grácil/Cuneiforme) -> Decusa en el BULBO (Fibras Arqueadas Internas) -> Lemnisco Medial. Vía Espinotalámica (Dolor/Temperatura): Decusa en la MÉDULA (Comisura blanca anterior) a nivel de entrada.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-081 / G0286 del banco canónico | integración: Tema 1.4 + Tema 1.5.1 + Tema 1.6 + Tema 1.10 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Archivo3_Parte2.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #17, #110) / 10-20 Clase magistral_ Sistema somatosensorial / ex. 2021 (respuestas).pdf (Pregunta #46)","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-149","number":"149","statement":"La analgesia endógena y la modulación descendente de la nocicepción se inician en la Sustancia Gris Periacueductal (PAG) del mesencéfalo. ¿A través de qué núcleo del tronco del encéfalo y mediante qué neurotransmisor proyecta la PAG para inhibir el dolor en el asta posterior medular?:","options":["Proyecta al Núcleo Magno del Rafe en el bulbo raquídeo, el cual envía fibras serotoninérgicas descendentes que activan interneuronas encefalinérgicas en la lámina II de Rexed.","Proyecta al núcleo rojo liberando GABA sobre el nervio óptico.","Proyecta directamente al núcleo dentado del cerebelo liberando acetilcolina.","Inerva la glándula pineal para liberar melatonina en las raíces dorsales."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de la Vía Descendente del Dolor: Sustancia Gris Periacueductal (PAG - Mesencéfalo) -> Núcleo Magno del Rafe (Bulbo - Serotonina) / Locus Coeruleus (Puente - Noradrenalina) -> Asta posterior de la médula (Lámina II) -> Liberación de Encefalinas / Opiáceos Endógenos.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-082 / G0287 del banco canónico | integración: Tema 1.4 + Tema 1.5.1 + Tema 1.10 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Archivo3_Parte2.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #111, #254) / 12-15 Lección_ Neurobiología del Dolor / TEMA 11 – SISTEMA SOMATOSENSORIAL .pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-150","number":"150","statement":"En la vía del cordón posterior-lemnisco medial, los axones de las neuronas de segundo orden (que nacen en los núcleos grácil y cuneiforme del bulbo) cruzan la línea media y forman el lemnisco medial. ¿En qué núcleo del tálamo hacen sinapsis con las neuronas de tercer orden?:","options":["Núcleo Ventral Posterolateral (VPL) del tálamo.","Núcleo Ventral Posteromedial (VPM) del tálamo.","Núcleo Anterior del tálamo.","Núcleo Geniculado Lateral del tálamo."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q14)] Hack VPL (Cuerpo) vs. VPM (Cara): VPL (Ventral Posterolateral): Recibe la sensibilidad táctil, térmica y nociceptiva del CUERPO (vía lemniscal y vía espinotalámica). VPM (Ventral Posteromedial): Recibe la sensibilidad táctil, térmica, nociceptiva y gustativa de la CARA Y CABEZA (vía trigeminal y tracto solitario).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-083 / G0292 del banco canónico | integración: Tema 1.4 + Tema 1.5.1 + Tema 1.6 + Tema 1.10 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Archivo3_Parte2.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #92, #148) / ex. 2021 (respuestas).pdf (Pregunta #53) / ex. 2022 (sin respuestas) 2.pdf (Pregunta #64)","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-151","number":"151","statement":"La información exteroceptiva nociceptiva y térmica procedente de la cara y región craneofacial es recogida por las tres ramas del nervio trigémino (V par). ¿En qué núcleo del tronco del encéfalo hacen sinapsis sus neuronas sensitivas de primer orden antes de decusar hacia el tálamo VPM?:","options":["En la porción espinal (núcleo trigeminal espinal), que se extiende desde la protuberancia caudal hasta los primeros segmentos medulares cervicales (C1-C2).","En el núcleo mesencefálico del trigémino.","En el núcleo motor del nervio facial.","En el núcleo gracilis del bulbo."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q17)] Hack de la Tripartición del Complejo Trigeminal: Núcleo Mesencefálico del V: Propiocepción de músculos masticatorios (¡Somas de 1ª orden dentro del SNC!). Núcleo Principal / Pontino del V: Tacto fino epicrítico de la cara. Núcleo Espinal del V: DOLOR Y TEMPERATURA DE LA CARA.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-084 / G0295 del banco canónico | integración: Tema 1.5.1 + Tema 1.5.2 + Tema 1.6 + Tema 1.10 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Archivo3_Parte2.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #185, #186) / 10-22C~1.MP3 / 10-20 Clase magistral_ Sistema somatosensorial","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-152","number":"152","statement":"Para la percepción y discriminación del tacto epicrítico y la presión fina de la CARA y región craneofacial, ¿qué núcleo del complejo trigeminal recibe las aferencias primarias y cuál es el nombre del tracto que asciende hacia el tálamo VPM?:","options":["Núcleo sensitivo principal (pontino) del trigémino, cuyos axones decusan y forman el lemnisco trigeminal (tracto trigeminotalámico).","Núcleo espinal del trigémino, enviando axones por el fascículo grácil.","Núcleo motor del abducens, proyectando al cerebelo.","Núcleo ambiguo del bulbo raquídeo de forma ipsilateral."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q22)] Hack del Núcleo Principal vs. Espinal del Trigémino: Núcleo Principal / Pontino: TACTO FINO EPICRÍTICO Y PRESIÓN craneofacial. Núcleo Espinal (Caudal): DOLOR Y TEMPERATURA craneofacial. La banca afirma que el núcleo espinal procesa el tacto fino o que el principal procesa el dolor. ¡FALSO!","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-085 / G0300 del banco canónico | integración: Tema 1.5.1 + Tema 1.5.2 + Tema 1.6 + Tema 1.10 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Archivo3_Parte2.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #186) / 10-21C~1.MP3 / TEMA 11 – SISTEMA SOMATOSENSORIAL .pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-153","number":"153","statement":"Respecto a las características neuroanatómicas de la vía de la propiocepción inconsciente del miembro superior (Tracto Cuneocerebeloso), señale la afirmación VERDADERA:","options":["Las neuronas de primer orden ascienden por el fascículo cuneiforme (cordón posterior) hasta el Núcleo Cuneiforme Accesorio del bulbo, desde donde las neuronas de segundo orden ingresan al cerebelo ipsilateralmente por el Pedúnculo Cerebeloso Inferior.","Decusa en la comisura blanca de la médula y termina en la corteza occipital.","Ingresa al cerebelo a través del nervio vago.","Sinapta en el núcleo supraóptico del hipotálamo."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack del Núcleo Cuneiforme Accesorio (Monakow): El Núcleo Cuneiforme Accesorio es el equivalente en el bulbo al Núcleo Torácico de Clarke de la médula. Recibe la propiocepción inconsciente de los brazos y la envía directamente al cerebelo por el cuerpo restiforme (PCI).","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-086 / G0306 del banco canónico | integración: Tema 1.4 + Tema 1.5.1 + Tema 1.9.3 + Tema 1.10 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Archivo3_Parte2.pdf | referencias indicadas: 12-15 Clase magistral_ Sistema somatosensorial / NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #95) / TEMA 11 – SISTEMA SOMATOSENSORIAL .pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-154","number":"154","statement":"En la vía lemniscal, la capacidad de diferenciar dos puntos táctiles muy cercanos sobre la piel depende del mecanismo de \"inhibición lateral\". ¿En qué estación sináptica se procesa de forma más prominente este filtrado para aumentar el contraste espacial?:","options":["En los núcleos de los cordones posteriores (Grácil y Cuneiforme) del bulbo raquídeo, mediante interneuronas GABAérgicas.","En la corteza auditiva primaria del lóbulo temporal.","En los corpúsculos de Pacini directamente.","En la cadena simpática paravertebral."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de la Inhibición Lateral (Aumento de Resolución Espacial): La inhibición lateral se inicia desde la primera sinapsis central en los núcleos Grácil y Cuneiforme del bulbo, donde interneuronas GABAérgicas suprimen las neuronas adyacentes para que el centro del estímulo llegue nítido a la corteza S1.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-087 / G0314 del banco canónico | integración: Tema 1.5.1 + Tema 1.10 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Archivo3_Parte2.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #116, #257) / 10-20 Clase magistral_ Sistema somatosensorial / TEMA 11 – SISTEMA SOMATOSENSORIAL .pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-155","number":"155","statement":"Las aferencias propioceptivas de los músculos masticatorios y de la articulación temporomandibular (ATM) presentan una peculiaridad neuroanatómica única en todo el sistema nervioso periférico. Indique cuál es:","options":["Sus somas neuronales de primer orden no están en un ganglio sensitivo periférico, sino dentro del propio SNC, formando el Núcleo Mesencefálico del Trigémino.","Carecen de receptores en los músculos masticatorios.","Viajan por el nervio vago directamente al corazón.","Tienen sus somas en la lámina X de la médula sacra."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de la Excepción del Núcleo Mesencefálico del V: Es la ÚNICA excepción de todo el organismo donde las neuronas sensitivas primarias (pseudounipolares) residen DENTRO del Sistema Nervioso Central (mesencéfalo), y no en un ganglio periférico fuera del tronco.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-088 / G0316 del banco canónico | integración: Tema 1.5.1 + Tema 1.5.2 + Tema 1.10 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Archivo3_Parte2.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #151) / 12-15 Clase magistral_ Sistema somatosensorial / wuolah-free-Examen-Neuro-recu-junio-2023.pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-156","number":"156","statement":"En su trayecto ascendente a través de los tres niveles del tronco del encéfalo (bulbo raquídeo, protuberancia y mesencéfalo), ¿en qué posición topográfica se sitúa el Lemnisco Espinal (Tracto Espinotalámico) en relación con el Lemnisco Medial?:","options":["Se ubica continuamente en una posición posterolateral (o ventrolateral externa) con respecto al lemnisco medial.","Ocupa el centro exacto de las pirámides bulbares.","Se sitúa medial al acueducto de Silvio dentro del núcleo rojo.","Desaparece en la protuberancia para reaparecer en la retina."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q46)] Hack de la Posición en el Tronco (Lemnisco Medial vs. Espinal): Lemnisco Medial (Tacto/Propiocepción): Ocupa una posición MEDIAL cerca de la línea media en el bulbo y protuberancia. Lemnisco Espinal / Espinotalámico (Dolor/Temperatura): Viaja siempre POSTEROLATERAL a lo largo de todo el tronco del encéfalo.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-089 / G0324 del banco canónico | integración: Tema 1.5.1 + Tema 1.6 + Tema 1.10 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Archivo3_Parte2.pdf | referencias indicadas: 09-25 Clase_ Neuroanatomía del Mesencéfalo / NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #21, #185) / TEMA 3 – TRONCO DEL ENCÉFALO.pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-157","number":"157","statement":"Un paciente presenta un infarto bulbar lateral (Síndrome de Wallenberg) por oclusión de la arteria PICA que destruye el Núcleo Espinal del Trigémino derecho. ¿Qué déficit sensitivo craneofacial específico manifestará en la cara?:","options":["Pérdida de la sensibilidad dolorosa y térmica en la mitad DERECHA (ipsilateral) de la cara, manteniendo intacta la discriminación táctil epicrítica y la presión (procesadas por el núcleo principal pontino).","Pérdida del tacto epicrítico con conservación del dolor.","Anestesia total bilateral de la lengua exclusivamente.","Parálisis de los músculos de la masticación."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q47)] Hack de la Disociación Sensitiva Trigeminal (Aitana): Núcleo Espinal del V (Bulbo caudal / Médula cervical C1-C2): Procesa ÚNICAMENTE DOLOR Y TEMPERATURA de la cara ipsilateral. Núcleo Principal / Pontino del V (Protuberancia): Procesa el TACTO EPICRÍTICO Y PRESIÓN.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-090 / G0325 del banco canónico | integración: Tema 1.3 + Tema 1.5.1 + Tema 1.5.2 + Tema 1.10 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Archivo3_Parte2.pdf | referencias indicadas: 10-22C~1.MP3 / 12-15 Clase magistral_ Sistema somatosensorial / NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #185)","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-158","number":"158","statement":"Analice las siguientes proposiciones sobre la neurobiología y vías del Sistema Somatosensorial tomadas de las opciones de examen oficial. Indique la ÚNICA combinación donde TODAS las proposiciones sean VERDADERAS: 1. El canal catiónico TRPV1 es activado por calor nocivo (>43 °C), protones (pH ácido) y capsaicina. 2. La vía del cordón posterior-lemnisco medial decusa en el bulbo raquídeo caudal como fibras arqueadas internas y hace su último relevo sensitivo en el núcleo VPL del tálamo. 3. El dolor rápido se transmite por fibras mielínicas pequeñas A-delta y el dolor lento por fibras amielínicas C.","options":["1, 2 y 3 son VERDADERAS.","Solo 1 y 2 son verdaderas.","Solo 2 y 3 son verdaderas.","1, 2 y 3 son falsas."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q48)] Hack del Gran Resumen del || [Explicación 2 (Neuro_Archivo3_Parte2.pdf Q48)] Hack del Gran Resumen del Tema 1.10:Proposición 1 (VERDADERA): TRPV1 = Calor >43 °C + Capsaicina + Protones (H⁺). Proposición 2 (VERDADERA): Lemnisco Medial = Decusación en Bulbo (Fibras Arqueadas) -> Tálamo VPL.Proposición 3 (VERDADERA): Dolor Agudo (Aδ) vs. Dolor Lento (C).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-091 / G0326 del banco canónico | integración: Tema 1.4 + Tema 1.5.1 + Tema 1.6 + Tema 1.10 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Archivo3_Parte2.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Preguntas #16, #49, #92, #94, #95, #106-#118, #148-#151, #185-#188, #250-#259) / Tema 1.10 - Sistema somatosensorial 25- 26.pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-159","number":"159","statement":"Al incidir un haz de luz brillante sobre la pupila ocular se desencadena el reflejo fotomotor de miosis (contracción pupilar consensual). Señale la secuencia neuroanatómica del circuito parasimpático responsable de esta respuesta:","options":["Axones ganglionares extrageniculadas → Área Pretectal (mesencéfalo) → Núcleo de Edinger- Westphal (III par) → Ganglio Ciliar → Músculo esfínter del iris.","Retina → Colículo inferior → Cadena simpática cervical → Músculo dilatador de la pupila.","Quiasma óptico → Corteza motora M1 → Nervio facial VII → Córnea.","Vía espinotalámica → Núcleo VPL → Glándula lagrimal."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q7)] Hack del Reflejo Fotomotor / Miosis: 1. Aferencia: Retina -> N. Óptico -> Área Pretectal (Mesencéfalo rostral). 2. Interconexión: Pretectum proyecta bilateralmente a los Núcleos de Edinger-Westphal (causa del reflejo consensual). 3. Eferencia Parasimpática: N. Oculomotor (III) -> Ganglio Ciliar -> N. ciliares cortos -> Músculo esfínter de la pupila. || [Explicación 2 (Neuro_Archivo3_Parte2.pdf Q7)] Hack del Reflejo Fotomotor / Miosis: Aferencia: Retina -> N. Óptico -> Área Pretectal (Mesencéfalo rostral). Interconexión: Pretectum proyecta bilateralmente a los Núcleos de Edinger- Westphal (causa del reflejo consensual). Eferencia Parasimpática: N. Oculomotor (III) -> Ganglio Ciliar -> N. ciliares cortos -> Músculo esfínter de la pupila.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-092 / G0333 del banco canónico | integración: Tema 1.5.1 + Tema 1.5.2 + Tema 1.11.1 + Tema 1.12 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Archivo3_Parte2.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #120, #122, #251) / 10-27 Clase_ Vía Visual y Reflejos Oculares / TEMA 12 – VISIÓN.pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-160","number":"160","statement":"Cuando se sigue con la mirada un tren en movimiento o un tambor estriado giratorio (tambor optocinético), los ojos presentan un movimiento involuntario rítmico denominado Nistagmo Optocinético (fase lenta de seguimiento suave y fase rápida de sacada de retorno). ¿Qué estructuras subcorticales y corticales participan en la fase de seguimiento y en la fase rápida sacádica respectivamente?:","options":["La fase lenta de seguimiento suave depende de la corteza visual asociativa V5/MT y del puente, mientras que la fase rápida sacádica de retorno es generada por el Colículo Superior y los Campos Oculares Frontales (Área 8 de Brodmann).","Ambas fases son generadas únicamente por la retina periférica sin intervención del tronco encefálico.","La fase lenta depende del cerebelo flóculo-nodular exclusivamente.","La fase rápida es inervada por el nervio vago (X)."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q31)] Hack de las Dos Fases del Nistagmo Optocinético: Fase Lenta (Seguimiento Suave): Vía occipito-ponto-cerebelosa y Área V5/MT (sigue el objeto en movimiento). Fase Rápida (Sacada de Retorno): Campos Oculares Frontales (Área 8) y Colículo Superior (devuelve el ojo al centro).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-093 / G0357 del banco canónico | integración: Tema 1.5.1 + Tema 1.7 + Tema 1.9.2 + Tema 1.11.1 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Archivo3_Parte3.pdf | referencias indicadas: 10-27 Clase_ Vía Visual y Reflejos Oculares / NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #120) / Tema 1.11.1 - Sistema visual 25-26.pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-161","number":"161","statement":"Un paciente con destrucción total de la Corteza Visual Primaria V1 (Área 17) bilateral manifiesta ceguera cortical completa. Sin embargo, ante objetos que se mueven rápidamente hacia su rostro, el paciente es capaz de esquivarlos involuntariamente sin \"verlos\" conscientemente (fenómeno de Visión Ciega o Blindsight). ¿Qué vía visual subcortical retinofugal alternativa conserva esta respuesta refleja?:","options":["La vía retinocolicular (proyección desde las células ganglionares M de la retina hacia el Colículo Superior del mesencéfalo y el Núcleo Pulvinar del tálamo).","La vía lemniscal que sube por los cordones posteriores.","La vía retinohipotalámica hacia el núcleo supraquiasmático.","El tracto corticoespinal lateral."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack del Blindsight / Vía Retinocolicular: Un 10% de las fibras del nervio óptico no van al NGL, sino al Colículo Superior (Mesencéfalo). Esta vía subcortical arcaica permite localizar espacialmente y reaccionar ante estímulos en movimiento sin percepción consciente de la visión (independiente de V1).","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-094 / G0359 del banco canónico | integración: Tema 1.5.1 + Tema 1.6 + Tema 1.7 + Tema 1.8 + Tema 1.11.1 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Archivo3_Parte3.pdf | referencias indicadas: 10-27 Clase_ Vía Visual / 11-06 Tutoría_ Neurofisiología / TEMA 12 – VISIÓN.pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-162","number":"162","statement":"En la neurosífilis (tabes dorsal) es característico el hallazgo de la Pupila de Argyll Robertson. ¿Qué disociación refleja pupilar presenta el paciente debido a la lesión de la región pretectal mesencefálica?:","options":["Abolición del reflejo fotomotor (las pupilas no se contraen ante la luz intensa) con conservación intacta del reflejo de acomodación y convergencia de cerca.","Miosis bilateral que no responde a la acomodación pero sí a la luz intensa.","Midriasis unilateral fija con pérdida del reflejo corneal.","Pérdida total de la movilidad ocular por destrucción del cerebelo."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de Argyll Robertson (Luz No / Acomodación Sí): La lesión en el Área Pretectal del mesencéfalo interrumpe las aferencias del reflejo fotomotor a la luz. Sin embargo, la vía de la acomodación de cerca (que desciende desde la corteza motora al núcleo de Edinger-Westphal) no pasa por el tectum y por tanto permanece intacta.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-095 / G0362 del banco canónico | integración: Tema 1.5.1 + Tema 1.5.2 + Tema 1.11.1 + Tema 1.12 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Archivo3_Parte3.pdf | referencias indicadas: 10-27 Clase_ Vía Visual y Reflejos Oculares / 12-15 Clase_ Patologías / ex. 2 (respuestas).pdf (Pregunta #58)","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-163","number":"163","statement":"La vía auditiva central es una vía ascendente multisináptica con decusaciones parciales a lo largo del tronco del encéfalo. Ordene cronológicamente las estaciones de relevo de esta vía desde la periferia hasta la corteza cerebral:","options":["Ganglio Espiral de Corti → Núcleos Cocleares (Ventral/Dorsal) → Complejo Olivar Superior → Lemnisco Lateral → Colículo Inferior → Núcleo Geniculado Medial del tálamo → Corteza Auditiva Primaria (A1 / Heschl).","Ganglio vestibular → Colículo superior → Núcleo geniculado lateral → Área 17.","Núcleo gracilis → Lemnisco medial → Núcleo VPL → Giro postcentral.","Órgano de Corti → Núcleo rojo → Oliva inferior → Cerebelo."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q4)] Hack Mnemónico Vía Auditiva \"E-CO-LI-MA\": E: Ganglio Espiral (1ª neurona). CO: Núcleos COcleares (2ª neurona). L: Lemnisco lateral / Complejo Olivar Superior (procesamiento binaural). I: Colículo Inferior del mesencéfalo. M: Núcleo Geniculado MEDIAL del Tálamo (Medial = Música / Medial = Audición; no confundir con Geniculado Lateral = Luz/Visión). A: Corteza Auditiva (Giros transversos de Heschl / Áreas 41 y 42).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-096 / G0372 del banco canónico | integración: Tema 1.5.1 + Tema 1.5.2 + Tema 1.6 + Tema 1.7 + Tema 1.11.2 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Archivo3_Parte3.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #123, #189, #229) / 09-24 Clase_ Neuroanatomía - Vías Sensitivas y Auditivas del Tronco Encefálico / TEMA 13 – SENTIDO DE LA AUDICIÓN Y EQUILIBRIO .pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-164","number":"164","statement":"La localización del origen espacial del sonido en el plano horizontal (sordera direccional) se realiza mediante el procesamiento binaural de pistas interaurales. ¿En qué estructura del tronco del encéfalo y en qué subnúcleos se analizan estas diferencias?:","options":["En el Complejo Olivar Superior de la protuberancia caudal; el Núcleo Olivar Superior Medial (OSM) analiza las diferencias interaurales de tiempo (ITD) y el Núcleo Olivar Superior Lateral (OSL) las diferencias de intensidad (IID).","En el colículo superior del mesencéfalo mediante fotopsinas.","En la corteza parietal posterior únicamente.","En el ganglio geniculado del nervio facial."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q5)] Hack de la Localización Sonora (Complejo Olivar Superior): Oliva Superior Medial (OSM): Diferencia de TIEMPO interaural (ITD) -> Frecuencias Bajas / Graves (<1500 Hz). Oliva Superior Lateral (OSL): Diferencia de INTENSIDAD interaural (IID) -> Frecuencias Altas / Agudas (>1500 Hz, por sombra de la cabeza).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-097 / G0373 del banco canónico | integración: Tema 1.5.1 + Tema 1.11.2 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Archivo3_Parte3.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #124, #229) / 10-28 Clase magistral_ Anatomía y fisiología del sistema auditivo / Tema 1.11.2 - Sentido de la audición","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-165","number":"165","statement":"El Reflejo Vestíbulo-Ocular (RVO) es un arco reflejo fundamental para mantener la fijación foveal de la mirada sobre un objetivo inmóvil durante los movimientos de la cabeza. ¿A través de qué fascículo del tronco del encéfalo conectan los núcleos vestibulares con los núcleos oculomotores (III, IV y VI pares)?:","options":["Fascículo Longitudinal Medial (FLM).","Fascículo Cuneiforme de Burdach.","Lemnisco Medial.","Tracto Corticospinal Lateral."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q10)] Hack del RVO y el FLM (Conexión Oculovestibular): 1. Girar la cabeza a la derecha -> Estimula conducto semicircular horizontal derecho. 2. Núcleo vestibular derecho proyecta por el Fascículo Longitudinal Medial (FLM) cruzado hacia el núcleo del VI par contralateral (izquierdo) y de ahí al III par ipsilateral. 3. Los ojos se mueven hacia la IZQUIERDA a la misma velocidad que gira la cabeza (mantiene la imagen estable en la fóvea). || [Explicación 2 (Neuro_Archivo3_Parte3.pdf Q10)] Hack del RVO y el FLM (Conexión Oculovestibular): Girar la cabeza a la derecha -> Estimula conducto semicircular horizontal derecho. Núcleo vestibular derecho proyecta por el Fascículo Longitudinal Medial (FLM) cruzado hacia el núcleo del VI par contralateral (izquierdo) y de ahí al III par ipsilateral. Los ojos se mueven hacia la IZQUIERDA a la misma velocidad que gira la cabeza (mantiene la imagen estable en la fóvea).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-098 / G0378 del banco canónico | integración: Tema 1.5.1 + Tema 1.5.2 + Tema 1.7 + Tema 1.11.1 + Tema 1.11.2 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Archivo3_Parte3.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #124, #189) / 10-27 Aula_ Fisiología de la Audición y el Equilibrio / TEMA 13 – SENTIDO DE LA AUDICIÓN Y EQUILIBRIO .pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-166","number":"166","statement":"La vía eferente olivococlear (Haz de Rasmussen) parte del Complejo Olivar Superior y proyecta hacia el Órgano de Corti. ¿Qué efecto neuroquímico y funcional ejerce esta vía eferente sobre las Células Ciliadas Externas (CCE)?:","options":["Libera Acetilcolina (ACh) sobre receptores nicotínicos/muscarínicos de las CCE, provocando su hiperpolarización para reducir la ganancia coclear y proteger la audición frente al ruido enmascarador o trauma acústico.","Libera Glutamato para destruir los estereocilios de las células internas.","Activa la producción de otolitos en la rampa timpánica.","Estimula la apertura de la ventana redonda hacia el conducto auditivo."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de la Modulación Eferente (Haz Olivococlear): El cerebro no solo escucha; también \"frena\" al oído. El Haz Olivococlear de Rasmussen envía fibras eferentes colinérgicas (ACh) que hiperpolarizan las CCE, atenuando la amplificación mecánica cuando hay ruido excesivo o para enfocar la atención en una conversación específica.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-099 / G0381 del banco canónico | integración: Tema 1.5.1 + Tema 1.11.2 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Archivo3_Parte3.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #123) / 10-28 Clase magistral_ Anatomía y fisiología del sistema auditivo / TEMA 13 – SENTIDO DE LA AUDICIÓN Y EQUILIBRIO .pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-167","number":"167","statement":"El Reflejo Estapedial (acústico) se desencadena ante sonidos de alta intensidad (>80 dB) para proteger el laberinto posterior. Señale la secuencia del arco reflejo sensitivo-motor bilateral responsable de la contracción del músculo del estribo:","options":["Aferencia por el Nervio Coclear (VIII) → Núcleos Cocleares → Complejo Olivar Superior (bilateral) → Eferencia por el Núcleo Motor del Nervio Facial (VII par) hacia el Músculo del Estribo.","Aferencia por el nervio óptico (II) → Eferencia por el nervio vago (X) sobre el tímpano.","Aferencia por el trigémino V1 → Eferencia por el hipogloso XII.","Circuito monosináptico directo dentro de la rampa timpánica."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de la Bilateralidad del Reflejo Estapedial: La interconexión a nivel del Complejo Olivar Superior proyecta a los núcleos del VII Par de AMBOS LADOS. Por ello, un estímulo sonoro intenso en el oído derecho produce la contracción reflexiva del músculo del estribo en AMBOS OÍDOS simultáneamente.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-100 / G0391 del banco canónico | integración: Tema 1.5.1 + Tema 1.5.2 + Tema 1.11.2 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Archivo3_Parte3.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #123, #153) / 10-28 Clase magistral_ Anatomía y fisiología del sistema auditivo / TEMA 13 – SENTIDO DE LA AUDICIÓN Y EQUILIBRIO .pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-168","number":"168","statement":"El nistagmo vestibular espontáneo se compone de dos fases de movimiento ocular de velocidad diferente. Señale qué estructura genera la fase lenta y cuál genera la fase rápida de corrección sacádica:","options":["La fase lenta de desviación tónica es producida por la asimetría de tono de los núcleos vestibulares del laberinto; mientras que la fase rápida de retorno es generada por el centro sacádico cerebral y la Formación Reticular Pontina Paramedia (FRPP).","Ambas fases son generadas exclusivamente por la córnea.","La fase rápida es generada por el nervio olfatorio y la lenta por la retina.","La fase lenta depende del lóbulo occipital y la rápida del nervio vago."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q24)] Hack de la Nomenclatura del Nistagmo: Origen de la lesión patológica: FASE LENTA (el oído dañado \"empuja\" menos y los ojos se desvían lentamente hacia el lado afecto). Dirección del Nistagmo (Nomenclatura clínica): Se nombra SIEMPRE según la FASE RÁPIDA (el centro pontino FRPP \"patea\" rápidamente los ojos hacia el lado sano).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-101 / G0392 del banco canónico | integración: Tema 1.5.1 + Tema 1.11.2 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Archivo3_Parte3.pdf | referencias indicadas: 10-27 Aula_ Fisiología de la Audición y el Equilibrio / NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #124) / TEMA 13 – SENTIDO DE LA AUDICIÓN Y EQUILIBRIO .pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-169","number":"169","statement":"El mareo por movimiento (Cinetosis) al viajar en barco, coche o avión desencadena náuseas, sudoración fría y vómitos. ¿Cuál es el desencadenante neurofisiológico subyacente y qué estructura bulbopontina integra la respuesta emética?:","options":["Ocurre por un conflicto sensorial (descordonamiento) entre las señales vestibulares, visuales y propioceptivas; la respuesta vegetativa se integra en el vestibulocerebelo (nódulo y flóculo) y el centro del vómito en el Área Postrema del bulbo raquídeo.","Ocurre por destrucción irreversible del caracol óseo.","Es provocado por un exceso de glucosa en el conducto auditivo externo.","Se origina por parálisis del III par craneal."],"answer":0,"explanation":"No incluida en el material.","hack":"Hack de la Cinetosis (Conflicto Sensorial + Área Postrema): Si estás leyendo un libro dentro de un coche en movimiento: tus ojos dicen \"estoy quieto\" (miran el libro), pero tu aparato vestibular dice \"me muevo\" (siente las curvas). Este conflicto sensorial llega al Área Postrema (bulbo caudal) desencadenando la respuesta emética defensiva.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-102 / G0393 del banco canónico | integración: Tema 1.5.1 + Tema 1.9.3 + Tema 1.10 + Tema 1.11.1 + Tema 1.11.2 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Archivo3_Parte3.pdf | referencias indicadas: 10-27 Aula_ Fisiología de la Audición y el Equilibrio / 10-13 Clase_ Funciones Cerebrales, Ritmos Circadianos / TEMA 13 – SENTIDO DE LA AUDICIÓN Y EQUILIBRIO .pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-170","number":"170","statement":"En la prueba de Potenciales Evocados Auditivos del Tronco Encefálico (PEATE / BERA), se registran cinco ondas eléctricas principales (I a V) durante los primeros 10 milisegundos tras un estímulo sonoro. Señale la correspondencia neuroanatómica de la ONDA I y de la ONDA V:","options":["La Onda I representa la despolarización del Nervio Coclear (VIII par); y la Onda V representa la actividad del Colículo Inferior del mesencéfalo.","La Onda I representa la corteza auditiva A1 y la Onda V el tímpano.","La Onda I se origina en el quiasma óptico y la Onda V en el cerebelo.","Todas las ondas se generan exclusivamente en el pabellón auricular."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q27)] Hack de las Ondas del PEATE (BERA): Onda I: Nervio Coclear (VIII) (Periférica) Onda II: Núcleos Cocleares (Bulbo) Onda III: Complejo Olivar Superior (Protuberancia) Onda IV: Lemnisco Lateral (Protuberancia alta) Onda V: Colículo Inferior (Mesencéfalo) -> La onda clínica más estable y relevante.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-103 / G0395 del banco canónico | integración: Tema 1.5.1 + Tema 1.5.2 + Tema 1.11.2 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Archivo3_Parte3.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #123, #229) / 10-28 Clase magistral_ Anatomía y fisiología del sistema auditivo / Tema 1.11.2 - Sentido de la audición","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-171","number":"171","statement":"En la tectum mesencefálica, el Colículo Inferior constituye una estación central obligada de la vía auditiva ascendente. ¿Qué integración realiza y hacia dónde envía sus axones de proyección?:","options":["Integra todas las aferencias auditivas tonotópicas y binaurales ascendentes procedentes del lemnisco lateral, proyectando a través del brazo del colículo inferior hacia el Núcleo Geniculado Medial del tálamo.","Integra la información visual de la retina y proyecta al nervio óptico.","Recibe impulsos gustativos y los envía al bulbo olfatorio.","Inhibe la producción de saliva en la glándula parótida."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q32)] Hack Tectum Mesencefálico (Superior vs. Inferior): Colículo SUPERIOR: Vía VISUAL subcortical / Reflejos oculomotores. Colículo INFERIOR: Vía AUDITIVA central / Integración tonotópica -> Envía fibras al Núcleo Geniculado Medial del Tálamo.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-104 / G0400 del banco canónico | integración: Tema 1.5.1 + Tema 1.6 + Tema 1.11.2 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Archivo3_Parte3.pdf | referencias indicadas: NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #123, #229) / 09-24 Clase_ Neuroanatomía - Vías Sensitivas y Auditivas / TEMA 13 – SENTIDO DE LA AUDICIÓN Y EQUILIBRIO .pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-172","number":"172","statement":"Para orientar la conducta médica es imprescindible diferenciar entre un Síndrome Vestibular Periférico (laberinto o VIII par) y un Síndrome Vestibular Central (tronco del encéfalo o cerebelo). Señale los hallazgos típicos de un Síndrome Vestibular Periférico:","options":["Vértigo armónico, rotatorio, de inicio brusco e intenso, con nistagmo unidireccional que SE INHIBE con la fijación de la mirada, y presencia frecuente de síntomas auditivos (hipoacusia/acúfeno) y vegetativos.","Nistagmo vertical puro no armónico que no se inhibe con la vista y disociación motora.","Parálisis total de las cuatro extremidades sin mareo.","Ausencia de nistagmo con pérdida de la visión de colores."],"answer":0,"explanation":"[Explicación 1 (Todas as questoes ate tema 1.10.1.pdf Q35)] Hack Vértigo Periférico vs. Central (Inhibición Ocular): Vértigo PERIFÉRICO: SE INHIBE al fijar la vista (el nistagmo disminuye o desaparece al mirar un punto fijo); nistagmo unidireccional/armónico. Vértigo CENTRAL: NO SE INHIBE al fijar la vista (o empeora); nistagmo multidireccional o vertical puro.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-105 / G0403 del banco canónico | integración: Tema 1.5.1 + Tema 1.5.2 + Tema 1.9.3 + Tema 1.11.2 | archivos: Todas as questoes ate tema 1.10.1.pdf; Neuro_Archivo3_Parte3.pdf | referencias indicadas: 10-27 Aula_ Fisiología de la Audición y el Equilibrio / NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf (Pregunta #124) / TEMA 13 – SENTIDO DE LA AUDICIÓN Y EQUILIBRIO .pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-173","number":"173","statement":"En relación al circuito de recompensa, el principal neurotransmisor liberado desde el mesencéfalo es:","options":["Dopamina.","Glutamato.","Noradrenalina.","Serotonina."],"answer":0,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-106 / G0417 del banco canónico | integración: Tema 1.5.1 + Tema 1.7 | número original en el examen: 53 | archivos: Neuro_Parte2.pdf | referencias indicadas: Design sem nome (3).pdf / Exame Neuro 2022.pdf (Prueba Objetiva, 22 de noviembre de 2022)","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-174","number":"174","statement":"La decusación de las pirámides se produce en:","options":["el cerebro.","el diencéfalo.","el mesencéfalo.","la protuberancia.","el bulbo raquídeo."],"answer":4,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-107 / G0419 del banco canónico | integración: Tema 1.5.1 + Tema 1.7 + Tema 1.9.1 | número original en el examen: 1 | archivos: Neuro_Parte2.pdf | referencias indicadas: wuolah-free-Examen-Neuro-1 (1).pdf / wuolah-free-examenes-2011.pdf (Prueba Objetiva)","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-175","number":"175","statement":"En los ganglios basales, las neuronas que contienen neuromelanina se encuentran en:","options":["La sustancia negra, parte compacta","La sustancia negra, parte reticular","El estriado, compartimento de los estriosomas","A, b y c son correctas","A y c son correctas"],"answer":0,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-108 / G0458 del banco canónico | integración: Tema 1.5.1 + Tema 1.7 + Tema 1.9.2 | número original en el examen: 4 | archivos: Neuro_Parte2.pdf | referencias indicadas: wuolah-free-tema-6-preguntas.pdf (Pergunta 4) / wuolah-free- examenes-2011.pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-176","number":"176","statement":"Indica la afirmación FALSA sobre la anatomía e histología de los ganglios basales:","options":["La amígdala cerebral es anterior (rostral) a la cola del núcleo caudado.","El núcleo lenticular está constituido por la suma del globo pálido y el putamen.","La sustancia negra se encuentra lateral al putamen.","El segmento interno del globo pálido inhibe tónicamente a los núcleos talámicos."],"answer":2,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-109 / G0471 del banco canónico | integración: Tema 1.5.1 + Tema 1.7 + Tema 1.9.2 | archivos: Neuro_Parte2.pdf | referencias indicadas: ex. 2 (respuestas).pdf (Pergunta 41) / ex. 2 (sin respuestas) (1, 2, 3 y 16).pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-177","number":"177","statement":"Ordena la secuencia de acontecimientos que tiene lugar en la activación de la vía directa de los ganglios basales: 1 - Desinhibición de las proyecciones tálamo-corticales 2 - Activación del cuerpo estriado por la corteza 3 - Inhibición del globo pálido interno / sustancia negra reticulada 4 - Activación de la corteza motora","options":["2 → 3 → 1 → 4","3 → 2 → 4 → 1","1 → 2 → 3 → 4","2 → 1 → 3 → 4"],"answer":0,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-110 / G0472 del banco canónico | integración: Tema 1.5.1 + Tema 1.6 + Tema 1.7 + Tema 1.9.1 + Tema 1.9.2 | archivos: Neuro_Parte2.pdf | referencias indicadas: perguntas neuro julio exame.docx / Examem 2025 outro modelo juneka.pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-178","number":"178","statement":"Sobre el tálamo, indica la respuesta INCORRECTA:","options":["Lámina medular interna — contiene el núcleo centromediano.","Pulvinar — localizado en la parte posterior del tálamo.","Núcleo ventral anterior (VA, porción lateral) — núcleo motor, recibe aferencia del globo pálido y sustancia negra y proyecta a corteza motora primaria.","Núcleo geniculado lateral — recibe información auditiva del colículo inferior mesencefálico y proyecta a la corteza auditiva primaria."],"answer":3,"explanation":"[Nota de la clave] Incorreta pois quem recebe a informação auditiva é o Núcleo Geniculado Medial; o lateral transmite a visão).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-111 / G0505 del banco canónico | integración: Tema 1.5.1 + Tema 1.6 + Tema 1.11.2 | archivos: Neuro_Parte2.pdf | referencias indicadas: ex. 2 (respuestas).pdf (Pregunta #21) / ex. 2 (sin respuestas) (1, 2, 3 y 16).pdf (Pregunta #21)","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-179","number":"179","statement":"¿Qué relación anatómica presenta la glándula pineal (epífisis) con respecto al III ventrículo y al diencéfalo?:","options":["Se ubica en la pared anterior del III ventrículo, sobre el quiasma óptico.","Se localiza en la región posterior del epitálamo, sobre los colículos superiores del mesencéfalo.","Se sitúa en la fosa interpeduncular.","Forma la pared lateral del IV ventrículo."],"answer":1,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-112 / G0549 del banco canónico | integración: Tema 1.5.1 + Tema 1.6 | archivos: Neuro_Parte2.pdf | referencias indicadas: 10-06 Clase_ Neuroanatomía del Hipotálamo / wuolah-free- PREGUNTAS-TEST-NEURO-DIENCEFALO-.pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-180","number":"180","statement":"¿Cuál de los siguientes tractos hipotalámicos conecta los núcleos mamilares con la formación reticular y sustancia gris periacueductal del tronco del encéfalo?:","options":["Tracto mamilotalámico.","Fórnix (trígono).","Fascículo mamilotegmental.","Estría medular del tálamo."],"answer":2,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-113 / G0560 del banco canónico | integración: Tema 1.5.1 + Tema 1.6 | archivos: Neuro_Parte2.pdf | referencias indicadas: wuolah-free-EXAMEN-2017-2018-1 (1).pdf / wuolah-free-tema-5- preguntas.pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-181","number":"181","statement":"Respecto a la anatomía funcional del tálamo, el Núcleo Geniculado Medial (NGM):","options":["Recibe aferencias visuales y proyecta al área 17 de Brodmann.","Recibe aferencias del colículo inferior mesencefálico y proyecta a la corteza auditiva primaria (áreas 41 y 42).","Recibe aferencias del cerebelo y proyecta a la corteza motora.","Inhibe GABAérgicamente a los demás núcleos talámicos."],"answer":1,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-114 / G0563 del banco canónico | integración: Tema 1.5.1 + Tema 1.6 + Tema 1.11.2 | archivos: Neuro_Parte2.pdf | referencias indicadas: wuolah-free-tema-5-preguntas.pdf / TEMA 5 – DIENCÉFALO .pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-182","number":"182","statement":"En relación a los pares craneales relacionados con el tronco del encéfalo, todos salen por la parte anterior del mismo, a excepción de uno que lo hace por la parte posterior (dorsal) del tronco del encéfalo. Este par craneal es:","options":["Par craneal III (nervio oculomotor)","Par craneal IV (nervio troclear)","Par craneal V (nervio trigémino)","Par craneal VI (nervio abducens)","Par craneal VII (nervio facial)"],"answer":1,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-115 / G0568 del banco canónico | integración: Tema 1.5.1 + Tema 1.5.2 | archivos: Neuro_Parte3.pdf | referencias indicadas: wuolah-free-tema-4-preguntas.pdf / wuolah-free-UNIRESUMEN- DOCUMENTO-GRATIS-PARES-CRANEALES.pdf / examenes neuro compl (1).pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-183","number":"183","statement":"¿Cuáles son los pares craneales que surgen del tronco del encéfalo por el surco preolivar del bulbo raquídeo?:","options":["Vago (X)","Abducens (VI)","Hipogloso (XII)","Glosofaríngeo (IX)","Accesorio (XI)"],"answer":2,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-116 / G0569 del banco canónico | integración: Tema 1.5.1 + Tema 1.5.2 | archivos: Neuro_Parte3.pdf | referencias indicadas: wuolah-free-tema-4-preguntas.pdf / TEMA 4 – PARES CRANEALES .pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-184","number":"184","statement":"Respecto a las emergencias de los pares craneales en la superficie del tronco del encéfalo, señale la opción CORRECTA:","options":["El nervio hipogloso (XII) emerge por el surco preolivar del bulbo raquídeo.","El nervio trigémino (V) emerge por la superficie posterior del mesencéfalo.","El nervio troclear (IV) emerge por el surco retroolivar junto al vago.","El nervio oculomotor (III) emerge de la cara dorsal de la protuberancia."],"answer":0,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-117 / G0590 del banco canónico | integración: Tema 1.5.1 + Tema 1.5.2 | archivos: Neuro_Parte3.pdf | referencias indicadas: wuolah-free-tema-4-preguntas.pdf (Preguntas #11 y #18) / wuolah- free-PREGUNTAS-EXAMEN-DE-NEURO.pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-185","number":"185","statement":"Las fibras de la sensibilidad gustativa de la parte anterior de la lengua (2/3 anteriores) tienen sus somas en el ganglio geniculado. ¿En qué núcleo del tronco del encéfalo realizan su primera sinapsis central?:","options":["Núcleo del trato solitario (porción gustativa / rostral)","Núcleo espinal del trigémino","Núcleo ambiguo","Núcleo dorsal del vago"],"answer":0,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-118 / G0599 del banco canónico | integración: Tema 1.5.1 + Tema 1.5.2 + Tema 1.11.3 | archivos: Neuro_Parte3.pdf | referencias indicadas: wuolah-free-tema-4-preguntas.pdf / ex. 2 (respuestas).pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-186","number":"186","statement":"¿Cuál de los siguientes pares craneales tiene su origen aparente en la cara lateral del puente (protuberancia), en el límite con los pedúnculos cerebelosos medios?:","options":["Nervio oculomotor (III)","Nervio trigémino (V)","Nervio facial (VII)","Nervio abducens (VI)"],"answer":1,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-119 / G0600 del banco canónico | integración: Tema 1.5.1 + Tema 1.5.2 + Tema 1.9.3 | archivos: Neuro_Parte3.pdf | referencias indicadas: wuolah-free-tema-4-preguntas.pdf (Pregunta #16) / wuolah-free- UNIRESUMEN-DOCUMENTO-GRATIS-PARES-CRANEALES.pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-187","number":"187","statement":"Respecto a la inervación motora del músculo oblicuo superior del ojo, la afirmación CORRECTA es:","options":["Es inervado por el nervio oculomotor (III) contralateral.","Es inervado por el nervio troclear (IV), cuyos axones decusan antes de emerger por la cara posterior del mesencéfalo.","Es inervado por el nervio abducens (VI).","Es inervado por la rama oftálmica del nervio trigémino (V1)."],"answer":1,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-120 / G0604 del banco canónico | integración: Tema 1.5.1 + Tema 1.5.2 | archivos: Neuro_Parte3.pdf | referencias indicadas: wuolah-free-tema-4-preguntas.pdf (Pregunta #24) / Recopilación preguntas neuro (1).pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-188","number":"188","statement":"¿Cuál de los siguientes núcleos del tronco del encéfalo recibe las aferencias viscerales generales e intermedias de los barorreceptores del seno carotídeo (vía IX) y del arco aórtico (vía X)?:","options":["Porción caudal e intermedia del núcleo del tracto solitario.","Núcleo ambiguo.","Núcleo espinal del trigémino.","Núcleo coclear ventral."],"answer":0,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-121 / G0605 del banco canónico | integración: Tema 1.5.1 + Tema 1.5.2 + Tema 1.12 | archivos: Neuro_Parte3.pdf | referencias indicadas: ex. 2 (respuestas).pdf / wuolah-free-tema-4-preguntas.pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-189","number":"189","statement":"Los somas de las neuronas de primer orden responsables de la audición se localizan en el ganglio espiral (de Corti). ¿Dónde realizan su primera sinapsis en el tronco del encéfalo?:","options":["Núcleos cocleares anterior (ventral) y posterior (dorsal) en el ángulo pontobulbar.","Núcleo vestibular superior de Bechterew.","Núcleo ambiguo.","Núcleo del tracto solitario."],"answer":0,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-122 / G0609 del banco canónico | integración: Tema 1.5.1 + Tema 1.5.2 + Tema 1.11.2 | archivos: Neuro_Parte3.pdf | referencias indicadas: ex. 2021 (respuestas).pdf / examenes neuro compl (1).pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-190","number":"190","statement":"¿Cuáles de los siguientes pares craneales tienen su origen aparente alineado en el surco retroolivar (postolivar) del bulbo raquídeo, ordenados de cefálico a caudal?:","options":["VI, VII y VIII","IX (glosofaríngeo), X (vago) y XI (accesorio)","III, IV y V","XII (hipogloso) y XI (accesorio)"],"answer":1,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-123 / G0612 del banco canónico | integración: Tema 1.5.1 + Tema 1.5.2 | archivos: Neuro_Parte3.pdf | referencias indicadas: wuolah-free-EXAMEN-2017-2018-1 (1).pdf / examenes neuro compl (1).pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-191","number":"191","statement":"El núcleo ambiguo (ubicado en el bulbo raquídeo) aloja las motoneuronas branquiales que dan origen a las eferencias motoras de los siguientes pares craneales:","options":["V, VI y VII","IX (glosofaríngeo), X (vago) y la porción craneal del XI (accesorio)","III, IV y VI","Únicamente el nervio troclear (IV)"],"answer":1,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-124 / G0626 del banco canónico | integración: Tema 1.5.1 + Tema 1.5.2 | archivos: Neuro_Parte3.pdf | referencias indicadas: wuolah-free-UNIRESUMEN-DOCUMENTO-GRATIS-PARES- CRANEALES.pdf (Pregunta #29)","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-192","number":"192","statement":"La decusación de las pirámides se produce en:","options":["El cerebro.","El diencéfalo.","El mesencéfalo.","La protuberancia.","El bulbo raquídeo."],"answer":4,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-125 / G0632 del banco canónico | integración: Tema 1.5.1 + Tema 1.7 + Tema 1.9.1 | archivos: Neuro_Parte3.pdf | referencias indicadas: wuolah-free-tema-3-preguntas.pdf / wuolah-free-Examen-Neuro-1 (1).pdf / wuolah-free-examenes-2011.pdf (Pregunta #1 - Decusación de las pirámides)","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-193","number":"193","statement":"El tracto ascendente que nace en la protuberancia y termina en el mesencéfalo (colículo inferior) formando parte de la vía auditiva se denomina:","options":["Lemnisco medial.","Lemnisco trigeminal.","Lemnisco espinal.","Lemnisco lateral."],"answer":3,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-126 / G0638 del banco canónico | integración: Tema 1.5.1 + Tema 1.11.2 | archivos: Neuro_Parte3.pdf | referencias indicadas: perguntas neuro julio exame.docx / Examem 2025 outro modelo juneka.pdf (Pregunta #54 - Vía Auditiva / Lemniscos)","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-194","number":"194","statement":"Señale la relación CORRECTA sobre los núcleos del tronco del encéfalo:","options":["Núcleo salivar inferior — Control vasomotor lacrimal.","Núcleo olivar inferior — Origen de fibras eferentes (trepadoras) al cerebelo.","Colículo inferior — Reflejos visuales.","Núcleo grácil — Relevo de información nociceptiva de las extremidades inferiores."],"answer":1,"explanation":"[Nota de la clave] O núcleo olivar inferior projeta axônios que cruzam a linha média e entram no cerebelo pelo pedúnculo cerebeloso inferior como fibras trepadoras).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-127 / G0639 del banco canónico | integración: Tema 1.5.1 + Tema 1.9.3 | archivos: Neuro_Parte3.pdf | referencias indicadas: examenes neuro compl (1).pdf / 10-30 Clase magistral_ Neuroanatomía meníngea2022 (Pregunta #55 - Núcleos do Tronco)","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-195","number":"195","statement":"En los núcleos olivares inferiores del bulbo raquídeo:","options":["Se releva información auditiva hacia la corteza cerebral.","Se releva información auditiva hacia el tálamo.","Se releva información de los propioceptores de músculos y articulaciones hacia el cerebelo (a través de las fibras trepadoras).","Se origina el tracto corticoespinal lateral."],"answer":2,"explanation":"[Nota de la clave] Hack de Inversão Olivar: A oliva INFERIOR no bulbo envia axônios ao cerebelo como fibras trepadoras. A informação auditiva passa pela oliva SUPERIOR na protuberância).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-128 / G0640 del banco canónico | integración: Tema 1.5.1 + Tema 1.9.3 + Tema 1.11.2 | archivos: Neuro_Parte3.pdf | referencias indicadas: wuolah-free-tema-3-preguntas.pdf / ex. 2 (respuestas).pdf / TEMA 3 – TRONCO DEL ENCÉFALO.pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-196","number":"196","statement":"Señale la afirmación INCORRECTA en relación a la sustancia blanca del tronco del encéfalo:","options":["Lemnisco medial — discurre contralateralmente al origen de la información del circuito del que forma parte.","Cuerpo trapezoide — espacio entre los núcleos pontinos ocupado por fibras procedentes de los núcleos cocleares que decusan.","Tracto corticoespinal — a nivel de la protuberancia, lo encontramos en la parte posterior de dicha estructura, adyacente a la línea media sagital.","Fascículos cuneiforme y grácil — no aparecen a nivel de la protuberancia ni del mesencéfalo."],"answer":2,"explanation":"[Nota de la clave] É a INCORRETA pois, a nível da protuberância, o trato corticoespinal desce pela região ANTERIOR / basilar, entremeado pelos núcleos pontinos).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-129 / G0641 del banco canónico | integración: Tema 1.5.1 + Tema 1.9.1 | archivos: Neuro_Parte3.pdf | referencias indicadas: ex. 2021 (respuestas).pdf / examenes neuro compl (1).pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-197","number":"197","statement":"Los núcleos grácil y cuneiforme se caracterizan por:","options":["Formar parte de la vía espinotalámica para la temperatura y el dolor.","Recibir información somatosensitiva de propiocepción consciente, tacto epicrítico y vibración de las extremidades inferiores (grácil) y superiores (cuneiforme).","Localizarse en la superficie anterior del tegmento mesencefálico.","Proyectar axones que forman el lemnisco lateral hacia el colículo inferior."],"answer":1,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-130 / G0642 del banco canónico | integración: Tema 1.5.1 + Tema 1.10 | archivos: Neuro_Parte3.pdf | referencias indicadas: PREGUNTAS-EXAMEN-DE-NEURO.pdf / wuolah-free-tema-3- preguntas.pdf / Tema 1.5.1 - Tronco del encéfalo 25-26.pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-198","number":"198","statement":"Respecto a los núcleos pontinos ubicados en la región ventral de la protuberancia, señale la afirmación CORRECTA:","options":["Son la principal vía de entrada o relevo de información motora desde la corteza cerebral hacia el cerebelo (vía corticopontocerebelosa).","Sintetizan noradrenalina para mantener la atención durante el sueño.","Proyectar axones directamente hacia la médula espinal formando el tracto rubroespinal.","Se originan embriológicamente de la placa basal pero migran hacia el tectum."],"answer":0,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-131 / G0645 del banco canónico | integración: Tema 1.5.1 + Tema 1.7 + Tema 1.9.3 | archivos: Neuro_Parte3.pdf | referencias indicadas: ex. 2 (respuestas).pdf / examenes neuro compl (1).pdf / Tema 1.5.1 - Tronco del encéfalo 25-26.pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-199","number":"199","statement":"En un corte transversal del mesencéfalo, ¿qué estructura redondeada y altamente vascularizada se ubica en el tegmento, entre el acueducto cerebral y la sustancia negra, dando origen al tracto rubroespinal?:","options":["Núcleo rojo.","Núcleo de Edinger-Westphal.","Núcleo centromediano.","Núcleo olivar superior."],"answer":0,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-132 / G0646 del banco canónico | integración: Tema 1.5.1 + Tema 1.9.1 + Tema 1.9.2 | archivos: Neuro_Parte3.pdf | referencias indicadas: 12-05 Clase_ Núcleos Basales - Terminología y Anatomía.mp / 12-04 Clase magistral_ Tracto corticoespinal","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-200","number":"200","statement":"¿En qué estructura del tronco del encéfalo se encuentra el complejo olivar superior, involucrado en el procesamiento auditivo binaural y la localización de fuentes sonoras?:","options":["Bulbo raquídeo.","Protuberancia (puente).","Mesencéfalo.","Diencéfalo."],"answer":1,"explanation":"[Nota de la clave] Diferença Crucial de Exame: A oliva INFERIOR está no BULBO; a oliva SUPERIOR está na PROTUBERÂNCIA).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-133 / G0647 del banco canónico | integración: Tema 1.5.1 + Tema 1.11.2 | archivos: Neuro_Parte3.pdf | referencias indicadas: 01-07 Clase_ Propiedades del Sonido y Percepción Auditiva.mp / examenes neuro compl (1).pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-201","number":"201","statement":"Seleccione la afirmación CORRECTA sobre las estructuras del tronco del encéfalo y sus vías:","options":["Las fibras tectoespinales originan el lemnisco medial.","Las fibras arciformes internas originan el lemnisco lateral.","Las pirámides del bulbo raquídeo llevan información propioceptiva.","En el nivel de la oliva inferior se encuentra la entrada/origen aparente del nervio vago (X).","El nervio facial describe un giro alrededor del núcleo del tracto solitario."],"answer":3,"explanation":"Desmonte da Armadilha: As fibras arciformes internas originam o lemnisco medial; as pirâmides levam informação motora/corticoespinal; e a alça/joelho do nervio facial contorna o núcleo do nervio abducens VI, elevando o colículo facial no soalho do IV ventrículo).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-134 / G0649 del banco canónico | integración: Tema 1.5.1 + Tema 1.5.2 + Tema 1.10 | archivos: Neuro_Parte3.pdf | referencias indicadas: wuolah-free-Examen-Neuro-3.pdf / Preguntas temas 3,4,5,6.pdf / TEMA 3 – TRONCO DEL ENCÉFALO.pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-202","number":"202","statement":"Señale la relación CORRECTA sobre los núcleos y áreas del tronco del encéfalo:","options":["Núcleos del Rafe — Localizados en la franja lateral de la protuberancia y mesencéfalo.","Núcleo olivar inferior — Relacionado con la localización de la fuente sonora en el plano horizontal.","Núcleo de Edinger-Westphal — Localizado en el mesencéfalo, próximo al acueducto cerebral.","Área tegmental ventral — Componente del sistema motor extrapiramidal ubicado en el bulbo raquídeo."],"answer":2,"explanation":"Hack de Inversão Olivar da Professora Aitana: O núcleo olivar superior [na protuberância] é quem processa a localização sonora horizontal; o olivar inferior [no bulbo] projeta ao cerebelo como fibras trepadoras).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-135 / G0650 del banco canónico | integración: Tema 1.5.1 + Tema 1.5.2 + Tema 1.9.3 | archivos: Neuro_Parte3.pdf | referencias indicadas: examenes neuro compl (1).pdf / perguntas neuro julio exame.docx","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-203","number":"203","statement":"Indica la afirmación FALSA sobre el tronco del encéfalo:","options":["En el bulbo raquídeo surgen las fibras arciformes internas.","En un corte a nivel de la protuberancia podemos encontrar el núcleo de la oliva superior.","Los núcleos pontinos son ventrales con respecto al núcleo prepósito de la protuberancia.","El lemnisco lateral surge en el bulbo raquídeo y asciende hasta el colículo inferior."],"answer":3,"explanation":"Hack de Origem de Lemniscos: É a FALSA pois o lemnisco lateral origina-se na protuberância a partir do corpo trapezoide e do complexo olivar superior, ascendendo até o colículo inferior do mesencéfalo).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-136 / G0651 del banco canónico | integración: Tema 1.2 + Tema 1.5.1 | archivos: Neuro_Parte3.pdf | referencias indicadas: examenes neuro compl (1).pdf / Preguntas temas 3,4,5,6.pdf / TEMA 16 – EMBRIOLOGÍA.pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-204","number":"204","statement":"Los núcleos grácil y cuneiforme localizados en la región posterior del bulbo raquídeo se caracterizan por:","options":["Ser parte directa de la vía espinotalámica lateral para el dolor y temperatura.","Formar parte del tracto espinocerebeloso anterior.","Recibir aferencias de propiocepción consciente, tacto epicrítico y vibración del cordón posterior.","Proyectar axones que forman el lemnisco lateral hacia el colículo inferior."],"answer":2,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-137 / G0654 del banco canónico | integración: Tema 1.5.1 + Tema 1.10 | archivos: Neuro_Parte3.pdf | referencias indicadas: wuolah-free-PREGUNTAS-EXAMEN-DE-NEURO.pdf / TEMA 3 – TRONCO DEL ENCÉFALO.pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-205","number":"205","statement":"La fosa romboidea:","options":["Es una depresión en forma de rombo que constituye el techo del cuarto ventrículo.","Se forma en la superficie dorsal del mesencéfalo.","Se encuentra limitada lateralmente por los pedúnculos cerebelosos.","Contiene exclusivamente núcleos motores de los nervios craneales."],"answer":2,"explanation":"[Nota de la clave] Pegadinha Teto vs. Soalho: A fossa romboide constitui o soalho (suelo) do 4º ventrículo, não o teto).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-138 / G0655 del banco canónico | integración: Tema 1.5.1 + Tema 1.9.3 | archivos: Neuro_Parte3.pdf; NEURO_275_ORGANIZADO_POR_TEMA_HACK24(1).pdf; NEURO_275_CRONOLOGICO_MARCADORES_FUNCIONAIS.pdf | referencias indicadas: Examem 2025 outro modelo juneka.pdf / perguntas neuro julio exame.docx / TEMA 3 – TRONCO DEL ENCÉFALO.pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-206","number":"206","statement":"Desde el punto de vista del desarrollo embrionario del tronco del encéfalo, ¿cuál de los siguientes núcleos se origina en la placa alar (sensorial) pero migra ventralmente hasta ocupar su posición definitiva en la región basilar de la protuberancia?:","options":["Núcleos pontinos.","Núcleo motor del trigémino.","Núcleo del nervio abducens.","Núcleo Edinger-Westphal."],"answer":0,"explanation":"[Nota de la clave] Hack de Exceção Embriológica: A professora Aitana reforça que os núcleos pontinos nascem na placa alar [sensitiva], mas migram para a região basal [motora/ventral] da protuberância).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-139 / G0657 del banco canónico | integración: Tema 1.2 + Tema 1.5.1 | archivos: Neuro_Parte3.pdf | referencias indicadas: 10-30 Clase magistral_ Neuroanatomía meníngea / TEMA 16 – EMBRIOLOGÍA.pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-207","number":"207","statement":"Sobre el tronco del encéfalo es FALSA la siguiente afirmación:","options":["Los tubérculos gráciles se encuentran a ambos lados de la fisura media posterior del bulbo raquídeo.","La protuberancia contiene los núcleos de los nervios craneales V, VI, VII y VIII.","Los colículos superiores están involucrados en la integración de la información auditiva.","La sustancia negra se encuentra en el tegmento/pedúnculos del mesencéfalo."],"answer":2,"explanation":"[Nota de la clave] Hack Visual vs. Auditivo: É a FALSA pois os colículos superiores processam reflexos visuais e oculomotores; a via auditiva realiza relevo nos colículos inferiores).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-140 / G0658 del banco canónico | integración: Tema 1.5.1 + Tema 1.11.2 | archivos: Neuro_Parte3.pdf | referencias indicadas: perguntas neuro julio exame.docx (Pregunta #15) / examenes neuro compl (1).pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-208","number":"208","statement":"Indica la afirmación VERDADERA sobre la participación del tronco del encéfalo en el control motor:","options":["No participa en aspectos automáticos del control locomotor.","Los estímulos vestibulares y propioceptivos son necesarios para el mantenimiento de la postura y el equilibrio mediante núcleos del tronco encefálico.","Los centros motores del tronco del encéfalo no tienen relación alguna con el cerebelo.","Los centros ubicados en el tronco del encéfalo no pueden ser modulados por la corteza cerebral."],"answer":1,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-141 / G0659 del banco canónico | integración: Tema 1.5.1 + Tema 1.11.2 | archivos: Neuro_Parte3.pdf | referencias indicadas: wuolah-free-tema-3-preguntas.pdf / ex. 2 (sin respuestas) (1, 2, 3 y 16).pdf (Pregunta #43)","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-209","number":"209","statement":"Una paciente presenta una extensión tónica de las extremidades inferiores junto con una flexión tónica de las extremidades superiores (postura de decorticación). ¿En qué nivel del tronco del encéfalo se sitúa la lesión para explicar esta presentación clínica?:","options":["Por encima del núcleo rojo (lesión suprarrubral).","Por debajo del núcleo rojo (postura de descerebración / infrarrubral).","En la corteza auditiva primaria.","En el cordón posterior de la médula lumbar."],"answer":0,"explanation":"Hack de Lesão Clínica Suprarrubral vs. Infrarrubral: Lesões acima do núcleo vermelho preservam a via rubroespinal, que flete os braços [decorticación]. Lesões abaixo do núcleo vermelho interrompem a rubroespinal e deixam os estímulos vestíbulo-espinais sem oposição, provocando extensão de todos os membros [descerebración]).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-142 / G0661 del banco canónico | integración: Tema 1.5.1 + Tema 1.9.1 | archivos: Neuro_Parte3.pdf | referencias indicadas: wuolah-free-Examen-Neuro-2.pdf (Pregunta #30) / 12-05 Clase magistral_ Tractos extrapiramidales","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-210","number":"210","statement":"¿Cuál de las siguientes vías o tractos motores descendentes se origina en los colículos superiores del mesencéfalo y participa en los movimientos reflejos de la cabeza y cuello en respuesta a estímulos visuales?:","options":["Tracto tectoespinal.","Tracto rubroespinal.","Tracto vestibuloespinal lateral.","Tracto reticuloespinal medular."],"answer":0,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-143 / G0662 del banco canónico | integración: Tema 1.5.1 + Tema 1.9.1 | archivos: Neuro_Parte3.pdf | referencias indicadas: wuolah-free-tema-3-preguntas.pdf / TEMA 3 – TRONCO DEL ENCÉFALO.pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-211","number":"211","statement":"El tracto tegmental central es una importante vía de conducción en el tronco del encéfalo que lleva axones descendentes procedentes del núcleo rojo y ganglios basales dirigidos específicamente hacia:","options":["El complejo olivar inferior en el bulbo raquídeo.","El núcleo grácil.","La corteza visual primaria.","El asta posterior de la médula espinal."],"answer":0,"explanation":"No incluida en el material.","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-144 / G0663 del banco canónico | integración: Tema 1.5.1 + Tema 1.9.2 | archivos: Neuro_Parte3.pdf | referencias indicadas: 09-25 Clase_ Neuroanatomía del Mesencéfalo / TEMA 3 – TRONCO DEL ENCÉFALO.pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"},{"id":"neuro20261004-1.5.1-212","number":"212","statement":"Indica la asociación INCORRECTA sobre las siguientes estructuras troncoencefálicas:","options":["Núcleos cocleares — ubicados en la protuberancia, forman parte de la vía auditiva.","Núcleos pontinos — relevo de información entre la corteza cerebral y la médula espinal.","Núcleos del rafe — sistema serotoninérgico responsable de la regulación del ciclo sueño-vigilia y modulación del dolor.","Lemnisco lateral — tracto que nace en la protuberancia y llega al colículo inferior."],"answer":1,"explanation":"Hack de Inversión de Destino: É a INCORRETA/FALSA porque os núcleos pontinos [localizados na região basilar da protuberância] recebem aferências da corteza cerebral e projetam axônios através dos pedúnculos cerebelosos médios rumo ao CEREBELO [vía corticopontocerebelosa], e NÃO para a médula espinal).","hack":"No incluido en el material.","source":"Neurociencias – Tema 1.5.1 - TRONCO DEL ENCÉFALO | entrada I-145 / G0664 del banco canónico | integración: Tema 1.4 + Tema 1.5.1 + Tema 1.7 + Tema 1.9.3 | archivos: Neuro_Parte3.pdf | referencias indicadas: ex. 2 (respuestas).pdf (Pregunta #14) / wuolah-free-Examen-Neuro- recu-junio-2023 orc.pdf / examenes neuro compl (1).pdf","topic":"1.5.1","document":"01-TEMA_1-4.TXT","subject":"MEFOS"}]);